Ceviri.ekle("bn","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["হাদরামাউত অটোমান সানজাক হল — অভ্যন্তরীণ শাসন কাসিরি প্রধানদের হাতে থাকল", "d80f8d20"], "d": ["হাদিম সুলেমান পাশার ভারত অভিযানের সময় অটোমান শাসনে আসা হাদরামাউত ইয়েমেনের অধীন সানজাক হিসেবে সংগঠিত হয়। তবে হাদরামাউতের ভেতরে শাসন কার্যত কাসিরি গোত্রপ্রধানদের হাতেই ছিল; অটোমান কর্তৃত্ব উপকূল ও করের বন্ধনে সীমিত থাকে।", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["জায়দি ইমাম মুতাওয়াক্কিল আলাল্লাহ হাদরামাউত আক্রমণ করলেন — কাসিরি সুলতানাত ইয়েমেন ইমামতের অধীন হল", "21ad9c85"], "d": ["1635 সালে অটোমানদের ইয়েমেন ছেড়ে যাওয়ার পর শক্তিশালী হওয়া জায়দি ইমামত ইমাম মুতাওয়াক্কিল আলাল্লাহর আমলে সেনা পাঠিয়ে হাদরামাউত আক্রমণ করে। কাসিরিদের অভ্যন্তরীণ হাদরামাউতে কর্তৃত্ব এভাবে প্রায় অর্ধশতক ইয়েমেন ইমামতের অধীন থাকে; অষ্টাদশ শতকের প্রথমার্ধে ইমাম ও কাসিরিদের প্রভাব দুর্বল হলে শাসন আবার স্থানীয় গোত্রগুলোর হাতে যায়।", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["আবদুল্লাহ ইবন রাশিদ হাইল আমিরাত ইবন আলি পরিবারের কাছ থেকে নিলেন — শাম্মার (রাশিদি) আমিরাত প্রতিষ্ঠিত", "357cc1a0"], "d": ["শাম্মার গোত্রের সবচেয়ে বড় শাখা আবদা-র সদস্য আবদুল্লাহ ইবন রাশিদ ভাই উবায়দের সঙ্গে হাইল শাসনকারী ইবন আলি পরিবারের বিরুদ্ধে শুরু করা লড়াই 1835 সালে জিতে আমিরাত দখল করেন। মেসোপটেমিয়া-হেজাজ বাণিজ্য ও হজপথে অবস্থানের কারণে হাইল রাশিদিদের 1921 পর্যন্ত চলা জাবাল শাম্মার কর্তৃত্বের কেন্দ্র হয়ে ওঠে।", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["অটোমান বেগলিকের প্রতিষ্ঠা", "9f0b7c0a"], "d": ["কায়ি গোত্রের ওসমান গাজির সোগুত-দোমানিচ অঞ্চলে স্বাধীনভাবে চলতে শুরু করা অটোমান রাষ্ট্রের প্রতিষ্ঠার ঐতিহ্যগত সূচনা বলে গণ্য হয়; কিছু ইতিহাসবিদ 1302 সালের বাফেউস বিজয়কে প্রকৃত মোড় মনে করেন। বেগলিক বাইজেন্টাইন সীমান্ত অঞ্চলে অবস্থানের সুবিধায় গাজা অভিযানের মাধ্যমে দ্রুত শক্তি সঞ্চয় করল। সেলজুক উত্তরাধিকার ভেঙে পড়ার এই পরিবেশে ওসমান গাজির চারপাশে আখি, গাজি ও যাযাবর তুর্কমেনরা জড়ো হলো; শেখ এদেবালির সঙ্গে গড়া বন্ধন বেগলিকের আধ্যাত্মিক বৈধতার ভিত্তি গণ্য হয়। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: ইনেগোল, ইয়ারহিসার।", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["বুরসার বিজয়", "98c727fa"], "d": ["বছরের পর বছর অবরুদ্ধ বুরসা অবরোধের শেষ পর্যায় পরিচালনাকারী ওরহান গাজির কাছে আত্মসমর্পণ করল; শহর বেগলিকের প্রথম বড় রাজধানী হলো। বিজয়ের খবর মৃত্যুশয্যায় ওসমান গাজির কাছে পৌঁছানো হয়েছিল বলে জনশ্রুতি আছে; ওসমান গাজি তাঁর ওসিয়ত অনুযায়ী বুরসায় সমাহিত হলেন। শহর অল্প সময়ে মসজিদ, ইমারত (দাতব্য রান্নাঘর) ও মাদ্রাসায় সজ্জিত হয়ে প্রাথমিক অটোমান নগরায়নের মডেলে পরিণত হলো।", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["ইজনিকের বিজয়", "a846a811"], "d": ["আনাতোলিয়ায় বাইজেন্টাইনদের সবচেয়ে গুরুত্বপূর্ণ কেন্দ্রগুলোর একটি ইজনিক (নিসিয়া) 1329 সালের পেলেকানন বিজয়ের পর প্রতিরোধের আশা হারিয়ে ওরহান গাজির কাছে আত্মসমর্পণ করল। প্রথম অটোমান মাদ্রাসা এখানে স্থাপিত হলো এবং দাউদ-ই কায়সারির মতো আলেমরা পাঠদান শুরু করলেন; শহর প্রাথমিক যুগের জ্ঞানকেন্দ্র হলো। আয়াসোফিয়া গির্জা মসজিদে রূপান্তরিত হয়ে বিজয় ঐতিহ্যের একটি প্রাথমিক উদাহরণ দেখা গেল।", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["ইজমিতের বিজয়", "06a35035"], "d": ["ইজমিতের (নিকোমিডিয়া) পতনে বাইজেন্টাইনদের আনাতোলীয় তীরের শেষ গুরুত্বপূর্ণ দুর্গও অটোমান শাসনে এলো; ইস্তানবুলের বিপরীত তীর পর্যন্ত পুরো কোজাএলি উপদ্বীপ অটোমান ভূমি হলো। এভাবে বেগলিক মারমারার দক্ষিণ ও পূর্ব উপকূলের পুরোটায় কর্তৃত্ব স্থাপন করে রুমেলিতে উত্তরণের ভিত্তি প্রস্তুত করল।", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["চিম্পে দুর্গ — রুমেলিতে উত্তরণ", "c2f0a07d"], "d": ["ওরহান গাজির পুত্র সুলেইমান পাশা বাইজেন্টাইন গৃহযুদ্ধে প্রদত্ত চিম্পে দুর্গ 1352 সালে ঘাঁটি করেছিলেন; মার্চ 1354-এ গালিপোলি ধ্বংসকারী বড় ভূমিকম্পের পর খালি হওয়া দুর্গগুলো দ্রুত সুরক্ষিত করে উপদ্বীপকে স্থায়ী অটোমান সেতুমুখে পরিণত করা হয়েছিল। আনাতোলিয়া থেকে আনা তুর্কমেন জনগোষ্ঠীর বসতি স্থাপনে সমর্থিত এই পদক্ষেপ ইউরোপ মহাদেশে অটোমানদের 550 বছরের বেশি স্থায়ী উপস্থিতির সূচনা।", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["এডির্নের বিজয়", "2f54ebb0"], "d": ["থ্রেসের মূল শহর এডির্ন (আদ্রিয়ানোপোলিস) দখল বলকান বিজয়ের প্রধান ঘাঁটি ও দিক নির্ধারণ করল; বিজয়ের তারিখ সূত্রে 1361 ও 1369-এর মধ্যে বিতর্কিত। শহর অল্প পরে রাজধানী করা হয়ে রাষ্ট্রের ভারকেন্দ্র রুমেলিতে সরে যাওয়ার ঘোষণা দিল; ইস্তানবুল বিজয় পর্যন্ত প্রায় 90 বছর রাজধানী রইল।", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["প্রথম মুরাদ সিংহাসনে বসলেন", "f8d48a26"], "d": ["ওরহান গাজির মৃত্যুতে সিংহাসনে বসা প্রথম মুরাদ (হুদাভেন্দিগার) তাঁর 27 বছরের সালতানাতে রাষ্ট্রকে সীমান্ত বেগলিক থেকে সাম্রাজ্যের কাঠামোয় উন্নীত করলেন। পেনচিক ব্যবস্থায় জানিসারি বাহিনীর ভিত্তি স্থাপিত হলো, তিমার ব্যবস্থা ছড়িয়ে পড়ল, রুমেলি বেইলারবেইলিক প্রতিষ্ঠিত হলো এবং উজিরের প্রতিষ্ঠান শক্তিশালী হলো। বলকান বিজয় তাঁর আমলে পদ্ধতিগত রাষ্ট্রীয় নীতিতে পরিণত হলো।", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["প্রথম কসোভো যুদ্ধ — প্রথম মুরাদের শাহাদাত", "10b8ddc9"], "d": ["নেজ লাজারের নেতৃত্বাধীন বলকান জোট কসোভো সমভূমিতে চূড়ান্তভাবে পরাজিত হলো; সার্বিয়া অটোমান উচ্চ আধিপত্যে এলো। রণক্ষেত্র ঘুরে দেখা প্রথম মুরাদ সার্বীয় অভিজাত মিলোশ ওবিলিচের ছুরিকাঘাতে শহীদ হলেন — রণক্ষেত্রে নিহত একমাত্র অটোমান সুলতান। তাঁর জায়গায় শিবিরে ইলদিরিম বায়েজিদকে বসানো হলো; ভাই ইয়াকুব চেলেবিকে শ্বাসরোধে হত্যা করা হলো, যা ভ্রাতৃহত্যা প্রথার জানা প্রথম উদাহরণগুলোর একটি।", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["নিকোপোলের বিজয়", "75716e96"], "d": ["হাঙ্গেরির রাজা সিগিসমুন্ডের আহ্বানে জড়ো হওয়া এবং ফরাসি-বার্গান্ডিয়ান নাইটরাও যোগ দেওয়া বড় ক্রুসেডার সেনাবাহিনী দানিউবের তীরে নিকোপোলের সামনে ইলদিরিম বায়েজিদের হাতে ভারী পরাজয় বরণ করল। বিজয় বুলগেরিয়ার ওপর অটোমান আধিপত্য নিশ্চিত করল; ইউরোপে এক প্রজন্ম ধরে বড় ক্রুসেড সংগঠিত হয়নি।", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["আঙ্কারা যুদ্ধ — ফেত্রেত যুগ শুরু", "b4a99d96"], "d": ["তিমুরের বাহিনীর বিরুদ্ধে চুবুক সমভূমিতে ভারী পরাজয়ে ইলদিরিম বায়েজিদ বন্দি হলেন এবং কয়েক মাস পর বন্দিদশায় মারা গেলেন। তিমুর আনাতোলীয় বেগলিকগুলো পুনরুজ্জীবিত করলেন; অটোমান ভূখণ্ড বায়েজিদের পুত্রদের মধ্যে খণ্ডবিখণ্ড হলো এবং 11 বছরের সিংহাসন-সংগ্রাম (ফেত্রেত যুগ) শুরু হলো। রাষ্ট্র প্রতিষ্ঠার পর থেকে সবচেয়ে ভারী সংকটের এই যুগ কেন্দ্রীভূত কাঠামোর গুরুত্ব অটোমান স্মৃতিতে খোদাই করল। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: দাত্চা, মারমারিস, ফেথিয়ে (Makri), সোকে, কুতাহিয়া, আফিয়ন, ইসপার্তা, মানিসা, আইদিন, দেনিজলি, মুগলা, আন্তালিয়া, কোনিয়া, কারামান, কাইসেরি, কাস্তামোনু, বার্তিন, সাফরানবোলু, সামসুন, সিভাস, মালাত্যা, বেইশেহির, সিভরিহিসার, কিরশেহির, চোরুম, চানকিরি, ইয়েনিশেহির (বুরসা), ইনেগোল, আয়দোস দুর্গ, গেইভে, কোপ্রুহিসার (ইয়েনিশেহির), Marmaracık, আকহিসার (পামুকোভা), মেকেজে, কেস্তেল, উলুবাত, Harmankaya, আকইয়াজি, ইমরালি দ্বীপ, কান্দিরা, মুদানিয়া, ইয়ালোভা, কারামুরসেল, আরমুতলু, জেমলিক (Kios), সোগুত, বিলেজিক, এসকিশেহির, বুরসা, ইজনিক, ইজমিত, বালিকেসির, চানাক্কালে, বেরগামা, আমাসিয়া, তোকাত, চোরলু, লুলেবুরগাজ, মালকারা, কেশান, ইপসালা, কিলিতবাহির, চির্মেন, স্তারা জাগোরা (Stara Zagora), পাজারজিক, ইহতিমান, কিউস্তেন্দিল, পেত্রিচ, নেভ্রোকোপ (Gotse Delçev), দ্রামা, গালিপোলি, চিম্পে, এডির্ন, দিদিমোতিখো, কিরক্লারেলি, তেকিরদাগ, ফিলিবে, সোফিয়া, নিশ, ভিদিন, তার্নোভো, ভার্না, শুমেন, সিলিস্ত্রা, নিকোপোল, রুসে, থেসালোনিকি, সেরেস, কাভালা, ইউস্কুপ, মানাস্তির, ওহরিড, ইয়েনিশেহির (লারিসা), ত্রিকালা, ইজদিন (লামিয়া), প্লেভেন, গুমুলজিনা, বিগা, দোমানিচ, কুলাজাহিসার, কারাজাহিসার, ইয়ারহিসার, দিম্বোস, কিতে (Kete), লেফকে (ওসমানেলি), লেবলেবিজিহিসার, কারাচেপুশ, কারাতিগিন, আবসু (Hypsu), আদ্রানোস (ওরহানেলি), পেলেকানন (এসকিহিসার), গেবজে, হেরেকে, সামান্দিরা, কিরমাস্তি (M.Kemalpaşa), মিহালিচ (কারাজাবে), কনস্তান্তা, গোলিয়াজি (Apollonia)।", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["চেলেবি মেহমেদ ঐক্য পুনঃপ্রতিষ্ঠা করলেন", "03413dfd"], "d": ["ভাইদের মধ্যে শেষ হিসাব-নিকাশে চামুরলুতে মুসা চেলেবিকে পরাজিতকারী প্রথম মেহমেদ দেশের ভূখণ্ড এক শাসনের অধীনে একত্র করলেন; তাই তিনি 'রাষ্ট্রের দ্বিতীয় প্রতিষ্ঠাতা' গণ্য হন। তাঁর সালতানাতে ক্ষয়ে যাওয়া রাষ্ট্রকাঠামো মেরামত হলো, আনাতোলীয় বেগলিকগুলোর সঙ্গে সম্পর্ক ভারসাম্যে এলো এবং রুমেলিতে সতর্ক শান্তিনীতি অনুসরণ করা হলো।", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["শেখ বেদরেদ্দিনের বিদ্রোহ", "e0a072ca"], "d": ["ফেত্রেত যুগে কাজিআস্কার পদে থাকা মহান ফকিহ ও সুফি শেখ বেদরেদ্দিনকে ঘিরে গড়ে ওঠা ধর্মীয়-সামাজিক আন্দোলন কারাবুরুনে বর্কলুজে মুস্তাফা ও মানিসায় তোরলাক কেমালের বিদ্রোহের সঙ্গে একযোগে ফেটে পড়ল। বিদ্রোহ রক্তাক্তভাবে দমন করা হলো; বেদরেদ্দিন দেলিওরমানে ধরা পড়ে সেরেসে মৃত্যুদণ্ড পেলেন। ঘটনাটি অটোমান ইতিহাসের সবচেয়ে প্রাচীন বড় সামাজিক-মাহদিবাদী বিদ্রোহ হিসেবে সাহিত্য ও ইতিহাস রচনায় গভীর ছাপ ফেলল।", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["ভার্না বিজয়", "f739eedc"], "d": ["সেগেদিন চুক্তি ভেঙে দক্ষিণে নামা হাঙ্গেরীয়-পোলিশ ক্রুসেডার বাহিনী সিংহাসন ছেড়ে দেওয়ার পর আবার সেনাবাহিনীর শীর্ষে ফেরা দ্বিতীয় মুরাদের হাতে ভার্নায় বিনষ্ট হলো; তরুণ রাজা তৃতীয় লাদিস্লাউস রণক্ষেত্রে নিহত হলেন। বিজয় বলকানে অটোমান উপস্থিতি মুছে ফেলার শেষ বড় বহিঃহস্তক্ষেপের সুযোগ নিশ্চিহ্ন করল এবং ইস্তানবুল বিজয়ের পথ নিশ্চিত করল।", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["দ্বিতীয় কসোভো যুদ্ধ", "ebe0b662"], "d": ["ভার্নার প্রতিশোধ নিতে চাওয়া হুন্যাদি ইয়ানোশের সেনাবাহিনী তিন দিনের কঠিন লড়াইয়ে দ্বিতীয় মুরাদের হাতে চূড়ান্তভাবে পরাজিত হলো। এটি ক্রুসেডারদের বলকানে অটোমানদের বিরুদ্ধে চালানো শেষ বড় রণক্ষেত্রের যুদ্ধ; বিজয়ে দানিউবের দক্ষিণে অটোমান আধিপত্য আর ফেরানো যায় না এমনভাবে স্থায়ী হলো।", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["কনস্টান্টিনোপলের বিজয়", "583d5e3e"], "d": ["চুয়ান্ন দিন (6 এপ্রিল–29 মে 1453) স্থায়ী অবরোধের পর 29 মে সকালে প্রাচীর পেরোনো অটোমান সেনাবাহিনী শহরে প্রবেশ করল; শেষ সম্রাট একাদশ কনস্টান্টিনোস লড়াইয়ে নিহত হলেন এবং 1100 বছরের পূর্ব রোমান সাম্রাজ্য ইতিহাসে বিলীন হলো। তরুণ সুলতান 'ফাতিহ' (বিজেতা) উপাধি নিলেন, শহরকে রাজধানী করে আয়াসোফিয়াকে মসজিদে রূপান্তর করলেন; শহর অল্প সময়ে বসতি ও নির্মাণে পুনরুজ্জীবিত হলো। TDV অনুযায়ী সিলিভ্রি ও ভিজে কেবল 1453 সালে চূড়ান্তভাবে বিজিত হয়েছে; TDV লিমনোস নিবন্ধ অনুযায়ী দ্বীপ বিজয়ের অব্যবহিত পরে অটোমান প্রশাসনে এলো এবং কর দেওয়ার শর্তে গাত্তিলুসিও পরিবারকে ছেড়ে দেওয়া হলো। অ্যাটলাসে সিলিভ্রি, ভিজে ও লিমনোস এই দিন থেকে বাইজেন্টাইনদের থেকে অটোমানদের নামে (লিমনোস করদ) লেখা। বিশাল কামান ঢালাই, জাহাজ স্থলপথে চালানো ও প্রাচীরের সামনে অবরোধ বিন্যাস সে যুগের সামরিক প্রকৌশলের শিখর গণ্য হয়। বিজয় ইউরোপীয় ইতিহাস রচনায় মধ্যযুগের সমাপ্তির প্রতীক তারিখগুলোর একটি।", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["ত্রাবজোনের বিজয়", "15f52403"], "d": ["ফাতিহের সেনাবাহিনী ও নৌবহর একযোগে চালানো কঠিন কৃষ্ণ সাগর অভিযানের শেষে ত্রাবজোন গ্রিক সাম্রাজ্য আত্মসমর্পণ করল; আনাতোলিয়ায় বাইজেন্টাইন জগতের এই শেষ অবশেষ বিলুপ্ত হওয়ায় কৃষ্ণ সাগরের দক্ষিণ উপকূল সম্পূর্ণ অটোমান আধিপত্যে এলো। কমনেনোস রাজবংশের অবসান ফাতিহের 'দুই সাগর ও দুই মহাদেশের শাসক' দাবি দৃঢ় করল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: গিরেসুন, রিজে।", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["সিলিফকের চূড়ান্ত বিজয় — কারামানোগলুদের শেষ প্রতিরোধ ভাঙল", "d988bee4"], "d": ["সিলিফকে দুর্গ 1472 সালে একবার গেদিক আহমেদ পাশার কাছে আত্মসমর্পণ করেছিল, কিন্তু একই বছর কারামানোগলু কাসিম বে ভূমধ্যসাগরের ক্রুসেডার নৌবহরের সাহায্যে দুর্গ ফিরিয়ে নিয়েছিলেন। ওতলুকবেলি বিজয়ের পর ফাতিহ পুত্র ও গেদিক আহমেদ পাশাকে অঞ্চল চূড়ান্তভাবে দখলের দায়িত্ব দিলেন; পুরোনো অটোমান কামানবাহিনীর সাহায্যে বারুদ ভাণ্ডারে আগুন দিয়ে দুর্গ দ্রুত পতিত হলো। এভাবে কারামানোগলুদের তাশেলি-ইচেল পাহাড়ে শেষ প্রতিরোধ ভাঙল; বেগলিকের বিলুপ্তি 1474 সালে সম্পূর্ণ হবে।", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["ওতলুকবেলির যুদ্ধ", "42c7194e"], "d": ["পূর্বে বড় শক্তি হয়ে ওঠা এবং ভেনিসের সঙ্গে মৈত্রী গড়া আকক্কোইউনলু শাসক উজুন হাসান ওতলুকবেলিতে ফাতিহের আগ্নেয়াস্ত্রে সজ্জিত সেনাবাহিনীর সামনে ভারী পরাজয় বরণ করলেন। বিজয় আনাতোলিয়ায় অটোমান প্রাধান্য নিশ্চিত করল; ধ্রুপদী সেনাবাহিনীর বিরুদ্ধে কামান ও বন্দুক ব্যবহারকারী কেন্দ্রীয় সেনাবাহিনীর শ্রেষ্ঠত্বের প্রাথমিক প্রমাণও হলো। TDV গুমুশহানে নিবন্ধ অনুযায়ী শহর 1467 থেকে আকক্কোইউনলু আধিপত্যে ছিল; এই আধিপত্য ওতলুকবেলি পরাজয়ে শেষ হলো এবং গুমুশহানে চূড়ান্তভাবে অটোমান আধিপত্যে গেল।", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["ক্রিমিয়ার অটোমান আশ্রয়ে আসা", "44e3f7c8"], "d": ["গেদিক আহমেদ পাশার নেতৃত্বাধীন নৌবহর জেনোয়ার হাতে থাকা কেফে (কাফা) সহ ক্রিমিয়ার দক্ষিণ উপকূলীয় শহরগুলো জয় করল; এই উপকূল সরাসরি অটোমান সানজাক করা হলো। ক্রিমিয়ান খানাত অবশ্য মেংলি গিরাইয়ের সঙ্গে অটোমান উচ্চ আধিপত্য স্বীকারকারী বিশেষাধিকারপ্রাপ্ত অধীনস্থ রাষ্ট্রে পরিণত হলো এবং তিন শতক উত্তরের রাজনীতির ভিত্তি রইল; কৃষ্ণ সাগর এখন কার্যত অটোমান অভ্যন্তরীণ সাগরে পরিণত হলো। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: বাখচিসারাই, কের্চ, আজভ।", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["ফাতিহের মৃত্যু — জেম সুলতান ঘটনা", "190ecf01"], "d": ["অভিযান পথে ফাতিহের আকস্মিক মৃত্যুতে দ্বিতীয় বায়েজিদ সিংহাসনে বসলেন; ভাই জেম সুলতান সালতানাতের দাবিতে বুরসায় নিজের নামে খুতবা পড়ালেন ও মুদ্রা ছাপালেন। পরাজিত হয়ে প্রথমে মামলুকদের, পরে রোডসের নাইটদের কাছে আশ্রয় নিলেন; নাইট ও পোপতন্ত্রের হাতে ইউরোপীয় কূটনীতির দর কষাকষির তাসে পরিণত জেম 1495 সালে নেপলসে মারা গেলেন। এই ঘটনা অটোমান পররাষ্ট্রনীতিকে পনেরো বছর সতর্ক আচরণে বাধ্য করল।", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["চালদিরান বিজয়", "fea64ebb"], "d": ["আনাতোলিয়ায় সাফাভি প্রচারণার সৃষ্ট হুমকি সমূলে মোকাবিলা করতে চাওয়া ইয়াভুজ সুলতান সেলিম শাহ ইসমাইলের সেনাবাহিনীকে চালদিরান সমভূমিতে কামান ও বন্দুকের প্রাধান্যে ভারী পরাজিত করলেন। তাবরিজে প্রবেশ করা হলো; পূর্ব ও দক্ষিণ-পূর্ব আনাতোলিয়া এবং মসুল-দিয়ারবাকির রেখা অটোমান শাসনে যুক্ত হলো। ইদ্রিস-ই বিতলিসির প্রচেষ্টায় কুর্দি বেগদের অটোমানদের সঙ্গে যুক্ত হওয়া শতাব্দীর পর শতাব্দী স্থায়ী পূর্ব সীমান্তের কাঠামো গড়ল।", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["মার্জ দাবিকের বিজয়", "07d254d3"], "d": ["মামলুক সেনাবাহিনী আলেপ্পোর উত্তরে মার্জ দাবিকে কয়েক ঘণ্টায় ছত্রভঙ্গ হলো; বৃদ্ধ সুলতান কানসুহ গাভরি যুদ্ধের সময় মারা গেলেন। আলেপ্পো ও দামেস্কের দরজা সম্পূর্ণ খুলে দেওয়া বিজয়ে সিরিয়া, লেবানন ও ফিলিস্তিন অটোমান শাসনে গেল; মামলুক রাষ্ট্রের অবসান ঘটানো মিসর অভিযানের পথ খুলল।", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["রিদানিয়া — মিসর বিজয় ও খিলাফত", "caf378d6"], "d": ["সিনাই মরুভূমি দ্রুত পেরোনো অটোমান সেনাবাহিনী রিদানিয়ায় তুমানবাইয়ের প্রতিরক্ষা রেখা ভেদ করে কায়রোয় প্রবেশ করল; প্রতিরোধ চালিয়ে যাওয়া তুমানবাই ধরা পড়ে মৃত্যুদণ্ড পেলেন এবং মামলুক রাষ্ট্র ইতিহাসে বিলীন হলো। মিসর, হিজাজ ও পবিত্র শহরগুলো অটোমান শাসনে এলো; আব্বাসীয় খলিফা ও পবিত্র নিদর্শনগুলো ইস্তানবুলে নিয়ে যাওয়া হলো। খিলাফত অটোমান রাজবংশে যাওয়ায় সুলতানরা ইসলামী বিশ্বের নেতৃত্বের দাবি গ্রহণ করলেন; মশলা পথের নিয়ন্ত্রণও সাম্রাজ্যকে বড় আয় দিল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: আক্কা, মা'আন, সাইদা, কেরাক।", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["কানুনি সুলতান সুলেইমান সিংহাসনে বসলেন", "f6512269"], "d": ["ইয়াভুজের মৃত্যুতে একমাত্র পুত্র হিসেবে সিংহাসনে বসা প্রথম সুলেইমানের 46 বছরের সালতানাত সাম্রাজ্যের রাজনৈতিক, সামরিক, আইনি ও সাংস্কৃতিক শিখর গণ্য হয়। প্রথাগত আইন সুসংহতকারী কানুননামা তাঁকে 'কানুনি' (আইনদাতা) উপাধি এনে দিল; পশ্চিমে তিনি 'মহান' (Magnificent) নামে পরিচিত। স্থপতি সিনানের কীর্তি, দিওয়ান সাহিত্যের স্বর্ণযুগ ও নৌবহরের ভূমধ্যসাগরীয় প্রাধান্য এই যুগের প্রতীক।", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["বেলগ্রেডের বিজয়", "59ef5cec"], "d": ["ফাতিহ 1456 সালে দখল করতে না পারা এবং 'মধ্য ইউরোপের তালা' গণ্য বেলগ্রেড কানুনির প্রথম অভিযানে দানিউব-সাভা সঙ্গমে অবরোধে পতিত হলো। হাঙ্গেরির দক্ষিণ প্রতিরক্ষা রেখা ভেঙে পড়ল; পাঁচ বছর পর মোহাচ ও বিশ বছর পর বুদিন অন্তর্ভুক্তি পর্যন্ত বিস্তৃত মধ্য ইউরোপ অভিযানের দরজা এই বিজয়ে খুলল।", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["রোডসের বিজয়", "807bbb1e"], "d": ["পূর্ব ভূমধ্যসাগরের সমুদ্রপথ ও হজ পথ হুমকিতে ফেলা সেন্ট জন নাইটদের ঘাঁটি রোডস মাসের পর মাস রক্তক্ষয়ী অবরোধের পর চুক্তিতে আত্মসমর্পণ করল; নাইটদের দ্বীপ ছেড়ে মুক্তভাবে যাওয়ার অনুমতি দেওয়া হলো (পরে তারা মাল্টায় বসতি করে)। আনাতোলীয় উপকূলের নিরাপত্তা নিশ্চিত হলো এবং ইস্তানবুল-মিসর সমুদ্রপথ নিরবচ্ছিন্ন অটোমান নিয়ন্ত্রণে এলো।", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["মোহাচের রণক্ষেত্রের যুদ্ধ", "f3418b0d"], "d": ["হাঙ্গেরীয় সেনাবাহিনী মোহাচ সমভূমিতে প্রায় দুই ঘণ্টায় কামানের গোলা ও কৌশলগত প্রাধান্যে বিনষ্ট হলো; রাজা দ্বিতীয় লাইওশ পালানোর সময় জলাভূমিতে মারা গেলেন। অটোমান ইতিহাসের সবচেয়ে দ্রুত অর্জিত বড় রণক্ষেত্রের যুদ্ধগুলোর একটি মোহাচ স্বাধীন হাঙ্গেরীয় রাজ্যের কার্যত অবসান ঘটাল এবং মধ্য ইউরোপে অটোমান-হাবসবার্গ প্রতিদ্বন্দ্বিতার যুগ খুলল।", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["প্রথম ভিয়েনা অবরোধ", "dc49ea4f"], "d": ["হাবসবার্গদের হাঙ্গেরীয় সিংহাসন দখলের বিরুদ্ধে অভিযানে অটোমান সেনাবাহিনী ভিয়েনা অবরোধ করল; ভারী কামান পথে ফেলে আসা, আগেভাগে নামা শীত ও রসদ সংকটে তিন সপ্তাহ পর অবরোধ তুলে নেওয়া হলো। শহর দখল না হলেও হাঙ্গেরির ওপর অটোমান প্রভাব রক্ষিত হলো; ভিয়েনার সামনের এলাকা সাম্রাজ্যের মধ্য ইউরোপে রসদ পৌঁছানোর সীমা নির্দেশ করল।", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["বাগদাদের বিজয় — ইরাকাইন অভিযান", "897092c3"], "d": ["'দুই ইরাক' (আরব ইরাক ও আজমি ইরাক) অভিযানে প্রথমে তাবরিজে, পরে যুদ্ধ ছাড়া বাগদাদে প্রবেশ করা হলো; আব্বাসীয়দের পুরোনো রাজধানী দখল অটোমান শাসককে ইসলামী বিশ্বে বড় মর্যাদা এনে দিল। ইমাম-ই আজম আবু হানিফার সমাধি সংস্কার করা হলো; বাগদাদ ও বসরার অন্তর্ভুক্তিতে অটোমান ভূখণ্ড পারস্য উপসাগরে পৌঁছল। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: কিরকুক, কারবালা।", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["প্রেভেজার নৌ বিজয়", "30dc0f97"], "d": ["পোপের নেতৃত্বে গঠিত ক্রুসেডার নৌবহর সংখ্যায় বেশি হওয়া সত্ত্বেও বারবারোসার বাতাস ও উপকূল দক্ষভাবে ব্যবহারের কৌশলে প্রেভেজার উপকূলে ছত্রভঙ্গ হলো; আন্দ্রেয়া দোরিয়া যুদ্ধক্ষেত্র ত্যাগ করলেন। বিজয় ভূমধ্যসাগরে প্রায় 33 বছর স্থায়ী প্রশ্নাতীত অটোমান নৌ প্রাধান্য প্রতিষ্ঠা করল; তুর্কি নৌ ঐতিহ্যে নৌবাহিনী দিবসের প্রতীকী তারিখ। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: এডেন, বেন্ডের।", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["বুদিনের অন্তর্ভুক্তি — হাঙ্গেরি অটোমান প্রদেশ", "db53b244"], "d": ["হাবসবার্গদের বুদিন অবরোধের কারণে অভিযানে বেরোনো কানুনি শহর রক্ষা করে মধ্য হাঙ্গেরিকে সরাসরি অটোমান শাসনে নিয়ে বুদিন বেইলারবেইলিক গড়লেন; ট্রান্সিলভানিয়াকে অটোমানের অধীন স্বায়ত্তশাসিত প্রিন্সিপালিটি করা হলো। হাঙ্গেরির এই ত্রিবিভক্ত ব্যবস্থা প্রায় 150 বছর টিকল এবং অটোমানদের মধ্য ইউরোপে স্থায়ী শাসনকাঠামো গড়ল।", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["আমাসিয়া চুক্তি", "a5afe0d1"], "d": ["বছরের পর বছর চলা অটোমান-সাফাভি যুদ্ধ শেষ করা প্রথম আনুষ্ঠানিক শান্তি চুক্তি। বাগদাদ ও ইরাক অটোমানদের হাতে রইল, পূর্ব আনাতোলিয়া সীমান্ত প্রথমবার পারস্পরিক স্বীকৃত হলো; সাফাভিরা অটোমান ভূমিতে শিয়া প্রচারণা বন্ধ করতে, অটোমানরা ইরানি হাজিদের চলাচলের নিরাপত্তা দিতে সম্মত হলো। চুক্তিটি দুই রাষ্ট্রের সম্পর্কের আইনি কাঠামোর প্রথম উদাহরণ।", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["সিগেতভার — কানুনির মৃত্যু", "e2917ed2"], "d": ["72 বছর বয়সী কানুনি তাঁর তেরোতম অভিযানে অবরোধ করা সিগেতভার দুর্গের পতনের কয়েক ঘণ্টা আগে তাঁবুতে মারা গেলেন; সোকোল্লু মেহমেদ পাশা সেনাবাহিনী ছত্রভঙ্গ না হওয়ার জন্য মৃত্যু সপ্তাহের পর সপ্তাহ গোপন রাখলেন। দুর্গ দখল হলো, কিন্তু রাষ্ট্র তার দীর্ঘতম শাসনকালের ও সবচেয়ে মহিমান্বিত সুলতানকে হারাল; পুত্র দ্বিতীয় সেলিম সিংহাসনে বসলেন এবং রাষ্ট্র শাসনে প্রধান উজিরদের ওজন বাড়তে শুরু করল।", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["সাইপ্রাসের বিজয়", "e364a2b3"], "d": ["ভেনিসের শাসনাধীন সাইপ্রাসে 1570 সালে অবতরণ করা হলো; নিকোসিয়া দ্রুত পতিত হলো, ফামাগুস্তা এগারো মাসের অবরোধের পর আগস্ট 1571-এ আত্মসমর্পণ করল। পূর্ব ভূমধ্যসাগরের বাণিজ্য ও হজ পথের নিরাপত্তার জন্য গুরুত্বপূর্ণ দ্বীপ বেইলারবেইলিক হিসেবে সংগঠিত হলো এবং আনাতোলিয়া থেকে জনগোষ্ঠী বসতি পেল; বিজয় নাফপাক্তোসে পৌঁছনো বড় ক্রুসেডার মৈত্রীরও কারণ হলো।", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["নাফপাক্তোস (লেপান্তো) পরাজয়", "6a1d44a9"], "d": ["সাইপ্রাস বিজয়ের পর একত্রিত ক্রুসেডার নৌবহর অটোমান নৌবহরকে নাফপাক্তোস উপসাগরে ধরে তার বড় অংশ বিনষ্ট করল; কাপুদান-ই দেরিয়া মুয়েজ্জিনজাদে আলী পাশা শহীদ হলেন, কেবল উলুচ আলীর বহর রক্ষা পেল। বিপর্যয়ের পর প্রধান উজির সোকোল্লু মেহমেদ পাশা উলুচ আলী পাশাকে কাপুদান-ই দেরিয়া করে ছত্রভঙ্গ নৌবহর সংগঠনের দায়িত্ব দিলেন এবং ইস্তানবুল থেকে আলানিয়া পর্যন্ত সব জাহাজ কারখানায় নতুন নৌবহর নির্মাণ শুরু করলেন; তবে ভূমধ্যসাগরে নিরঙ্কুশ প্রাধান্য মনস্তাত্ত্বিকভাবে নড়ে গিয়েছিল।", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["হাচোভার রণক্ষেত্রের যুদ্ধ", "da308ec5"], "d": ["দীর্ঘ যুদ্ধের (1593–1606) সবচেয়ে বড় রণক্ষেত্রের যুদ্ধে তৃতীয় মেহমেদ স্বয়ং যে সেনাবাহিনীর শীর্ষে ছিলেন, তা ছত্রভঙ্গ হওয়ার মুহূর্তে হোজা সাদেদ্দিন এফেন্দির পরামর্শে সংগঠিত হয়ে হাবসবার্গ সেনাবাহিনীকে পরাজিত করল। অটোমানদের জেতা শেষ বড় ধ্রুপদী রণক্ষেত্রের যুদ্ধ গণ্য হয়; তবে যুদ্ধের সামগ্রিক গতি না বদলানোও সামরিক ব্যবস্থার ক্ষয়ের ইঙ্গিত বলে ধরা হয়।", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["জিতভাতোরোক চুক্তি", "39c01142"], "d": ["তেরো বছরের ক্ষয়কারী যুদ্ধ শেষ করা চুক্তিতে হাবসবার্গ শাসক প্রথমবার 'রোমান সম্রাট' উপাধিতে সুলতানের সমকক্ষ গণ্য হলেন এবং বার্ষিক কর বিলুপ্ত হলো। ভূখণ্ড ক্ষতি প্রায় নেই বললেই চলে; তবে কূটনৈতিক ভাষার এই বদল ইউরোপের বিরুদ্ধে অটোমানদের নিরঙ্কুশ শ্রেষ্ঠত্বের দাবির অবসানের প্রতীক হিসেবে পঠিত হয়।", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["কাসরে শিরিন চুক্তি", "c1acf3af"], "d": ["চতুর্থ মুরাদের বাগদাদ পুনরুদ্ধারের (1638) পর স্বাক্ষরিত চুক্তি শতাধিক বছরের অটোমান-সাফাভি যুদ্ধের অবসান ঘটাল। বাগদাদ ও ইরাক চূড়ান্তভাবে অটোমানদের হাতে রইল, ইরেভান সাফাভিদের ছেড়ে দেওয়া হলো; আঁকা রেখা সামান্য পরিবর্তনসহ বর্তমান তুরস্ক-ইরান সীমান্তের ভিত্তি হলো এবং বিশ্বের দীর্ঘস্থায়ী সীমান্তগুলোর একটি গণ্য হয়। চুক্তি বেদরে, জেসসান, মেন্দেলি, দের্তেং ও দেরনেকে অটোমানদের ছেড়ে দিল; সীমান্তের জেনজির দুর্গ ধ্বংস করা হবে, তার পশ্চিমের গ্রাম অটোমানদের, পূর্বেরগুলো ইরানের থাকবে। শেহরিজোরের কাছে জালিম দুর্গের আশপাশ ও কিজিলজা কালে অটোমানদের, আভরোমান ও মিহরিবান ইরানের রইল; কোতুর, মাকু ও মাগাজবের্দ দুর্গ দুই পক্ষই ধ্বংস করবে।", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["ক্রিটের বিজয় সম্পূর্ণ", "e0d85604"], "d": ["1645 সালে শুরু হওয়া ক্রিট যুদ্ধের শেষ দৃশ্য ক্যান্ডিয়া অবরোধ ফাজিল আহমেদ পাশার তিন বছরের দৃঢ় অভিযানে শেষ হলো; ভেনিসীয় অধিনায়ক মরোসিনি চুক্তির মাধ্যমে শহর হস্তান্তর করলেন। প্রায় সিকি শতক চলা সংগ্রাম অটোমান ইতিহাসের দীর্ঘতম অবরোধ হিসেবে নথিভুক্ত হলো; পূর্ব ভূমধ্যসাগরের শেষ বড় ল্যাটিন দুর্গও অটোমান শাসনে এলো। দ্বীপের উত্তর উপকূলের তিনটি ছোট পাথুরে দুর্গ — সুদা, স্পিনালোঙ্গা ও গ্রাম্বুসা — তখনও ভেনিসের হাতে রইল; এগুলো আলাদা ছোট দ্বীপে অবস্থিত হওয়ায় মানচিত্রে ক্রিটের বাকি অংশ থেকে আলাদা দেখানো যায় না।", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["বুচাচ চুক্তি — সবচেয়ে প্রশস্ত সীমান্ত", "b17b6e5a"], "d": ["পোল্যান্ড অভিযানে কামিয়ানেৎসের বিজয়ের পর স্বাক্ষরিত বুচাচ চুক্তিতে পোডোলিয়া অটোমানদের সঙ্গে যুক্ত হলো এবং ইউক্রেনের একাংশ আশ্রয়ে নেওয়া হলো। সাম্রাজ্য এভাবে ইউরোপে সবচেয়ে প্রশস্ত সীমান্তে পৌঁছল; এই বিন্দু সম্প্রসারণ যুগের শিখর ও একই সঙ্গে শেষ কড়ি গণ্য হয়।", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["দ্বিতীয় ভিয়েনা অবরোধের পরাজয়", "7d889252"], "d": ["মেরজিফোনলু কারা মুস্তাফা পাশার দুই মাসের ভিয়েনা অবরোধ পোল্যান্ডের রাজা ইয়ান সোবিয়েস্কির কালেনবার্গ পাহাড় থেকে নামানো আকস্মিক আঘাতে পরাজয়ে পরিণত হলো; সেনাবাহিনী ভারী সরঞ্জাম ফেলে সরে গেল, মেরজিফোনলু বেলগ্রেডে মৃত্যুদণ্ড পেলেন। বিজয়ের পর গঠিত পবিত্র মৈত্রীর সঙ্গে যুদ্ধ 16 বছর চলল; অটোমান ইতিহাসে বড় পতনের সূচনামুহূর্ত হিসেবে এই পরাজয় দেখানো হয়।", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["গ্রাম্বুসা দুর্গের বিজয় — ক্রিটে ভেনিসের হাতে থাকা পাথুরে দুর্গগুলোর একটি", "3ddf9eeb"], "d": ["1669 সালে ক্যান্ডিয়ার আত্মসমর্পণে ক্রিট বিজয় মোটামুটি সম্পূর্ণ ধরা হলেও দ্বীপের উত্তর-পশ্চিম প্রান্তের পাথুরে দ্বীপ-দুর্গ গ্রাম্বুসা আরও তেইশ বছর ভেনিসের হাতে রইল। 1692 সালে দখলের মাধ্যমে ক্রিটে তিন ভেনিসীয় অবশেষের একটি মুছল; সুদা ও স্পিনালোঙ্গা 1715 সালের মোরিয়া অভিযানের অপেক্ষায় রইল।", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["কার্লোভিৎস চুক্তি — প্রথম বড় ভূখণ্ড হারানো", "8f7e2546"], "d": ["ষোলো বছরের পবিত্র মৈত্রী যুদ্ধ শেষ করা কার্লোভিৎসে হাঙ্গেরি ও ট্রান্সিলভানিয়া অস্ট্রিয়াকে, পোডোলিয়া পোল্যান্ডকে, মোরিয়া ও ডালমাশিয়া উপকূল ভেনিসকে ছেড়ে দেওয়া হলো। অটোমান ইতিহাসে প্রথমবার এই মাপের ভূখণ্ড আলোচনার টেবিলে ও স্থায়ীভাবে হাতছাড়া হচ্ছিল; চুক্তি সাম্রাজ্যের ইউরোপের বিরুদ্ধে প্রতিরক্ষায় যাওয়ার নতুন যুগের সূচনা-দলিল গণ্য হয় এবং অটোমান কূটনীতির ইতিহাসেরও মোড়। একই দিন অ্যাটলাসে হাতবদল হওয়া বসতি: কোস্তাইনিৎসা ও ইয়াসেনোভাৎস (অটোমান থেকে হাবসবার্গে; চুক্তির পাঠ Castanoviz সম্রাটের হাতে রাখে, ইয়াসেনোভাৎসের হস্তান্তরের দিন সূত্রে নেই, চুক্তির দিন লেখা হয়েছে) এবং প্রেভেজা (ভেনিস থেকে অটোমানে; TDV karlofca: 24 রজব 1110 / 26 জানুয়ারি 1699 স্বাক্ষরিত বিধান অনুযায়ী নাফপাক্তোস উপসাগরের উত্তরে ভেনিসের দখল করা স্থান ফেরত দেওয়া হলো)। অ্যাটলাস আরও কোস্তাইনিৎসা (Kostajnica) ও ইয়াসেনোভাৎসকে হাবসবার্গ পক্ষে, ডান তীরের ইউক্রেনের উমান ও ভিন্নিৎসাকে অটোমান থেকে পোল্যান্ডে (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: 1672-99 তুর্কি আধিপত্য) এবং ডালমাশিয়ার নাদিনকে ভেনিসে লেখে (বসতি-নির্দিষ্ট হস্তান্তরের দিন সূত্রে নেই, চুক্তির দিন লেখা হয়েছে; নাদিনের যুগের সীমা সূত্রে যাচাই হয়নি — ঘোষিত আনুমানিকতা)। নাফপাক্তোস উপসাগরের উত্তরের ভনিৎসাও ভেনিস থেকে অটোমানদের ফেরত দেওয়া হয় (TDV karlofca); ডালমাশিয়ায় ভ্রানা (Urana) ভেনিসের হাতে থাকা স্থানগুলোর মধ্যে (যুগের সীমা যাচাই হয়নি — ঘোষিত)।", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["প্রুত বিজয়", "2583572f"], "d": ["পলতাভা পরাজয়ের পর অটোমানদের কাছে আশ্রয় নেওয়া সুইডিশ রাজার প্রশ্নে বাধা যুদ্ধে জার প্রথম পিটারের সেনাবাহিনী প্রুতের তীরে অবরুদ্ধ হয়ে আত্মসমর্পণ করতে বাধ্য হলো। স্বাক্ষরিত চুক্তিতে আজাক ফিরিয়ে নেওয়া হলো; সেনাবাহিনী নিশ্চিহ্ন না করা ও জারকে মুক্তি দেওয়া সেদিন থেকে আজও বিতর্কিত সিদ্ধান্ত হিসেবে ইতিহাসে স্থান পেল।", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["সুদা ও স্পিনালোঙ্গা দুর্গের বিজয় — ক্রিটে শেষ ভেনিসীয় চিহ্ন মোছা", "7261f7ba"], "d": ["1692 সালে গ্রাম্বুসার পতনের তেইশ বছর পর মোরিয়া অভিযানের একটি শাখা অভিযানে ক্রিটে ভেনিসের শেষ দুই ঘাঁটি সুদা ও স্পিনালোঙ্গা দুর্গও জয় হলো। এভাবে 1645 সালে শুরু হওয়া ক্রিট বিজয় ছেচল্লিশ বছর পর দ্বীপের শেষ ইঞ্চি পর্যন্ত সম্পূর্ণ হলো।", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["পাত্রোনা হালিলের বিদ্রোহ", "100941a4"], "d": ["ইরান রণাঙ্গনে ব্যর্থতা, কর ও প্রাসাদ মহলের বিলাসিতার বিরুদ্ধে ক্ষোভ হাম্মামের তেল-মালিশকারী পাত্রোনা হালিলের নেতৃত্বে বড় বিদ্রোহে রূপ নিল। প্রধান উজির ইব্রাহিম পাশা নিহত হলেন, তৃতীয় আহমেদ সিংহাসনচ্যুত হলেন এবং তুলিপ যুগ শেষ হলো; বিদ্রোহীদের মাসের পর মাস শহরে কর্তৃত্ব কেন্দ্রীয় কর্তৃত্বের ভঙ্গুরতা চমকপ্রদভাবে দেখাল।", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["বেলগ্রেড চুক্তি — বেলগ্রেড, স্মেদেরেভো ও উত্তর সার্বিয়ার পুনরুদ্ধার", "ba7f8e46"], "d": ["অস্ট্রিয়া ও রাশিয়ার বিরুদ্ধে দুই ফ্রন্টে চালানো যুদ্ধের (1736–1739) শেষে বেলগ্রেড ও উত্তর সার্বিয়া ফিরে পাওয়া গেল; রাশিয়া আজাক নিরস্ত্র করতে ও কৃষ্ণ সাগরে নৌবহর না রাখতে সম্মত হলো। 18শ শতকের অটোমান কূটনীতি ও সেনাবাহিনীর শেষ বড় সাফল্য গণ্য এই চুক্তি সাম্রাজ্যকে সিকি শতকের শান্তি যুগ এনে দিল। একই দিন অ্যাটলাসে অস্ট্রিয়া থেকে অটোমানদের ফেরা অন্যান্য বসতি: গ্রোচকা (Grocka) (বেলগ্রেডের আবি-মার্কেজ শৃঙ্খল; TDV belgrad), ক্রাইওভা (Craiova), রিমনিক (Râmnicu Vâlcea) ও তুর্নু সেভেরিন (ছোট ওয়ালাচিয়ার অটোমানদের কাছে ফেরা, ওয়ালাচিয়ার অধীনস্থতায়)। সাভা তীরের বসনা ব্রদ (Bosanski Brod) ও বসনা দুবিৎসা (Bosanska Dubica) অ্যাটলাসে অবশ্য 28 সেপ্টেম্বর 1739 অটোমানদের কাছে ফেরে (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 সেপ্টেম্বর 1739)। ছোট ওয়ালাচিয়ায় তিরগু জিউও একই দিন অটোমানদের কাছে ফেরে।", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["চেশমে হামলা", "840b30bd"], "d": ["ব্রিটিশ সমর্থনে ভূমধ্যসাগরে বেরোনো রুশ নৌবহর অটোমান নৌবহরকে আশ্রয়স্থল চেশমে বন্দরে অগ্নিজাহাজ দিয়ে হামলা করে প্রায় পুরোপুরি পুড়িয়ে দিল। রাশিয়া প্রথমবার ভূমধ্যসাগরে বড় নৌশক্তি হিসেবে আবির্ভূত হলো; বিপর্যয় 1774 সালের কুচুক কায়নারজার দিকে যাওয়া যুদ্ধের ভাগ্য নির্ধারণকারী আঘাতগুলোর একটি হলো এবং নৌবহরের মূলগত সংস্কারের প্রয়োজন প্রকাশ করল।", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["কুচুক কায়নারজা চুক্তি", "2776dcdb"], "d": ["1768–1774 যুদ্ধ শেষ করা এবং অটোমান ইতিহাসের সবচেয়ে ভারী চুক্তিগুলোর একটি গণ্য কুচুক কায়নারজায় ক্রিমিয়ান খানাতকে 'স্বাধীনতা' দেওয়া হলো — কার্যত রুশ প্রভাব বলয় সৃষ্টি হলো। রাশিয়া কৃষ্ণ সাগর উপকূলে বসল, বাণিজ্য জাহাজের প্রণালী দিয়ে চলাচলের অধিকার ও ইস্তানবুলে স্থায়ী দূতাবাস পেল; অর্থোডক্স প্রজাদের ওপর অস্পষ্ট আশ্রয়ের ধারা পরবর্তী শতকের হস্তক্ষেপের অজুহাতের দরজা খুলল। প্রথমবার জনসংখ্যায় মুসলিম একটি ভূমি অটোমান আধিপত্য থেকে বেরিয়ে যাচ্ছিল।", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["ক্রিমিয়ার রাশিয়ায় অন্তর্ভুক্তি", "bdf6faa8"], "d": ["কুচুক কায়নারজার সৃষ্ট 'স্বাধীন' ক্রিমিয়া শেষ খান শাহিন গিরাইয়ের আমলের বিশৃঙ্খলাকে অজুহাত করে দ্বিতীয় ক্যাথরিনের ঘোষণাপত্রে রাশিয়ার সঙ্গে সংযুক্ত হলো। তিন শতকের অটোমান-ক্রিমিয়ান অংশীদারিত্ব শেষ হলো; উত্তরের স্তেপ হারানো ইস্তানবুলের প্রতিরক্ষার গভীরতা নষ্ট করল এবং হাজার হাজার ক্রিমিয়ান তাতারের অটোমান ভূমিতে অভিবাসনের প্রথম বড় ঢেউ শুরু করল। এই দিন ক্রিমিয়া উপদ্বীপ (আলুশতা, কেফে, সুদাক, ইয়াল্টা, বালাক্লাভা, ইনকেরমান, মানকুপ, আরাবাত) রাশিয়ায় যুক্ত হলো; তামান ও কুবানও একই অন্তর্ভুক্তিতে রাশিয়ায় গেল (TDV Kırım: 8 এপ্রিল 1783 জুলিয়ান = 19 এপ্রিল গ্রেগরিয়ান)।", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["তৃতীয় সেলিম ও নিজাম-ই জেদিদ", "d53aec21"], "d": ["যুদ্ধের মাঝে সিংহাসনে বসা তৃতীয় সেলিম পরাজয় কাঠামোগত বুঝে 'নিজাম-ই জেদিদ' (নতুন ব্যবস্থা) নামে ব্যাপক সংস্কার কর্মসূচি শুরু করলেন: ইউরোপীয় ধাঁচে প্রশিক্ষিত নতুন সেনাবাহিনী, তা অর্থায়নকারী আলাদা কোষাগার (ইরাদ-ই জেদিদ), প্রকৌশল স্কুল শক্তিশালীকরণ ও ইউরোপীয় রাজধানীতে প্রথম স্থায়ী দূতাবাস। কর্মসূচি আধুনিক তুর্কি সংস্কার ঐতিহ্যের সূচনা গণ্য হয়; তবে ওজাক ও আয়ানদের প্রতিরোধে 1807 সালে ভেঙে পড়বে।", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["মাল্টার নাইটদের বিলুপ্তি — ফরাসি নৌবহরের পথের বিরতি", "d62f901d"], "d": ["মিসরের দিকে যাওয়া ফরাসি নৌবহর পথের ওপর মাল্টায় থামল; সেন্ট জন (মাল্টা) নাইটরা বেশি প্রতিরোধ না করেই দ্বীপ হস্তান্তর করল। 1522 সালে রোডস থেকে বিতাড়িত হয়ে এখানে বসা নাইট সংঘের শেষ দুর্গ এভাবে শেষ হলো। মাল্টা দুই বছর পর ব্রিটেনের হাতে যাবে, নেপোলিয়ন দ্বীপ থেকে সরাসরি আলেকজান্দ্রিয়ায় যাবেন।", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["নেপোলিয়নের মিসর দখল", "93fede5f"], "d": ["জেনারেল বোনাপার্টের সেনাবাহিনী আলেকজান্দ্রিয়ায় নেমে মিসর দখল করল; ব্রিটেনের ভারত পথকে লক্ষ্য করা এই অভিযান ছিল একটি ইউরোপীয় শক্তির অটোমানদের কেন্দ্রীয় ভূমিতে প্রথম সরাসরি আক্রমণ। নেলসনের আবুকির হামলা ও জেজ্জার আহমেদ পাশার আক্কা প্রতিরক্ষা ফরাসি অগ্রযাত্রা ভাঙল; দখল 1801 সালে শেষ হলো, কিন্তু রেখে যাওয়া শূন্যতায় কাভালার মেহমেদ আলী পাশার উত্থান ও 'প্রাচ্য সমস্যা'র যুগ শুরু হলো।", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["সেনেদ-ই ইত্তিফাক", "cce49ef5"], "d": ["দ্বিতীয় মাহমুদকে সিংহাসনে বসানো রুসের আয়ান আলেমদার মুস্তাফা পাশার নেতৃত্বে প্রাসাদ ও প্রদেশের শক্তিশালী আয়ান পরিবারগুলোর মধ্যে স্বাক্ষরিত দলিল; আয়ানরা সুলতানের প্রতি আনুগত্য ও সৈন্য সমর্থনের অঙ্গীকার করল, রাষ্ট্রও তাদের অস্তিত্ব ও অধিকার স্বীকার করল। সুলতানের কর্তৃত্ব একটি দলিলে সীমিত হওয়ার অটোমান ইতিহাসে প্রথম উদাহরণ হওয়ায় কিছু ইতিহাসবিদ একে সাংবিধানিক ঐতিহ্যের দূরবর্তী সূচনা গণ্য করেন; কার্যত কয়েক মাসেই এটি অকার্যকর হলো।", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["গ্রিক বিদ্রোহ শুরু", "a7293715"], "d": ["ফিলিকি এতেরিয়া সংগঠনের প্রস্তুত করা বিদ্রোহ প্রথমে ওয়ালাচিয়ায়, পরে মূল শক্তি নিয়ে মোরিয়ায় ফেটে পড়ল; তেপেদেলেনলি আলী পাশার ঝামেলায় ব্যস্ত রাষ্ট্র প্রথম হস্তক্ষেপে দেরি করল। ইউরোপীয় জনমতের তীব্র গ্রিক সহানুভূতির (ফিলহেলেনিজম) কারণে বিদ্রোহ অল্প সময়ে আন্তর্জাতিক ইস্যুতে পরিণত হলো; জাতীয়তাবাদের যুগে অটোমান ভূমিতে প্রথম সফল স্বাধীনতা আন্দোলনের ফিউজ এভাবে জ্বলল। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: এথেন্স, পাত্রাস, থিবস, লিভাদিয়া, এলেউসিস (আত্তিকা), মিসোলোঙ্গি।", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["মোরিয়ায় প্রথম সশস্ত্র বিদ্রোহ", "77e6250f"], "d": ["প্রুত পারাপারের পর বিদ্রোহ মোরিয়ায় ছড়াল: কালাভ্রিতায় (জুলিয়ান 21 মার্চ) শুরু হওয়া সশস্ত্র পদক্ষেপের পর পাত্রাস, কালামাতা ও মানিতে আন্দোলন অনুসরণ করল; মোরিয়া অল্প সময়ে সাধারণ বিদ্রোহে পরিণত হলো এবং অটোমান প্রশাসন উপদ্বীপের বড় অংশ হারাল। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: এথেন্স, পাত্রাস, থিবস, লিভাদিয়া, এলেউসিস (আত্তিকা), মিসোলোঙ্গি।", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["ভাকা-ই হাইরিয়ে — জানিসারি বাহিনী বিলুপ্ত", "08c9372a"], "d": ["নতুন গঠিত এশকিঞ্জি বাহিনীর প্রশিক্ষণের বিরুদ্ধে বিদ্রোহ করা জানিসারিরা দ্বিতীয় মাহমুদের আগে থেকে প্রস্তুত বিশ্বস্ত বাহিনীর কামানের গোলায় এতমেইদানির ব্যারাকে বিনষ্ট হলো; ওজাক তার সব শাখা ও সংশ্লিষ্ট বেকতাশি তাকিয়াসহ বিলুপ্ত হলো। 'শুভ ঘটনা' অর্থের নামে ইতিহাসে স্থান পাওয়া এই অভিযান চার শতকের প্রতিষ্ঠানকে বিলুপ্ত করে আসাকির-ই মানসুরে-ই মুহাম্মাদিয়ে বাহিনী ও পরবর্তী সব কেন্দ্রীকরণ সংস্কারের পথ খুলল।", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["নাভারিনোর হামলা", "ee579e7f"], "d": ["গ্রিক বিদ্রোহ দমনরত অটোমান-মিসরীয় নৌবহর যুদ্ধ ঘোষণা ছাড়া বন্দরে ঢোকা ব্রিটিশ-ফরাসি-রুশ যৌথ বহরের হাতে নাভারিনোতে পুড়ে গেল; ষাটের কাছাকাছি জাহাজ ও হাজার হাজার নাবিক হারানো হলো। ইউরোপীয় কূটনীতিতে 'দুর্ভাগ্যজনক ঘটনা' বলে এড়িয়ে যাওয়া হামলা গ্রিক স্বাধীনতা কার্যত নিশ্চিত করল এবং 1828–29 অটোমান-রুশ যুদ্ধের পথ খুলল।", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["তানজিমাত ফরমান", "5042ce7b"], "d": ["গুলহানেতে পঠিত হাত্ত-ই হুমায়ুনে ধর্ম নির্বিশেষে সব প্রজার জীবন, সম্পদ ও সম্মানের নিরাপত্তা রাষ্ট্রীয় নিশ্চয়তায় নেওয়া হলো; করে ন্যায়বিচার, সামরিক সেবায় শৃঙ্খলা এবং বিচার ছাড়া শাস্তি না দেওয়ার নীতি ঘোষিত হলো। মুস্তাফা রেশিদ পাশার কীর্তি এই ফরমান অটোমান আধুনিকায়নের সাংবিধানিক প্রকৃতির প্রথম বড় দলিল গণ্য হয় এবং 'তানজিমাত যুগ' (1839–1876) সংস্কার যুগকে তার নাম দিয়েছে; প্রশাসন, আইন, শিক্ষা ও অর্থব্যবস্থায় মূলগত পুনর্গঠন এই কাঠামোয় চালানো হলো।", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["ক্রিমিয়ান যুদ্ধ শুরু", "3b9ca3c8"], "d": ["পবিত্র স্থান প্রশ্ন ও রাশিয়ার অর্থোডক্স প্রজাদের ওপর আশ্রয়ের দাবিতে শুরু হওয়া সংকট অটোমানদের যুদ্ধ ঘোষণায় প্রকাশ্য সংঘর্ষে পরিণত হলো; সিনোপ হামলার পর ব্রিটেন ও ফ্রান্স (পরে পিডমন্ট) অটোমান পক্ষে যুদ্ধে নামল। মিত্র বাহিনীর ক্রিমিয়ায় নেমে সেভাস্তোপল দখলের মাধ্যমে যুদ্ধ 1856 সালের প্যারিস চুক্তিতে জেতা হলো; তবে যুদ্ধের বছরগুলোতে নেওয়া প্রথম বৈদেশিক ঋণ (1854) সাম্রাজ্যকে অর্ধ শতক স্থায়ী আর্থিক নির্ভরতার চক্রে ফেলল।", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["ইসলাহাত ফরমান", "78ff234d"], "d": ["প্যারিস শান্তি আলোচনার আগে ঘোষিত ফরমান তানজিমাত নীতি সম্প্রসারণ করে অমুসলিম প্রজাদের সরকারি চাকরি, সামরিক সেবা ও স্কুল খোলাসহ ব্যাপক সমান অধিকার দিল; সম্প্রদায় সংগঠনগুলো পুনর্বিন্যস্ত হলো। এরপর স্বাক্ষরিত প্যারিস চুক্তিতে অটোমান রাষ্ট্র আনুষ্ঠানিকভাবে ইউরোপীয় রাষ্ট্রীয় আইনের পরিবারে গৃহীত হলো এবং ভূখণ্ডগত অখণ্ডতা বড় শক্তিগুলোর যৌথ নিশ্চয়তায় নেওয়া হলো — এই নিশ্চয়তা বাস্তবে হস্তক্ষেপের নতুন দরজা হবে।", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["কানুন-ই এসাসি — প্রথম সাংবিধানিক যুগ", "0fe052c1"], "d": ["বলকান সংকট আলোচনায় ইস্তানবুলে জড়ো হওয়া আন্তর্জাতিক সম্মেলন শুরুর দিন কামান দেগে প্রথম অটোমান সংবিধান ঘোষিত হলো; মিদহাত পাশার নেতৃত্বাধীন 'নব্য অটোমান' আন্দোলনের কীর্তি কানুন-ই এসাসিতে দ্বিকক্ষ সংসদ গঠিত হলো। মেজলিস-ই মেবুসান মার্চ 1877-এ খুলল; তবে দ্বিতীয় আবদুলহামিদ '93 যুদ্ধ'কে অজুহাত করে ফেব্রুয়ারি 1878-এ সংসদ অনির্দিষ্টকালের জন্য স্থগিত করলেন এবং সংবিধান ত্রিশ বছর ঝুলে রইল।", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["93 যুদ্ধ (1877–78 অটোমান-রুশ যুদ্ধ)", "5bd96af7"], "d": ["রুমি 1293 সালের সঙ্গে মিলে যাওয়ায় '93 যুদ্ধ' নামে পরিচিত এই যুদ্ধে রুশ সেনাবাহিনী দুই ফ্রন্টে আক্রমণ করল; গাজি ওসমান পাশার প্লেভেন প্রতিরক্ষা ও আহমেদ মুখতার পাশার ককেশাস যুদ্ধ মহাকাব্যিক হলেও ফ্রন্ট ভেঙে পড়ল এবং রুশরা ইয়েশিলকোই (আয়াস্তেফানোস) পর্যন্ত এগোল। যুদ্ধ বলকান ও ককেশাস থেকে ইস্তানবুলের দিকে আজ পর্যন্ত প্রভাব বিস্তৃত বড় মুসলিম অভিবাসন ঢেউ শুরু করল; সাম্রাজ্যের জনতাত্ত্বিক ও আর্থিক কাঠামো আর আগের অবস্থায় ফিরতে পারেনি।", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["বার্লিন চুক্তি", "47f76a49"], "d": ["আয়াস্তেফানোসের সৃষ্ট 'বৃহৎ বুলগেরিয়া'কে বড় শক্তিগুলোর ভারসাম্যের নামে সংশোধনকারী বার্লিন কংগ্রেস তবুও ভারী চিত্র রেখে গেল: সার্বিয়া, মন্টিনিগ্রো ও রোমানিয়া স্বাধীন হলো; স্বায়ত্তশাসিত বুলগেরিয়া প্রিন্সিপালিটি গঠিত হলো; বসনিয়া-হার্জেগোভিনা অস্ট্রীয় দখলে, সাইপ্রাস ব্রিটিশ প্রশাসনে, কার্স-আরদাহান-বাতুম রাশিয়াকে ছেড়ে দেওয়া হলো। রুমেলিতে পাঁচ শতকের অটোমান ব্যবস্থা বহুলাংশে ভেঙে পড়ল; 'প্রাচ্য প্রশ্ন' ইউরোপীয় কূটনীতির স্থায়ী আলোচ্যসূচিতে পরিণত হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: ফিলিবে, ভিদিন, তার্নোভো, ভার্না, শুমেন, সিলিস্ত্রা, রুসে, বুখারেস্ট, ইয়াশি, কনস্তান্তা। রোমানিয়া বেসারাবিয়া রাশিয়াকে দেওয়ার বিনিময়ে তুলচা (Tulcea) ও দোব্রুজা পেল: উত্তর দোব্রুজার তুলচা, বাবাদাগ (Babadag), মাচিন, ইসাকচা (Isaccea), হির্সোভা (Hârșova) ও মাঙ্গালিয়া (Mangalia) রোমানিয়ায় গেল।", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["তিউনিসের দখল ও দুয়ুন-ই উমুমিয়ে", "c7e25598"], "d": ["ফ্রান্স আলজেরিয়া সীমান্তের ঘটনাকে অজুহাত করে তিউনিস দখল করে বার্দো চুক্তিতে আশ্রয়ে নিল; উত্তর আফ্রিকায় অটোমান উপস্থিতি ত্রিপোলিতে নেমে এলো। একই বছর জারি মুহাররম ফরমানে দেউলিয়া বৈদেশিক ঋণ ব্যবস্থাপনার জন্য পাওনাদারদের প্রতিনিধিত্বযুক্ত দুয়ুন-ই উমুমিয়ে প্রশাসন গঠিত হলো: লবণ, তামাক, রেশমের মতো মূল আয় সরাসরি এই বিদেশি প্রশাসনের সঙ্গে যুক্ত হলো এবং আর্থিক সার্বভৌমত্ব গুরুতরভাবে সীমিত হলো। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: কাইরুয়ান, গাবেস, সফাকস, জেরবা (Djerba)।", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["মিসরের ব্রিটিশ দখল", "f1269768"], "d": ["মিসরে আর্থিক দেউলিয়াত্ব ও বিদেশি নিয়ন্ত্রণের বিরুদ্ধে উঠে আসা উরাবি পাশা আন্দোলন আলেকজান্দ্রিয়ায় বোমাবর্ষণের পর নামা ব্রিটিশ সেনাবাহিনীর তেল আল-কেবির বিজয়ে চূর্ণ হলো এবং কায়রো দখল হলো। মিসর আইনত অটোমানদের সঙ্গে যুক্ত থাকলেও কার্যত ব্রিটিশ শাসনে গেল; সুয়েজ খালের নিয়ন্ত্রণ ব্রিটিশ সাম্রাজ্য কৌশলের কেন্দ্রে বসল।", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["দ্বিতীয় সাংবিধানিক যুগের ঘোষণা", "95ee2fd2"], "d": ["ইত্তিহাদ ও তেরাক্কি সমিতির সঙ্গে যুক্ত অফিসারদের ম্যাসেডোনিয়ায় পাহাড়ে ওঠায় বেড়ে ওঠা আন্দোলনের মুখে দ্বিতীয় আবদুলহামিদ কানুন-ই এসাসি পুনরায় কার্যকর করলেন; 'স্বাধীনতার ঘোষণা' উচ্ছ্বাসে স্বাগত হলো এবং নির্বাচনে যাওয়া হলো। তবে স্থিতিশীলতা এলো না: 31 মার্চের ঘটনা (এপ্রিল 1909) দমনের পর আবদুলহামিদ সিংহাসনচ্যুত হলেন; বুলগেরিয়ার স্বাধীনতা, বসনিয়ার অন্তর্ভুক্তি ও ক্রিটের গ্রিসের দিকে ঝোঁকাও এই উত্তাল মাসগুলোতে ঘটল।", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["ত্রিপোলি যুদ্ধ", "ed441994"], "d": ["উপনিবেশ খোঁজা ইতালি অটোমানদের উত্তর আফ্রিকার শেষ ভূমি ত্রিপোলিতে যুদ্ধ ঘোষণা করে উপকূল দখল করল; নৌবহরহীন রাষ্ট্র নিয়মিত সেনা পাঠাতে না পারায় মুস্তাফা কেমাল ও এনভার বের মতো তরুণ অফিসাররা গোপনে অঞ্চলে গিয়ে সেনুসি গোত্রগুলোর সঙ্গে কার্যকর প্রতিরোধ সংগঠিত করলেন। বলকান যুদ্ধ শুরু হওয়ায় স্বাক্ষরিত উশি চুক্তিতে (18 অক্টোবর 1912) লিবিয়া ইতালিকে ছেড়ে দেওয়া হলো; ইতালি রোডস ও বারো দ্বীপপুঞ্জও দখল করল।", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["লন্ডন চুক্তি — রুমেলির হারানো", "f3f976df"], "d": ["প্রথম বলকান যুদ্ধ শেষ করা লন্ডন চুক্তিতে মিদিয়ে-এনেজ রেখার পশ্চিমের সব ভূখণ্ড ও এজিয়ান দ্বীপপুঞ্জ হারানো হলো; আলবেনিয়া স্বাধীন হলো। পাঁচ শতকের বেশি সময় ধরে সাম্রাজ্যের জনতাত্ত্বিক, অর্থনৈতিক ও সাংস্কৃতিক ভারকেন্দ্র রুমেলি থেকে কেবল পূর্ব থ্রেস অবশিষ্ট থাকবে (এডির্ন দ্বিতীয় বলকান যুদ্ধে পুনরুদ্ধার হয়); ক্ষতি ইত্তিহাদি শাসনের যুদ্ধ ও বসতি নীতিকে মূলগতভাবে কঠোর করল। মিদিয়ে-এনেজ রেখার পশ্চিমে পড়া নিম্নোক্ত স্থান হাতছাড়া হলো: ইউস্কুপ, কোপ্রুলু (Veles), ইশতিপ (Štip), উস্ত্রুমজা, দোইরান, গেভগেলি (Gevgelija), মানাস্তির, ওহরিড, দেবরে (Dibra), প্রিজরেন, প্রিস্তিনা, পেচ (Pejë), ইয়েনিপাজার (Novi Pazar), কসোভো সমভূমি (Kosovo Polje); সেরেস, দ্রামা, কাভালা, পেত্রিচ, নেভ্রোকোপ, ইস্কেচে, গুমুলজিনা, দেদেআগাচ, দিদিমোতিখো, চির্মেন, ফেরেচিক (Feres), সোফুলু (Soufli), অরেস্তিয়াদা (Kumçiftliği), প্রাভিশতে (Eleftheroupoli), Stérna, Távri, উমুর ফাকিহ (Fakia), মালাক দেরভেন্ত (Lalkovo); ক্রিটে খানিয়া, ক্যান্ডিয়া, ক্রিট (Resmo), সিতিয়া (Sitia) ও ইসফাকিয়ে (Sfakia)।", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["প্রথম বিশ্বযুদ্ধে প্রবেশ", "05a0252e"], "d": ["ব্রিটেন থেকে পালানো গোয়েবেন ও ব্রেসলাউ যুদ্ধজাহাজ কেনা দেখিয়ে প্রণালী দিয়ে ঢোকানো রাষ্ট্রকে ধাপে ধাপে জার্মানির পাশে টানল; অ্যাডমিরাল সুশনের নেতৃত্বাধীন নৌবহরের রুশ বন্দরে বোমাবর্ষণে (29 অক্টোবর) যুদ্ধ কার্যত শুরু হলো এবং পারস্পরিক ঘোষণা নভেম্বরের শুরুতে এলো। জিহাদ-ই আকবর ঘোষণা সত্ত্বেও প্রত্যাশিত প্রভাব পড়েনি; সাম্রাজ্য চার বছর ধরে ককেশাস থেকে ফিলিস্তিন পর্যন্ত পাঁচটি আলাদা রণাঙ্গনে অস্তিত্বের যুদ্ধে নামল।", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["চানাক্কালে বিজয়", "95d888e8"], "d": ["ইস্তানবুল ফেলে রাশিয়ায় পৌঁছতে চাওয়া মিত্র নৌবহর 18 মার্চ মাইন রেখা ও দুর্গের গোলাবর্ষণে প্রণালী থেকে হটে গেল; নুসরেত মাইন-জাহাজের বিছানো রেখা যুদ্ধের ভাগ্য নির্ধারণ করল। এপ্রিলে শুরু হওয়া গালিপোলি স্থল অভিযানও আনাফার্তালার ও জনকবাইরে থামানো হলো; মিত্ররা জানুয়ারি 1916-এ উপদ্বীপ সম্পূর্ণ খালি করল। লেফটেন্যান্ট কর্নেল মুস্তাফা কেমালের নাম এই রণাঙ্গনে পরিচিত হলো; প্রায় সিকি মিলিয়ন শহীদ ও ক্ষতিতে অর্জিত বিজয় জাতীয় সংগ্রামের কর্মী ও চেতনার জন্মস্থান গণ্য।", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["শরিফ হুসেইনের বিদ্রোহ", "75f7c58c"], "d": ["মক্কার আমির শরিফ হুসেইন ব্রিটিশদের সঙ্গে চালানো গোপন চিঠিপত্রের পর স্বাধীন আরব রাজ্যের প্রতিশ্রুতিতে বিদ্রোহ করলেন; হিজাজ রেলপথ হামলার লক্ষ্য হলো। ফখরুদ্দিন পাশার মদিনার যুদ্ধবিরতির পর পর্যন্ত চলা কিংবদন্তি প্রতিরক্ষা প্রতিরোধের প্রতীক হয়ে রইলেও বিদ্রোহ ফিলিস্তিন রণাঙ্গনের ব্রিটিশ অগ্রযাত্রার সঙ্গে মিলে আরব প্রদেশগুলোতে অটোমান আধিপত্যের ভাঙন ত্বরান্বিত করল। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: তায়েফ।", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["মুদ্রোস যুদ্ধবিরতি", "9e87c767"], "d": ["বুলগেরিয়ার পতনে রণাঙ্গনগুলো বিচ্ছিন্ন হওয়া অটোমান রাষ্ট্র আগামেমনন যুদ্ধজাহাজে স্বাক্ষরিত যুদ্ধবিরতিতে যুদ্ধ থেকে সরে এলো। প্রণালী খোলা ও বিশেষ করে নিরাপত্তা হুমকিতে থাকা স্থান দখলের সুযোগ দেওয়া ধারা 7 অল্প সময়ে কার্যত ভাগাভাগির আইনি আবরণে পরিণত হলো: মসুল, ইসকেন্দেরুন, পরে ইজমির ও ইস্তানবুল দখল হলো। যুদ্ধবিরতি সাম্রাজ্যের কার্যত সমাপ্তির দলিল গণ্য হয়। একই তারিখে হাতছাড়া হওয়া অন্যান্য বসতি: হামা, দামেস্ক, হোমস।", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["মুস্তাফা কেমাল সামসুনে — জাতীয় সংগ্রাম", "09a8f784"], "d": ["ইজমির দখলের সৃষ্ট ক্ষোভের পরিবেশে 9ম সেনাবাহিনীর পরিদর্শক হিসেবে সামসুনে নামা মুস্তাফা কেমাল পাশা তাঁর সরকারি দায়িত্ব আনাতোলিয়ায় প্রতিরোধ সংগঠনে ঘুরিয়ে দিলেন। আমাসিয়া সার্কুলার এবং এরজুরুম ও সিভাস কংগ্রেস এই সূচনার ধারাবাহিকতা; 'জাতির স্বাধীনতা আবার জাতির সংকল্প ও সিদ্ধান্তই রক্ষা করবে' নীতি জাতীয় সংগ্রামের রাজনৈতিক কর্মসূচির মূলকেন্দ্র হলো।", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["তুরস্কের গ্র্যান্ড ন্যাশনাল অ্যাসেম্বলির উদ্বোধন ও সেভ্র", "2008feec"], "d": ["ইস্তানবুলের আনুষ্ঠানিক দখল ও মেজলিস-ই মেবুসান ভেঙে দেওয়ায় 23 এপ্রিল 1920 আঙ্কারায় মহান জাতীয় সংসদ খুলল; অসাধারণ ক্ষমতা নিজের মধ্যে কেন্দ্রীভূত করা সংসদ জাতীয় ইচ্ছাভিত্তিক নতুন রাষ্ট্রের কেন্দ্র হলো। আগস্টে ইস্তানবুল সরকারের স্বাক্ষরিত সেভ্র চুক্তি আনাতোলিয়া ভাগ করছিল; সংসদ চুক্তি স্বাক্ষরকারীদের দেশদ্রোহী ঘোষণা করল এবং সেভ্র কখনোই কার্যকর হয়নি।", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["সাকারিয়া রণক্ষেত্রের যুদ্ধ", "f2f970a6"], "d": ["আঙ্কারার 50 কিলোমিটার পর্যন্ত এগোনো গ্রিক আক্রমণ প্রধান সেনাপতির দায়িত্ব নেওয়া মুস্তাফা কেমাল পাশার 'প্রতিরক্ষা রেখা নেই, প্রতিরক্ষা পৃষ্ঠ আছে' আদেশে চালানো 22 দিন 22 রাতের যুদ্ধে ভাঙল। গ্রিক সেনাবাহিনী প্রথমবার কৌশলগত প্রতিরক্ষায় গেল; বিজয় মুস্তাফা কেমালকে গাজি ও মুশির (মার্শাল) উপাধি এনে দিল, ফ্রান্সের সঙ্গে আঙ্কারা চুক্তি ও বহির্বিশ্বের স্বীকৃতির দরজা খুলল।", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["মহা আক্রমণ ও ইজমিরের মুক্তি", "172a50c4"], "d": ["26 আগস্ট সকালে কোজাতেপে থেকে শুরু হওয়া আক্রমণ 30 আগস্ট দুমলুপিনারে প্রধান সেনাপতির রণক্ষেত্রের যুদ্ধে গ্রিক প্রধান বাহিনী বিনষ্ট করল; 'সেনাবাহিনী, তোমাদের প্রথম লক্ষ্য ভূমধ্যসাগর, এগিয়ে চলো!' আদেশে চলা পশ্চাদ্ধাবনে 9 সেপ্টেম্বর ইজমির মুক্ত হলো। মুদানিয়া যুদ্ধবিরতিতে (11 অক্টোবর) পূর্ব থ্রেস যুদ্ধ ছাড়াই ফিরে এলো; সামরিক বিজয় লোজানে গড়া নতুন রাষ্ট্রের আলোচনার টেবিলের শক্তি নির্ধারণ করল।", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["সালতানাত বিলোপ", "9f36a9f6"], "d": ["লোজান আলোচনায় ইস্তানবুল সরকারকেও ডাকায় তুরস্কের গ্র্যান্ড ন্যাশনাল অ্যাসেম্বলি 1 নভেম্বর 1922 সালতানাত ও খিলাফত পৃথক করে সালতানাত বিলুপ্ত করল; 623 বছরের অটোমান রাজবংশীয় শাসন আইনত শেষ হলো। ষষ্ঠ মেহমেদ ভাহিদেদ্দিন 17 নভেম্বর একটি ব্রিটিশ যুদ্ধজাহাজে দেশ ছাড়লেন; খিলাফত পদে সংসদের সিদ্ধান্তে আবদুলমেজিদ এফেন্দিকে আনা হলো এবং এই পদও 3 মার্চ 1924 বিলুপ্ত হবে।", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["লোজান চুক্তি", "38c27f7d"], "d": ["আট মাসের কঠিন আলোচনার শেষে স্বাক্ষরিত লোজান শান্তি চুক্তিতে নতুন তুর্কি রাষ্ট্রের সীমানা, পূর্ণ স্বাধীনতা ও সার্বভৌমত্ব আন্তর্জাতিকভাবে স্বীকৃত হলো; কাপিতুলাসিয়ন বিলুপ্ত হলো, দুয়ুন-ই উমুমিয়ে বিলোপ প্রক্রিয়ায় গেল, জনসংখ্যা বিনিময় নির্ধারিত হলো। সেভ্রকে কার্যত বাতিল করা লোজান জাতীয় সংগ্রামের কূটনৈতিক বিজয় ও প্রজাতন্ত্রের প্রতিষ্ঠাকালীন বৈদেশিক দলিল গণ্য হয়।", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["প্রজাতন্ত্রের ঘোষণা", "d5bfcdfb"], "d": ["তুরস্কের গ্র্যান্ড ন্যাশনাল অ্যাসেম্বলি সংবিধান সংশোধনে 'তুরস্ক রাষ্ট্রের সরকারের রূপ প্রজাতন্ত্র' বিধান গ্রহণ করায় প্রজাতন্ত্র ঘোষিত হলো; মুস্তাফা কেমাল পাশা প্রথম রাষ্ট্রপতি নির্বাচিত হলেন। 1299 সালে সীমান্ত বেগলিক হিসেবে শুরু হওয়া 624 বছরের অটোমান যাত্রা এভাবে শেষ হলো, সার্বভৌমত্ব নিঃশর্তভাবে জাতির — এমন নতুন রাষ্ট্র সাম্রাজ্যের উত্তরাধিকারের ওপর গড়ে উঠল।", "f5cabb8c"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["আলানিয়া (আলাইয়ে) সেলজুক-পরবর্তী যুগে স্থানীয় বেইলিকের নিয়ন্ত্রণে গেল", "7b1489b3"], "d": ["আনাতোলিয়ান সেলজুক রাষ্ট্রের 1290-এর দশকে কার্যত ভেঙে পড়ায় ভূমধ্যসাগর উপকূলের আলাইয়ে (আলানিয়া) বন্দর কেন্দ্রীয় কর্তৃপক্ষ থেকে স্বাধীন হয়ে অঞ্চলের বেইলিকগুলোর (এই সময়ে কারামানোগ্লুদের প্রভাব-এলাকায়) নিয়ন্ত্রণে আসে; সঠিক তারিখ এবং কোন বেইলিক সরাসরি কর্তৃত্ব করেছিল তা সূত্রে স্পষ্ট নয়।", "78a4ff46"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["সিনোপ গাজি চেলেবি দখল করে চান্দারোগ্লু প্রভাবে আনলেন", "f107586a"], "d": ["ইলখানি কর্তৃত্বের দুর্বলতায় কাস্তামোনু ও সিনোপ অঞ্চলে শক্তিশালী হওয়া চান্দারোগ্লু (ইসফেন্দিয়ারোগ্লু) বেইলিকের প্রতিষ্ঠাতা পরিবারের গাজি চেলেবি 1322 সালের দিকে সিনোপ দখল করে শহরটিকে বেইলিকের একটি বন্দর কেন্দ্রে পরিণত করেন।", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["শিবেনিক শুবিচ কাউন্ট ও ভেনিসের মাঝে পড়ে ভেনিসের অধীন হল", "99b341e0"], "d": ["ক্রোয়াট সামন্ত ব্রিবির-এর শুবিচ কাউন্টদের ও ভেনিসের মাঝে পড়া শিবেনিক 1 মার্চ 1322 তারিখে নিজেকে ভেনিসের হাতে সঁপে দেয় এবং 1357 পর্যন্ত ভেনিস শাসনে থাকে।", "120581de"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["স্প্লিটে হাঙ্গেরীয় কর্তৃত্বের অবসান — ভেনিস শাসন শুরু", "4b04ca1a"], "d": ["স্প্লিট কমিউনে 1133 সাল থেকে চলা হাঙ্গেরীয় কর্তৃত্ব 18 সেপ্টেম্বর 1327 তারিখে শেষ হয়; শহর ভেনিস শাসনে আসে এবং 1357 পর্যন্ত সেখানে থাকে।", "75ef7dfc"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["জাদার চুক্তি — দুব্রোভনিক ভেনিস থেকে হাঙ্গেরির আশ্রয়ে গেল", "57fb81f9"], "d": ["18 ফেব্রুয়ারি 1358 তারিখে স্বাক্ষরিত জাদার চুক্তি ডালমাশিয়ার উপর ভেনিসের 150 বছরের কর্তৃত্বের অবসান ঘটায়; দুব্রোভনিক (রাগুসা) এভাবে ভেনিস শাসন থেকে বেরিয়ে হাঙ্গেরির রাজা প্রথম লায়োশের আশ্রয়ে আসা আধা-স্বায়ত্তশাসিত প্রজাতন্ত্রের মর্যাদা পায়।", "e207c893"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["এরজুরুম ও আশকালে অঞ্চল কারাকোয়ুনলু-তিমুরি প্রতিদ্বন্দ্বিতায় হাত বদলাল", "ca64775a"], "d": ["1405 সালে তৈমুরের মৃত্যুর পর সৃষ্ট ক্ষমতার শূন্যতায় কারাকোয়ুনলু শাসক কারা ইউসুফ 1406-1408 সালের মধ্যে পূর্ব আনাতোলিয়ার তিমুরি গভর্নরদের বিরুদ্ধে অভিযানে নামেন; এরজুরুম ও আশপাশের আশকালে এই লড়াইয়ে তিমুরি নিয়ন্ত্রণ থেকে বেরিয়ে কারাকোয়ুনলু প্রভাবে আসে।", "10b1b07c"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["আকোয়ুনলু উজুন হাসান হিসনকেইফা আইয়ুবি শাখা বিলুপ্ত করলেন", "2b464a1f"], "d": ["উচ্চ দজলায় হামার সঙ্গে আইয়ুবি রাজবংশের টিকে থাকা শেষ দুই শাখার একটি হিসনকেইফা (হাসানকেইফ) ও সিইর্ত 1462 সালে আকোয়ুনলু শাসক উজুন হাসান সংযুক্ত করে আইয়ুবি কর্তৃত্বের অবসান ঘটান।", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["পর্তুগাল হরমুজ প্রণালীর উপকূলে কর্তৃত্ব সম্পূর্ণ করল", "bef031f0"], "d": ["আফোনসু দি আলবুকের্কের 1507 সালে শুরু করা বসরা উপসাগর অভিযান 1515 সালে হরমুজ দ্বীপ এবং বিপরীত উপকূলের কিশম ও বুরাইমিসহ সম্পূর্ণ হয়; ইরানের অধীন হরমুজ রাজ্য কার্যত পর্তুগিজ আশ্রয়ে আসে এবং পর্তুগাল উপসাগরীয় বাণিজ্যের নিয়ন্ত্রণ হাতে নেয়।", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["লুবলিন ইউনিয়ন — ইউক্রেনীয় ভূমি লিথুয়ানিয়া থেকে পোল্যান্ডে গেল", "1881ceff"], "d": ["1 জুলাই 1569 তারিখে স্বাক্ষরিত লুবলিন ইউনিয়ন লিথুয়ানিয়ার গ্র্যান্ড ডাচি ও পোল্যান্ড রাজ্যকে একটি রাষ্ট্রে (রজেচপস্পোলিতা) একত্র করে। চুক্তির শর্ত অনুযায়ী পোডোলিয়া, ভলিনিয়া ও কিয়েভ অঞ্চল (বার, বের্দিচেভ, বিয়ালিস্টক, ব্রাস্লাভসহ) প্রশাসনিকভাবে লিথুয়ানিয়া থেকে সরাসরি পোল্যান্ড রাজ্যে হস্তান্তরিত হয়।", "184b03dd"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["মিসরীয় বাহিনী আহসা (লাহসা) অঞ্চল থেকে সরে গেল", "5ea75c8d"], "d": ["মেহমেদ আলি পাশার মিসরীয় বাহিনী 1836 সালে নজদ ও পূর্ব আরব (আহসা, কাতিফ, উকায়র, জুবাইলসহ) দখল করেছিল; 1840 সালের লন্ডন প্রণালী সনদ মিসরকে আরব উপদ্বীপে তার বিজয় ছাড়তে বাধ্য করলে বাহিনী 1841 সালে অঞ্চল থেকে সরে যায় এবং শাসন আবার স্থানীয় শক্তিগুলোর (সৌদি/আল খলিফা প্রভাব) হাতে যায়।", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["আক-মেচিত দুর্গ রুশ বাহিনীর হাতে দখল — কোকন্দ খানাতের সির দরিয়া রেখা ভেঙে পড়ল", "e9f9a9c7"], "d": ["জেনারেল ভাসিলি পেরোভস্কির নেতৃত্বাধীন রুশ বাহিনী কোকন্দ খানাতের সির দরিয়া তীরের আক-মেচিত দুর্গ 1853 সালের জুলাইয়ে দীর্ঘ অবরোধের পর দখল করে; দুর্গটি পরে পেরোভস্ক নামে রুশ তুর্কিস্তানের অগ্রবর্তী ঘাঁটি হয়।", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["গোকতেপে যুদ্ধ — আহাল তেকে তুর্কমেনরা রাশিয়ার কাছে পরাজিত", "76c7a102"], "d": ["জেনারেল মিখাইল স্কোবেলেভের নেতৃত্বাধীন রুশ বাহিনী 24 জানুয়ারি 1881 তারিখে গোকতেপে (গেওক তেপে) দুর্গের পতন ঘটিয়ে আহাল তেকে তুর্কমেনদের প্রতিরোধ ভাঙে; দিহিস্তান সমভূমি, আবিভের্দ ও নিসাসহ ট্রান্সক্যাস্পিয়ান তুর্কমেন অঞ্চল রুশ সাম্রাজ্যে যুক্ত হওয়ার প্রক্রিয়ায় প্রবেশ করে (ট্রান্সক্যাস্পিয়ান অঞ্চল 1881 সালে গঠিত)। এই ঘটনায় কিজিলআরভাত ও আশগাবাত (আহাল তুর্কমেন ভূমি) রাশিয়ায় যায়।", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["রোমানিয়া রাজ্য ঘোষিত — প্রিন্সিপালিটি রাজ্যে রূপান্তরিত", "4d413f0c"], "d": ["1877-78 সালের অটোমান-রুশ যুদ্ধের পর বার্লিন কংগ্রেসে স্বাধীনতা স্বীকৃত রোমানিয়া প্রিন্সিপালিটি 26 মার্চ 1881 তারিখে (জুলিয়ান ক্যালেন্ডারে 14 মার্চ) রাজা প্রথম কারোলের মুকুট পরার মাধ্যমে রাজ্যে রূপান্তরিত হয়; বাবাদাগ, ভিরলাদ, বুজাউ ও রাজধানী বুখারেস্টসহ পুরো দেশ প্রশাসনিকভাবে নতুন রাজ্যের অংশ হয়। রাজ্য ঘোষণার ফলে রোমানিয়ার পুরোটা (ইয়াশ, গালাতি, ব্রাইলা, কনস্তান্ৎসা, তুলচা, কালাফাত ও অন্যান্য শহর) রোমানিয়া রাজ্য হয়।", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["ইতালি আসমারা ও কেরেনসহ এরিত্রিয়ান মালভূমি সংযুক্ত করল", "31308dc8"], "d": ["আবিসিনিয়ার সম্রাট দ্বিতীয় ইওহান্নেসের 1889 সালের মৃত্যুতে সৃষ্ট ক্ষমতার শূন্যতার সুযোগ নেওয়া ইতালি উচ্চিয়ালি (ওয়াচালে) চুক্তির (2 মে 1889) পর আসমারা ও কেরেনসহ এরিত্রিয়ান মালভূমি কার্যত সংযুক্ত করে; 1 জানুয়ারি 1890 তারিখে আনুষ্ঠানিকভাবে 'এরিত্রিয়া' নামে উপনিবেশ ঘোষিত হয়। এই ঘটনায় কেরেন ইতালীয় শাসনে যায়।", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["কেনিয়ার উত্তর-পূর্ব অঞ্চল (গারিসা-মার্সাবিট রেখা) ব্রিটিশ পূর্ব আফ্রিকা প্রটেক্টরেটে যুক্ত হল", "e45c6d43"], "d": ["ইম্পেরিয়াল ব্রিটিশ ইস্ট আফ্রিকা কোম্পানির সনদ 1895 সালে রাজকীয় শাসনে হস্তান্তরিত হওয়ায় গঠিত ব্রিটিশ পূর্ব আফ্রিকা প্রটেক্টরেট গারিসা, কিতুই, মার্সাবিট ও ওয়াজিরের মতো উত্তর-পূর্ব অঞ্চলও অন্তর্ভুক্ত করে সম্প্রসারিত হয়; এই অভ্যন্তরীণ অঞ্চলগুলোর কার্যকর শাসনে আনা 1890-এর দশকের দ্বিতীয়ার্ধ জুড়ে ছড়ায়।", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["ইলোরিন আমিরাত রয়্যাল নাইজার কোম্পানির বাহিনীর হাতে দখল", "b111cb7d"], "d": ["সোকোতো খিলাফতের অধীন ইলোরিন আমিরাত স্যার জর্জ গোল্ডির নেতৃত্বাধীন রয়্যাল নাইজার কোম্পানির বাহিনীর 1897 সালের ফেব্রুয়ারি অভিযানে দখল হয়; আমিরাতের সামরিক শক্তি ভেঙে যায় এবং অঞ্চল কার্যত ব্রিটিশ প্রভাবে আসে (আনুষ্ঠানিক সংযুক্তি 1900 সালে উত্তর নাইজেরিয়া প্রটেক্টরেট প্রতিষ্ঠার মাধ্যমে সম্পূর্ণ হয়)।", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["বুনিয়োরোর রাজা কাবালেগা বন্দি হলেন, রাজ্য ব্রিটিশ উগান্ডা প্রটেক্টরেটের সঙ্গে যুক্ত হল", "62bc7c64"], "d": ["1894 সাল থেকে ব্রিটিশ বাহিনীকে প্রতিরোধ করা বুনিয়োরোর রাজা কাবালেগা 9 এপ্রিল 1899 তারিখে লাঙ্গো অঞ্চলে (দোকোলোর কাছে) ধরা পড়ে সেশেলসে নির্বাসিত হন; রাজধানী হোইমা ও মাসিন্দিসহ রাজ্যের ভূমি ব্রিটিশ উগান্ডা প্রটেক্টরেটে যুক্ত হয়।", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["তোরো চুক্তি — তোরো রাজ্য ব্রিটিশ উগান্ডা প্রটেক্টরেটের স্বায়ত্তশাসিত অংশ হল", "c55340a2"], "d": ["1899 সালে বুনিয়োরোর পতনের পর প্রতিবেশী তোরো রাজ্য 1896 সাল থেকে চলা ব্রিটিশ আশ্রয় 1900 সালের উগান্ডা চুক্তির কাঠামোতে আনুষ্ঠানিক করে; রাজধানী ফোর্ট পোর্টালসহ রাজ্য ব্রিটিশ উগান্ডা প্রটেক্টরেটের মধ্যে স্বায়ত্তশাসিত স্থানীয় শাসনের মর্যাদা পায়।", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["আদামাওয়া আমিরাত জার্মানি ও ব্রিটেনের মধ্যে ভাগ হল", "b9230d3d"], "d": ["সোকোতো খিলাফতের অধীন আদামাওয়া (ফোম্বিনা) আমিরাত জার্মান ও ব্রিটিশ উপনিবেশিক বাহিনীর 1899-1901 অভিযানের শেষে দুই ভাগ হয়: পূর্ব অংশ (গারুয়া, বানিও, মারুয়া, নগাউন্দেরেসহ) জার্মান ক্যামেরুনে, পশ্চিম অংশ (রাজধানী ইয়োলা) ব্রিটিশ উত্তর নাইজেরিয়ায় যুক্ত হয়; আমির জুবাইরকে নির্বাসনে পাঠানো হয়। এই ঘটনায় রে বুবা (আদামাওয়া (জার্মান অংশ)) জার্মান ক্যামেরুনের শাসনে যায়।", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["তিত যুদ্ধ — আহাগ্গার তুয়ারেগরা ফরাসি বাহিনীর কাছে পরাজিত", "831143d6"], "d": ["কোতেনেস্ত অভিযানের সময় 7 মে 1902 তারিখে তিত মরূদ্যানের কাছে সংঘটিত যুদ্ধে ফরাসি বাহিনী কেল আহাগ্গার তুয়ারেগদের চূড়ান্তভাবে পরাজিত করে; আহাগ্গারের কেন্দ্র আবালেসা ও ইদেলেসসহ সাহারার এই অভ্যন্তরীণ অঞ্চল ফরাসি আলজেরিয়ার নিয়ন্ত্রণে আসে।", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["ফরাসি বাহিনী উবাঙ্গি-শারির অভ্যন্তরীণ অঞ্চল (বাম্বারি-ব্রিয়া রেখা) দখল করল", "0b9a9f72"], "d": ["ফরাসি কঙ্গোর উত্তরমুখী অভিযান 1900-এর দশকের গোড়ায় বাম্বারি, বাতাঙ্গাফো, বোসাঙ্গোয়া ও ব্রিয়া নিয়ে উবাঙ্গি-শারির অভ্যন্তরীণ অঞ্চল কার্যত নিয়ন্ত্রণে আনে; অঞ্চলটি 29 ডিসেম্বর 1903 তারিখে আনুষ্ঠানিকভাবে উবাঙ্গি-শারি উপনিবেশ হিসেবে সংগঠিত হয় (ফরাসি নিরক্ষীয় আফ্রিকার অংশ)।", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["সুলতান মোহাম্মদ আস-সানুসির দার আল-কুতি সুলতানাত ফরাসি বাহিনীর হাতে বিলুপ্ত", "644b2c3f"], "d": ["1897 সালে ফরাসি আশ্রয়ে আসা, রাজধানী এনদেলে, দাসব্যবসা-ভিত্তিক দার আল-কুতি সুলতানাত সুলতান মোহাম্মদ আস-সানুসির ফরাসি কর্তৃত্বের বিরুদ্ধে প্রতিরোধ চালিয়ে যাওয়ায় 1911 সালে সংগঠিত একটি অভিযানে কার্যত বিলুপ্ত হয়; সানুসি যুদ্ধে নিহত হন, সুলতানাত 1912 সালে আনুষ্ঠানিকভাবে বাতিল হয়।", "3f913340"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["সেনুসিয়ার মরু কেন্দ্র জাগবুবের অটোমান ব্যবস্থার সঙ্গে যুক্ত হওয়া — আবদুলমেজিদের অব্যাহতি ফরমান", "039fce6d"], "d": ["বহু বছর মক্কায় থাকা মুহাম্মদ ইবনে আলী আস-সেনুসি ত্রিপোলিতানিয়ায় ফিরে মিশর সীমান্তের জাগবুব মরূদ্যানে বসতি স্থাপন করে প্রভাবশালী পাথুরে টিলায় বিশাল জাভিয়া নির্মাণ করালেন; কয়েকটি কুঁড়েঘরের স্থানটি অল্প সময়ে শহরে পরিণত হলো। 1856 সালে সুলতান আবদুলমেজিদের ফরমানে তরিকার সদস্যদের সম্পত্তি কর থেকে অব্যাহতি পেল এবং মুরিদদের কাছ থেকে জাকাত সংগ্রহের ক্ষমতা দেওয়া হলো। এই ফরমান পশ্চিম আফ্রিকা ও সুদানকে কায়রোর সঙ্গে যুক্ত করা কাফেলা পথের ওপরের মরূদ্যানকে অটোমান আর্থিক ও প্রশাসনিক ব্যবস্থার অংশ বানালো এবং জাগবুবকে বাণিজ্যকেন্দ্র হিসেবে শক্তিশালী করলো। অঞ্চলের জনগণের খলিফার প্রতি আনুগত্য 1884 ও 1893 সালে এটি পরিদর্শনকারী মিরালায় সাদিক আল-মুয়াইয়েদের ভ্রমণবৃত্তান্ত দিয়েও নিশ্চিত হয়।", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["সুয়েজ খাল খননের শুরু ও পোর্ট সাইদের প্রতিষ্ঠা", "cef0be8d"], "d": ["বাব-ই আলি 5 জানুয়ারি 1856 তারিখে অনুমোদন দেওয়া লেসেপ্স প্রকল্পের খনন কাজ 25 এপ্রিল 1859 তারিখে শুরু হলো; খাল দশ বছর পর, 16 নভেম্বর 1869 তারিখে সমাপ্ত হবে। খননের ভূমধ্যসাগরীয় প্রান্তে মেনজালা হ্রদ ও সাগরের মধ্যবর্তী উপকূলীয় ফালিতে শ্রমিকদের জন্য স্থাপিত পাঁচ ঘরের কুঁড়ে গ্রাম পোর্ট সাইদের কেন্দ্র গড়লো। খাল কোম্পানির কর্মকর্তারা সে সময়ের মিশরীয় গভর্নর সাইদ পাশাকে উৎসর্গ করে 1860 সালে শহরকে 'সাইদ বন্দর' অর্থবোধক এই নাম দিলেন। এভাবে অটোমান মানচিত্রে আগে কোনো বসতি না থাকা উপকূলীয় ফালিতে নতুন বন্দর জন্ম নিলো।", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["সুলতান আবদুলআজিজের মিশর সফর ও সুয়েজ যোজকে ইসমাইলিয়ার প্রতিষ্ঠা", "bcfacf38"], "d": ["সুলতান আবদুলআজিজ প্রধান উজির ইউসুফ কামিল পাশার উৎসাহে 3 এপ্রিল 1863 তারিখে মিশরে গেলেন এবং বিপুল উল্লাসে অভ্যর্থিত হলেন; উদ্দেশ্য ছিল কাভালালি মেহমেদ আলী পাশার বিদ্রোহের পর থেকে কার্যত আলাদা রাষ্ট্রের রূপ নিতে শুরু করা প্রদেশের কেন্দ্রের প্রতি আনুগত্য শক্তিশালী করা। একই বছর যোজকে তিমসাহ হ্রদের তীরে তিলালুলজিসর টিলায় খাল কোম্পানির প্রশাসনিক কেন্দ্র স্থাপিত হলো: প্রথমে প্রকৌশলীদের জন্য কারিয়েতুত্তিমসাহ, পরে শ্রমিকদের জন্য কারিয়েতুলআরাব গ্রাম বসানো হলো। খেদিভ ইসমাইল পাশা মিষ্টি পানির খালের প্রতি ঘনিষ্ঠ আগ্রহী হয়ে এই টিলায় নিজের জন্য একটি কুটির নির্মাণ করালে বসতি তাঁর নামে ইসমাইলিয়া হিসেবে পরিচিত হলো। শহরের প্রতিষ্ঠা 1863 সালের; সঠিক দিন জানা নেই।", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["মিদহাত পাশার বাগদাদ গভর্নরত্ব ও গোত্র বসতিস্থাপন — রামাদি ও নাসিরিয়ার প্রতিষ্ঠা", "0fa98f06"], "d": ["শুরা-ই দেভলেত প্রধানের পদ থেকে সরিয়ে ইস্তানবুল থেকে দূরে পাঠানো মিদহাত পাশা মোসুল ও বসরাকেও অন্তর্ভুক্ত করা বাগদাদ প্রদেশ 1869-1872 সালে ষষ্ঠ সেনাবাহিনীর অধিনায়কত্বও নিজের দায়িত্বে রেখে ব্যাপক ক্ষমতায় পরিচালনা করলেন। আরাজি আইনসংকলন ও নতুন প্রদেশ আইন এখানে প্রয়োগ করে ভূমি টাপু দিয়ে বণ্টন করলেন, যাযাবর গোত্রদের স্থায়ী ব্যবস্থা ও রাষ্ট্রীয় কর্তৃত্বে বাঁধলেন। এই বসতিস্থাপন নীতির ফল হিসেবে 1869 সালে ফোরাত তীরে দুলাইম গোত্রের জন্য রামাদি এবং দক্ষিণে মুনতেফিক মুতাসারিফ নাসির পাশা আস-সাদুনের হাতে নাসিরিয়া স্থাপিত হলো; দুটিই সেদিন পর্যন্ত বসতি না থাকা স্থানে জন্ম নিয়ে মানচিত্রে প্রথমবার এই তারিখে এলো।", "7babb36f"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["আঙ্কারা বিপর্যয়ের পর ওয়ালাচিয়া ভয়েভোদা মির্চা দোবরুজা পুনরায় নিলেন — সিলিস্ত্রা, কনস্তান্তা, বাবাদাগ, ইসাকচা", "5eaefc68"], "d": ["ইলদিরিম বায়েজিদের আঙ্কারায় তৈমুরের কাছে পরাজয় দানিউব তীরের অটোমান আধিপত্যকে নাড়া দিল। ওয়ালাচিয়া ভয়েভোদা মির্চা এই শূন্যতার সুযোগ নিয়ে দোবরুজায় আবার প্রবেশ করলেন; সিলিস্ত্রা, কনস্তান্তা, বাবাদাগের আশেপাশে এবং দানিউব তীরের ইসাকচা ফেত্রেত বছরগুলো জুড়ে তাঁর হাতে থাকলো। মির্চা চেলেবি মেহমেদের বিরুদ্ধে মুসা চেলেবিকে সমর্থন করলেন। সিলিস্ত্রা 1418 সালে মৃত্যু পর্যন্ত ধরে রাখলেন।", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["বাবাদাগ ও আশেপাশের অটোমানদের হাতে যাওয়া — মির্চা ও পুত্র মিহাইল পরাজিত", "bfda2c60"], "d": ["চেলেবি মেহমেদ ওয়ালাচিয়া ভয়েভোদা মির্চা ও পুত্র মিহাইলকে পরাজিত করার পর উত্তর দোবরুজার বাবাদাগ ও আশেপাশে অটোমান আধিপত্যে নিলেন। বাবাদাগ সালতুক বাবার নাম বহনকারী এবং ত্রয়োদশ শতকের তুর্কমেন বসতিতে গড়া শহর ছিল। আশেপাশের সিলিস্ত্রা, কনস্তান্তা ও অন্য দোবরুজা দুর্গগুলো অবশ্য 1419 সাল পর্যন্ত ওয়ালাচিয়ায় থাকলো; অর্থাৎ বাবাদাগ তিন বছর অটোমান ভূখণ্ড থেকে বিচ্ছিন্ন দ্বীপ (এক্সক্লেভ) হিসেবে দেখা যায়।", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["সিলিস্ত্রা ও দোবরুজার পুনরুদ্ধার — মির্চার মৃত্যুর পর", "73eb6ae9"], "d": ["ওয়ালাচিয়া ভয়েভোদা মির্চার 1418 সালে মৃত্যুর পর ওয়ালাচিয়ায় সৃষ্ট বিশৃঙ্খলা চেলেবি সুলতান মেহমেদকে সিলিস্ত্রা ও দোবরুজা ফিরিয়ে নেওয়ার সুযোগ দিল। 1419 সালের বসন্তে সিলিস্ত্রা, কনস্তান্তা ও দোবরুজার বড় অংশ আবার অটোমান শাসনে এলো; এনিসালা (ইয়েনিসালে) ও ইসাকচা দুর্গ মেরামত করে সীমান্ত দুর্গ (সেরহাত) করা হলো; দোবরুজা এরপর 1878 সাল পর্যন্ত অটোমানদের থাকলো।", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["নিম্ন দানিউব বন্ধ — ইয়ের্গোগু, তুরনু ও ওরশোভার অন্তর্ভুক্তি", "331a0b68"], "d": ["ফেত্রেত যুগ শেষ হওয়ার পর চেলেবি মেহমেদের দানিউব রেখা শৃঙ্খলে আনার উদ্যোগ 1420 সালে ফল দিল। ওয়ালাচিয়া ভয়েভোদা কোজা মির্চার নিজের ভূখণ্ডে লবণ বিক্রির আয়ে ব্যয় মিটিয়ে নির্মাণ করানো ইয়ের্গোগু দুর্গ এই বছর অটোমান হাতে গেল (দোবরুজা এক বছর আগে, 1419 সালের বসন্তে পুনরুদ্ধার হয়েছিল — TDV silistre) এবং দানিউবের ডান তীরের তুরনু (কুলে/হোলোভনিক) ও ওরশোভা — পরবর্তী নাম ফেথুলইসলাম — অন্তর্ভুক্ত হলো। এভাবে নদীর দুই তীরই একসঙ্গে নিয়ন্ত্রণে এলো। ইয়ের্গোগুর গুরুত্ব তার ভূগোল থেকে: এটি দানিউবের বাম, অর্থাৎ ওয়ালাচিয়া তীরে স্থাপিত অটোমান দুর্গ এবং বিপরীত তীরের রুসচুকের সঙ্গে একই পারঘাটের দুই প্রান্ত ধরে রাখে। অটোমান নথিগুলো এই দ্বৈততা স্পষ্ট লেখে — রুসচুকের জন্য 'ইয়ের্গোগু এদিকের তীর', জিউরজিউর জন্য 'ইয়ের্গোগু ওপারের তীর' বলা হয়। দুর্গ 1427 সালে ওয়ালাচিয়ানদের হাতে ফিরে যাবে, 1449 সালে আবার অটোমান নিয়ন্ত্রণে আসবে এবং ইয়ের্গোগু কাজা নিগবোলু সানজাকের সঙ্গে যুক্ত হয়ে ভয়েভোদালিকের ভেতরে সরাসরি শাসিত দ্বীপে পরিণত হবে। মানচিত্রে ওয়ালাচিয়ার দানিউব তীর কেন গাঢ় রঙের তার উত্তর এখান থেকে শুরু।", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["তোপলিৎসা অঞ্চল (কুরশুমলিয়া, উরকুপ) অটোমান আধিপত্যে এলো", "e22e690d"], "d": ["দ্বিতীয় মুরাদের মারা ব্রাঙ্কোভিচের সঙ্গে বাগদানের সময় দুবোচিৎসা ও তোপলিৎসা অঞ্চল (লেস্কোভাৎস, কুরশুমলিয়া ও উরকুপের আশেপাশে) অটোমান আধিপত্যে যাওয়ার সম্ভাবনা বেশি দেখা যায়; 1445-1447 তাহরির নথি অঞ্চলটি অটোমান সিপাহিদের তিমার হিসেবে দেওয়া হয়েছিল বলে দেখায়। মানচিত্রে কুরশুমলিয়া ও উরকুপ এই বছর থেকে অটোমান শাসনে।", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["সারায় সমভূমির অন্তর্ভুক্তি — বসনিয়ার ভেতরে অটোমান প্রান্ত স্থাপন", "be5c0f00"], "d": ["বসনিয়ার রাজারা 1428-1429 সালে করের আওতায় আসার পর অটোমানরা রাজ্যের ভেতরের দিকে স্থায়ীভাবে বসতি গড়তে শুরু করলো। 1428-1435 সালের মধ্যে হোদিদ্জেদ শহর নেওয়া হলো; 852 (1448) সালে হোদিদ্জেদ প্রদেশ সারায় সমভূমিসহ সম্পূর্ণ অটোমান শাসনে এলো। এটি বসনিয়া বিজয়ের পনেরো বছর আগে রাজ্যের মাঝখানে গড়া প্রান্ত এলাকা এবং ভয়েভোদা উপাধিধারী উস্কুপ বে ইসা বে দ্বারা পরিচালিত হয়েছিল — আশেপাশে তখনও অটোমানদের অধীন বসনিয়ার বেরা থাকায় অঞ্চল দ্বিমুখী নিয়ন্ত্রণে ছিল। শহরটিও এই সময়ে জন্ম নিল: 1462 সালের আগে ইসহাক বে বা পুত্র ইসা বে প্রথম মুসলিম মহল্লা গড়লেন, 862 (1458) সালে ফাতিহের নামে হুনকার মসজিদ নির্মিত হলো এবং ব্রোদেৎস গ্রামের শস্যক্ষেত উন্নীত হয়ে সারায় শহর আত্মপ্রকাশ করলো। 1463 সালের বিজয় বসনিয়া রাজ্য বিলুপ্ত করলো; সারায় সমভূমি সেই তারিখে ইতিমধ্যেই পনেরো বছর অটোমান ভূখণ্ড ছিল।", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["পোদগরিতসার অটোমান ভূখণ্ডে যুক্ত হওয়া — জেতা সমভূমির নিয়ন্ত্রণ", "46e401c5"], "d": ["শকোদার হ্রদের বিশ কিলোমিটার উত্তরে মোরাচা ও রিবনিৎসা জলধারা মিলিত সমভূমিতে স্থাপিত শহর সূত্রে প্রথম 1216 সালে রিবনিৎসা, 1326 সালে পোদগরিতসা নামে উল্লিখিত। 1457 সালে অটোমান ভূখণ্ডে যুক্ত হলো এবং জেতা সমভূমির নিয়ন্ত্রণ এভাবে বালশিচ-ক্রনোয়েভিচ রাজবংশের হাত থেকে বেরিয়ে গেল। ফাতিহ সুলতান মেহমেদ 1474-1478 সালের মধ্যে দুই নদীর সংযোগস্থলের খাড়া পাথুরে ঢালে একটি দুর্গ ও মসজিদ নির্মাণ করালেন; 1479 সালে শকোদার বিজয়ের পর অঞ্চল নতুন গঠিত শকোদার সানজাকের সঙ্গে যুক্ত হলো। 1485 তাহরিরে চল্লিশ ঘরের খ্রিস্টান শহর থাকা পোদগরিতসা 1529-30 সালে 800 জনে এবং দুর্গের ভেতরে একজন দিজদারের অধীন বত্রিশজনের গ্যারিসনে, 1582 সালে 322 ঘরে পৌঁছালো। এভলিয়া চেলেবি 1662 সালে ফাতিহ দুর্গে তিনশ ঘর, গুদাম, অস্ত্রাগার ও সাতশ রক্ষী গুনলেন। এই নথিগুলো জেতার সমভূমি ও পর্বতের মধ্যকার পার্থকিও দেখায়: সমভূমি গণনা, কর আরোপ ও গ্যারিসনযুক্ত অটোমান কাজা — অথচ অষ্টাদশ শতকে শহর মন্টিনিগ্রোর পর্বতের গোত্রদের হানা ঠেকাতে ছয়টি দুর্গ ও তিন ফটকের প্রাচীরে সুরক্ষিত হতে বাধ্য হবে। পোদগরিতসা 1876-1878 যুদ্ধের শেষ দিকে মন্টিনিগ্রোর হাতে গেল এবং বার্লিন চুক্তিতে সেখানেই থাকলো।", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["ফোচা দখল — হার্জেগোভিনা ডাচিতে প্রথম প্রবেশের পথ খোলা", "f098a9e6"], "d": ["বসনিয়া রাজ্য 1463 সালে বিলুপ্ত হওয়ার পর রাজ্য থেকে আলাদা হয়ে নিজের ডাচি গড়া স্তেপান ভুকচিচ-কোসাচার ভূখণ্ডের পালা এলো। দ্রিনা উপত্যকায় ইস্তানবুলকে দুব্রোভনিকের সঙ্গে যুক্ত করা বাণিজ্যপথের সংযোগস্থলে অবস্থিত ফোচা 1465 সালে অটোমান শাসনে এলো। শহরের গুরুত্ব তৎক্ষণাৎ বোঝা গেল: 1470 সালে নতুন গঠিত হার্জেগোভিনা সানজাকের কেন্দ্র করা হলো — অর্থাৎ হার্জেগোভিনার প্রশাসনিক কেন্দ্র ডাচি নিজে ভাঙার আগেই ফোচায় স্থাপিত হলো। ডাচির সম্পূর্ণ অন্তর্ভুক্তি 1483 সাল পর্যন্ত চলবে। ফোচা এরপর অনুকূল জলবায়ু ও পথের সংযোগস্থলের অবস্থানের কারণে বাণিজ্য ও প্রশাসনের কেন্দ্র হিসেবে বিকশিত হলো। মানচিত্রে এই তারিখ বসনিয়া বিজয়ের পর দক্ষিণে দ্বিতীয় তরঙ্গ শুরু হওয়ার দিন।", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["লিভনো ও পশ্চিম বসনিয়ার চূড়ান্ত অন্তর্ভুক্তি — ভেনিসীয় সীমান্ত স্থাপন", "c14d4283"], "d": ["লিভনো সমভূমির ওপর কর্তৃত্বকারী মালভূমির দুর্গ 1448-1454 সালের মধ্যে হার্জেগোভিনা ডাচির প্রতিষ্ঠাতা স্তেপান ভুকচিচ-কোসাচার হাতে ছিল। 1463 বসনিয়া অভিযানে অল্প সময়ের জন্য অটোমান বাহিনী দখল করেছিল, কিন্তু একই বছর ফিরিয়ে নেওয়া হয়েছিল; 1466 সালে শহরের কর্তা ইভানিশ ভ্লাতকোভিচ। TDV-এর ভাষায় চূড়ান্ত অটোমান আধিপত্য খুব সম্ভব 1468-1469 সালে ঘটলো এবং 1485 তাহরির লিভনোকে এখন অটোমান ভূখণ্ড হিসেবে নথিভুক্ত করে। এটি বসনিয়া বিজয়ের পশ্চিম প্রান্ত বন্ধ হওয়া: লিভনো, সমতল সমভূমি বরাবর কেবল ছত্রিশ কিলোমিটার দূরের ভেনিসীয় ভূখণ্ডের প্রতিবেশী, বিপজ্জনক সীমান্ত শহরে পরিণত হলো এবং এই অবস্থান 1521-1522 সালে বসনিয়ার গভর্নর গাজি হুসরেভ বের ভেনিসীয় দুর্গ দখল পর্যন্ত বজায় রাখলো।", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["বোগুরদেলেনের হাঙ্গেরীয়দের হাতে হারানো — সাভা রেখায় প্রথম ফাটল", "129fe8f2"], "d": ["ফাতিহ সুলতান মেহমেদের সময় অটোমান হাতে আসা এবং আগে জাসলন নামে পরিচিত স্থানে 1471 সালে কাঠ ও মাটির একটি দুর্গ নির্মিত হয়েছিল। বেলগ্রেডকে হুমকি দেওয়া স্থানে অবস্থিত হওয়া এবং এখান থেকে হাঙ্গেরি ও অস্ট্রিয়ার দক্ষিণ অঞ্চলে সহজে হানা দেওয়া যেত বলে দুর্গ নামও এই কাজ থেকে নিয়েছিল — বোগুরদেলেন মানে 'পার্শ্বে আঘাতকারী দুর্গ'। হাঙ্গেরীয় রাজা মাতিয়াস করভিনুস 1475 সালের শেষ দিকে দুর্গ অবরোধ করলেন এবং 1476 সালের ফেব্রুয়ারিতে দখল করলেন। অবরোধ বর্ণনাকারী Szabács viadala নামের হাঙ্গেরীয় মহাকাব্য পঞ্চদশ শতকের হাঙ্গেরীয় ঐতিহাসিক কবিতাগুলোর মধ্যে আজ পর্যন্ত টিকে থাকা সবচেয়ে দীর্ঘ পাঠগুলোর একটি। হাঙ্গেরীয়রা অঞ্চলে একটি ব্যানাত গঠন করলো এবং দুর্গ পাথরে পুনরায় সুরক্ষিত করে সীমান্ত দুর্গ শৃঙ্খলের সংযোগ বানালো। অটোমানরা 1492 সালে ফিরিয়ে নেওয়ার চেষ্টা করে ব্যর্থ হলো; দুর্গ পঁয়তাল্লিশ বছর হাঙ্গেরীয় হাতে থাকলো।", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["আয়োনীয় দ্বীপপুঞ্জ জয় — তোক্কো ডাচির অবসান: আয়ামাভরা, কেফালোনিয়া, জাকিন্থোস, ইথাকা", "07b27251"], "d": ["একই বছরের জানুয়ারিতে ভেনিসের সঙ্গে স্বাক্ষরিত ইস্তানবুল চুক্তি শকোদার ও আলবেনীয় উপকূল অটোমানদের হাতে রেখেছিল; আয়োনীয় দ্বীপপুঞ্জ অবশ্য ভেনিসের নয়, কেফালোনিয়া-জাকিন্থোস কাউন্টি ধরে রাখা তোক্কো পরিবারের শাসনে ছিল এবং আলাদা অভিযানে দখল হলো। TDV-এর আয়ামাভরা ভুক্তি অনুযায়ী শেষ ডিউক লেওনার্দো তোক্কো প্রথমে ফাতিহের আত্মীয় মিলিৎসা ব্রাঙ্কোভিচকে বিয়ে করে আনুগত্য রক্ষা করেছিলেন, 1464 সালে স্ত্রী মারা গেলে 1477 সালে নেপলস রাজবংশের ফ্রান্সেসকা মার্জানোকে বিয়ে করে সুলতানকে অসন্তুষ্ট করেছিলেন। দুই বছর পর আভলোনার বে গেদিক আহমেদ পাশার নেতৃত্বাধীন নৌবহর আয়ামাভরাকে দক্ষিণের কেফালোনিয়াসহ দখল করলো; লেওনার্দো ও ফ্রান্সেসকা ইতালিতে পালালেন। গেদিক আহমেদ পাশা ভুক্তি একই অভিযানে জাকিন্থোসও (জান্তে) দখল হয়েছিল বলে লেখে; কেফালোনিয়া কাউন্টির অধীন ইথাকাও এই সময়ে অটোমান শাসনে এলো। এভাবে আদ্রিয়াটিকের মুখ থেকে মোরা পর্যন্ত বিস্তৃত সমুদ্রপথ সম্পূর্ণ নিয়ন্ত্রণে এলো। দ্বীপগুলোর মধ্যে জাকিন্থোস তিন বছর পর ভেনিসকে ছেড়ে দেওয়া হবে, কেফালোনিয়া ও ইথাকা 1500 সালে হারাতে হবে, কেবল আয়ামাভরা দুইশ বছর অটোমান থাকবে।", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["ক্রনোয়েভিচ জেতার আনুগত্য ও চেতিনিয়ের কেন্দ্র হয়ে ওঠা", "59d20267"], "d": ["1479 সালে শকোদার অটোমানদের হাতে থাকায় তার পেছনের উঠোনের জেতা পার্বত্য অঞ্চলও সাম্রাজ্যের সীমানার ভেতরে পড়লো। অঞ্চল ধরে রাখা ক্রনোয়েভিচ পরিবার ফাতিহের মৃত্যুর পর সিংহাসনে বসা দ্বিতীয় বায়েজিদের শাসন স্বীকার করে করের আওতায় এসে অভ্যন্তরীণ বিষয়ে স্বাধীন থাকলো; ইভান ক্রনোয়েভিচ কেন্দ্র সমভূমি থেকে সরিয়ে লভচেন পর্বতের পাদদেশের চেতিনিয়েতে নিলেন এবং শহর প্রতিষ্ঠা করলেন। দুই বছর পর সেখানে নির্মাণ করানো মঠ অঞ্চলের ধর্মীয় কেন্দ্র হলো। এভাবে মন্টিনিগ্রো মানচিত্রে সরাসরি অটোমান ভূখণ্ড হিসেবে নয়, হালকা রঙে করদ অঞ্চল হিসেবে দেখা দেয়। TDV-এর Karadağ ভুক্তি রাজবংশ ও চেতিনিয়ে বিশপরাজ্য উল্লেখ করে, 1514 সালে আধিপত্য ইসকেন্দার বে (ক্রনোয়েভিচ বংশের, অটোমান প্রাসাদে বেড়ে ওঠা) কর্তৃক আলাদা সানজাকে রূপ নেয় বলে লেখে; 1482 সাল TDV-তে নেই, মন্টিনিগ্রো ইতিহাসচর্চা দেওয়া তারিখ। ভূগোলের কঠোরতার কারণে এখানকার প্রশাসন কখনো সমভূমির মতো কঠোরভাবে চলেনি।", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["কিলিয়া দুর্গ জয় — দানিউব মোহনার তালা", "ef4eca73"], "d": ["বোগদান 1455 সালের সেপ্টেম্বর থেকে বছরে দুই হাজার স্বর্ণমুদ্রা কর দেওয়া করদ ভয়েভোদালিক ছিল, কিন্তু কৃষ্ণসাগরে খোলা দুটি বন্দর তখনও ভয়েভোদার হাতে ছিল এবং দানিউব থেকে আসা বাণিজ্য সেখান দিয়ে যেত। দ্বিতীয় বায়েজিদ সালতানাতের প্রথম বড় অভিযান এই দুই বন্দরের দিকে চালালেন। দশ দিন দিনরাত গোলাবর্ষণ করা কিলিয়া দুর্গের অধিনায়ক আত্মসমর্পণে বাধ্য হলেন। দুর্গ সরাসরি অটোমান প্রশাসনে নিয়ে সানজাক বেইত্বে পরিণত করা হলো; ষোড়শ শতকের দ্বিতীয়ার্ধে কসাক হুমকির কারণে কাজা করে রুমেলি বেইলারবেইত্বের অধীন আক্কেরমান সানজাকের সঙ্গে যুক্ত করা হলো। এখান থেকে বোগদান মানচিত্রে দুই স্তরে দেখা দেয়: ভেতরে ভয়েভোদালিক হালকা রঙে করদ ভূখণ্ড হিসেবে থাকে, উপকূলের দুই বন্দর গাঢ় রঙে সরাসরি অটোমান সানজাক। TDV-এর Boğdan ভুক্তি এই দুটিকে 'বোগদানের চাবি ও দরজা' বলে উল্লেখ করে এবং অঞ্চল দ্বিতীয় বায়েজিদের সময় নিশ্চিতভাবে অটোমানদের সঙ্গে যুক্ত হয়েছিল বলে লেখে।", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["আক্কেরমান জয় — দনিস্টার মোহনা ও বোগদানের কৃষ্ণসাগর দরজা বন্ধ", "7cb20feb"], "d": ["কিলিয়ার আত্মসমর্পণের বিশ দিন পর সেনাবাহিনী দনিস্টার মোহনার আক্কেরমানের সামনে এলো এবং দুর্গ 4 আগস্ট দখল হলো। শহর বোগদানের সবচেয়ে ব্যস্ত বন্দর ছিল; ফাতিহের যুগে ভয়েভোদা তৃতীয় পেত্রু 1455 সালে অটোমান আধিপত্য স্বীকার করলে আক্কেরমান বণিকদের বাণিজ্যের অনুমতি দেওয়া হয়েছিল, এখন বন্দর সরাসরি রাষ্ট্রের হলো। জয়ের পর রুমেলি বেইলারবেইত্বের অধীন সানজাক করা আক্কেরমান 1593 সালে নতুন গঠিত ওজি প্রদেশে যুক্ত হলো। এভাবে বোগদানের উত্তরে খোতিন, দক্ষিণে কিলিয়া ও আক্কেরমান দিয়ে ঘেরা বাইরের খোলস অটোমানদের সরাসরি নিয়ন্ত্রণে আসতে শুরু করলো; ভয়েভোদালিক অভ্যন্তরীণ বিষয়ে স্বাধীন থাকলো কিন্তু সাগরে প্রবেশের পথ থাকলো না। মানচিত্রে মাঝে কোনো ফাঁকা অঞ্চল নেই — গাঢ় রঙের বন্দর সানজাক ও হালকা রঙের ভয়েভোদালিক ভূখণ্ড পরস্পর স্পর্শ করে; দুইয়ের মাঝের বুজাক স্তেপ 1538 সাল পর্যন্ত তখনও ভয়েভোদালিকের অংশ।", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["ইনেবাখতির আত্মসমর্পণ — করিন্থ উপসাগরের মুখ ভেনিসের কাছ থেকে নেওয়া হলো", "2cfe0777"], "d": ["ইনেবাখতি 1407 সাল থেকে ভেনিসের হাতে ছিল এবং করিন্থ উপসাগরের মুখ ধরে রেখেছিল; উপসাগরের ভেতরের সমগ্র উপকূল এই দুর্গের পাল্লায় বাঁধা ছিল। 1499 অভিযানে দুর্গ স্থলপথে অবরুদ্ধ হলো, ইনেবাখতির উপকূলে ভেনিসীয় নৌবহরের সঙ্গে লড়া অটোমান নৌবহর সমুদ্র থেকে অবরোধকারী বাহিনীকে সহায়তা করলো। দুর্গের ভেনিসীয়রা 26 আগস্ট শহর অটোমানদের কাছে হস্তান্তর করলো। শহর এরপর একশ আটাশি বছর অটোমান থাকলো, 1687 সালে মোরা হারানোর সঙ্গে আবার ভেনিসের হাতে গেল, 1715 সালে পুনরুদ্ধার হলো। একই গ্রীষ্মের নৌযুদ্ধ ও এই আত্মসমর্পণ দুটি আলাদা ঘটনা: নৌবহরের সংঘর্ষ মোরার পশ্চিম প্রান্তে, সাপিয়েঞ্জা-জোনকিও জলে ঘটলো; ইনেবাখতি অন্যদিকে করিন্থ উপসাগরের মুখে স্থল অবরোধে পতিত হলো।", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["স্রেব্রেনিক ব্যানাতের অন্তর্ভুক্তি — উত্তর বসনিয়ায় হাঙ্গেরীয় রেখার প্রথম ভাঙন", "6d98c725"], "d": ["বসনিয়া রাজ্য 1463 সালে ধসে পড়ার পর মাতিয়াস করভিনুস পাল্টা আক্রমণে গিয়ে রাজ্যের উত্তরে অটোমান অগ্রগতি থামানো দুটি ব্যানাত গড়েছিলেন: পশ্চিমে ইয়ায়চে, উত্তর-পূর্বে স্রেব্রেনিক। এগুলো বসনিয়ায় হাঙ্গেরির অগ্রবর্তী প্রতিরক্ষা রেখা ছিল এবং সাভা ও বসনার মধ্যবর্তী করিডর বন্ধ করে রেখেছিল। স্রেব্রেনিক ব্যানাত 1512 সালে দখল হলো; এভাবে রেখার পূর্ব বাহু ধসে গেল এবং ইজভর্নিক সানজাক উত্তরের দিকে বিস্তৃত হতে পারলো। পশ্চিম বাহুর ইয়ায়চে আরও ষোলো বছর টিকবে, মোহাচের পর কেবল 1528 সালে দখল হবে।", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["বোগুরদেলেন জয় — কানুনির নেওয়া প্রথম দুর্গ এবং বেলগ্রেড সিদ্ধান্তের স্থান", "85177a90"], "d": ["কানুনি সুলাইমানের প্রথম হাঙ্গেরি অভিযানে অঞ্চলে পাঠানো রুমেলি বেইলারবেই আহমেদ পাশার বাহিনী তীব্র অবরোধের পর দুর্গ 7 জুলাই 1521 তারিখে নিল। বোগুরদেলেন কানুনির সালতানাতে বিজিত প্রথম দুর্গ। সুলতান জয়ের পর নিজে দুর্গে প্রবেশ করে শহরের উন্নয়নের আদেশ দিলেন; বেলগ্রেড জয়ের সিদ্ধান্তও এখানেই নেওয়া হলো — অর্থাৎ 29 আগস্ট 1521 তারিখে পতিত হতে যাওয়া বেলগ্রেডের পরিকল্পনা বোগুরদেলেনে হলো। দুর্গ এরপর প্রায় দুইশ বছর অটোমান হাতে থাকলো; প্রথমে রুমেলি, 1580 সাল থেকে বসনিয়া প্রদেশের, এরপর অল্প সময় সেমেন্দিরে এবং সবশেষে ইজভর্নিক সানজাকের অধীন হলো। মানচিত্রে এই তারিখ সাভা রেখা অটোমানদের পক্ষে বন্ধ হওয়ার দিন।", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["তিন ভয়েভোদালিকের বিদ্রোহ শুরু — ট্রান্সিলভানিয়া পবিত্র মৈত্রীতে গেল, অটোমানপন্থী বেরা গ্রেপ্তার", "68a33800"], "d": ["দীর্ঘ যুদ্ধের দ্বিতীয় বছরে মধ্য ইউরোপে অটোমানদের করদ বলয় হঠাৎ ভেঙে পড়লো। পোপ অষ্টম ক্লেমেন্টের আশ্রয়ে গঠিত পবিত্র মৈত্রীতে গ্রীষ্মের শেষে বোগদান ও ট্রান্সিলভানিয়া যোগ দিল: বোগদান ভয়েভোদা আরন ভোদা 16 আগস্ট 1594 তারিখে খ্রিস্টান পক্ষে যোগদান একটি দলিলে আনুষ্ঠানিক করলেন, ট্রান্সিলভানিয়ার প্রিন্স জিগমন্ড বাথরিও 28 আগস্ট 1594 তারিখে যুদ্ধের বিরোধী অটোমানপন্থী বেদের পরিষ্কার করে ভেতরের বিরোধিতা ভাঙলেন। ওয়ালাচিয়ার ভয়েভোদা সাহসী মিহাই একই বছরের শরতে মৈত্রীতে যোগ দিলেন। এভাবে দানিউবের উত্তরে অটোমানদের তিন করদ প্রিন্সিপালিটি — দেড়শ বছর কর দেওয়া, ভয়েভোদা ইস্তানবুল কর্তৃক অনুমোদিত তিন ভয়েভোদালিক — একই শরতে একসঙ্গে বিপক্ষে গেল। সিদ্ধান্ত 28 জানুয়ারি 1595 তারিখে প্রাগে স্বাক্ষরিত চুক্তিতে আনুষ্ঠানিক হলো। এটি অটোমানদের বলকানের উত্তরের পরোক্ষ শাসন ব্যবস্থার সবচেয়ে ভারী ঝাঁকুনি ছিল; বিদ্রোহ দমন করা হবে কিন্তু তিন প্রিন্সিপালিটির আনুগত্য আর কখনো 1526-1593 সালের মতো দৃঢ় হবে না।", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["বুখারেস্ট বিদ্রোহ ও দানিউব দুর্গে আক্রমণ", "18971100"], "d": ["পবিত্র মৈত্রীর সিদ্ধান্ত এক মাস পর রক্তের মধ্য দিয়ে কার্যকর হলো: সাহসী মিহাই বুখারেস্টে অটোমান রক্ষী ইউনিট ও শহরের লেভান্তীয় পাওনাদারদের তরবারির আঘাতে হত্যা করলেন। বিদ্রোহ একই শীতে দানিউব রেখায় ছড়ালো; ওয়ালাচীয় বাহিনী ইয়ের্গোগু, ইবরাইল, হিরসোভা ও সিলিস্ত্রায় আক্রমণ করলো, বোগদানের দিকে আরন ভোদা বেন্ডারের অটোমান রক্ষীদের ওপর একই আক্রমণ চালালেন। আঘাত করা স্থানগুলোর বাছাই কাকতালীয় নয়: এগুলো সবই ভয়েভোদালিকের ভূখণ্ড নয়, দানিউব তীরের সরাসরি অটোমান প্রশাসনের অধীন দুর্গ ও কাজা ছিল — ইয়ের্গোগু কাজা নিগবোলু সানজাক বেইত্বের, ইবরাইল 1538 সাল থেকে সরাসরি রাষ্ট্রের, বেন্ডার একইভাবে 1538 সাল থেকে বুজাক সানজাকের অধীন ছিল। অর্থাৎ বিদ্রোহ করদ অভ্যন্তর থেকে নয়, সেই অঞ্চল ঘিরে থাকা সরাসরি অটোমান খোলসের ওপর আঘাত করেছিল। এই খোলস না ফুঁড়ে ট্রান্সিলভানিয়া-ওয়ালাচিয়া-বোগদান ত্রিভুজ হাবসবুর্গ ফ্রন্টের সঙ্গে যুক্ত হতে পারতো না।", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["কালুগারেনির যুদ্ধ — কোজা সিনান পাশার ওয়ালাচিয়া অভিযান", "201210a1"], "d": ["তিন ভয়েভোদালিকের একসঙ্গে হাতছাড়া হওয়ায় প্রধান উজির কোজা সিনান পাশা বিশাল সেনাবাহিনী নিয়ে দানিউব পেরোলেন এবং ওয়ালাচিয়াকে আবার আনুগত্যে আনতে এগোলেন। সাহসী মিহাই খোলা যুদ্ধে প্রতিরোধ করতে পারবেন না জেনে সেনাবাহিনীকে নেয়াজলোভের জলাভূমি পারঘাটে, কালুগারেনিতে অপেক্ষা করলেন এবং সংকীর্ণ ভূমিতে আটকে পড়া বাহিনীর ওপর অতর্কিত হামলা চালালেন। হামলার পর সংখ্যায় বেশি অটোমান সেনাবাহিনীর সামনে টিকতে না পেরে উত্তরে, পর্বতে সরে গেলেন; সিনান পাশা বুখারেস্ট ও তারগোভিশতে দখল করে ওয়ালাচিয়াকে সরাসরি প্রশাসনে বাঁধার চেষ্টা করলেন। কালুগারেনি তাই অটোমানদের জন্য পরাজয় নয়, অভিযান সম্পূর্ণ হওয়া বিলম্বিত করা এক হামলা ছিল; কিন্তু মিহাইয়ের সেনাবাহিনী রক্ষা করতে পারা কয়েক সপ্তাহ পরে ট্রান্সিলভানিয়া থেকে আসা সহায়তায় পাল্টা আক্রমণ সম্ভব করলো।", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["ওয়ালাচিয়া থেকে পশ্চাদপসরণ ও ইয়ের্গোগু হামলা — দমন অভিযানের নিষ্ফল পরিণতি", "118806e1"], "d": ["ট্রান্সিলভানিয়ার প্রিন্সের বাহিনীর সঙ্গে মিলিত সাহসী মিহাইয়ের পাল্টা আক্রমণে সিনান পাশা তারগোভিশতে ও বুখারেস্ট খালি করে দানিউবে সরে গেলেন। পশ্চাদপসরণের সবচেয়ে ব্যয়বহুল মুহূর্ত পারঘাটে ঘটলো: 1595 সালের অক্টোবরে ওয়ালাচিয়া থেকে ফেরা সেনাবাহিনীর অনুসরণকারী আকিনজিরা ইয়ের্গোগুতে মিহাইয়ের হামলার শিকার হলো। অভিযান এভাবে ওয়ালাচিয়াকে সরাসরি প্রশাসনে বাঁধার লক্ষ্যে পৌঁছাতে না পেরে শেষ হলো এবং ভয়েভোদালিক কার্যত হাতছাড়া থেকে গেল। অটোমান কর্তৃত্ব এই ত্রিভুজে কেবল বছরের পর বছর ধরে ও খণ্ড খণ্ডভাবে মেরামত করা গেল; ট্রান্সিলভানিয়ার আনুগত্যে ফেরা 1604 সালের বোচকাই বিদ্রোহের, ফ্রন্ট সম্পূর্ণ বন্ধ হওয়া 1606 সালের জিতভাতোরোক চুক্তির অপেক্ষায় থাকবে।", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["খোতিনের বোগদান থেকে বিচ্ছিন্ন হওয়া — ভয়েভোদালিকের মাঝখানে সরাসরি অটোমান সানজাক", "947517cb"], "d": ["প্রুত অভিযানে বোগদান ভয়েভোদা দিমিত্রি কান্তেমিরের রুশ পক্ষে চলে যাওয়া দেখালো যে ভয়েভোদালিকের উত্তর সীমান্ত আর ভয়েভোদার হাতে ছেড়ে রাখা যায় না। এর ফলে খোতিন 1711 সালের পর বোগদান থেকে নেওয়া হয়ে সরাসরি অটোমান প্রশাসনে আনা হলো; প্রথমে নাহিয়ে, পরে সানজাক মর্যাদা দেওয়া হলো। 1713 সালের অস্থায়ী রুশ দখলের পর দুর্গ ইস্তানবুল থেকে পাঠানো অটোমান ও ফরাসি কারিগরি প্রতিনিধিদলের তত্ত্বাবধানে পুনরায় মেরামত ও সম্প্রসারিত হয়ে দানিউবের উত্তরের সবচেয়ে শক্তিশালী অটোমান দুর্গে পরিণত হলো। মানচিত্রে এই তারিখের পর খোতিনের করদ ভয়েভোদালিক রং থেকে বেরিয়ে সরাসরি অটোমান রঙে ফেরা এবং করদ বোগদানের মাঝখানে কেবল দ্বীপের মতো থাকা এই প্রশাসনিক বিভাজনেরই প্রতিফলন — এটি আঁকার ভুল নয়। একই কাঠামো বুজাকে 1538 সাল থেকে, কিলিয়া ও আক্কেরমানে 1484 সাল থেকে আগেই ছিল: ভয়েভোদালিক অভ্যন্তরীণ বিষয়ে স্বাধীন, সীমান্ত দুর্গগুলো রাষ্ট্রের।", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["বোগুরদেলেনের দ্বিতীয় অস্ট্রীয় দখল — সাভা ফ্রন্ট খোলা", "063b3ad0"], "d": ["অস্ট্রিয়ার 9 ফেব্রুয়ারি 1788 তারিখে রাশিয়ার পক্ষে যুদ্ধে নামার পর সাভা রেখা আবার ফ্রন্ট হলো এবং বোগুরদেলেন 24 এপ্রিল 1788 তারিখে অস্ট্রীয় আধিপত্যে গেল। দুর্গ আগে 17 আগস্ট 1717 তারিখে যুদ্ধ ছাড়াই অস্ট্রিয়াকে ছেড়ে দেওয়া হয়েছিল এবং বেলগ্রেড চুক্তি (1739) পর্যন্ত রাখা হয়েছিল; সে সময় জনসংখ্যা এতটাই কমেছিল যে শহরে চৌত্রিশটি খ্রিস্টান ঘর ছিল, একজনও মুসলিম ছিল না। 1739-1788 সালের অটোমান যুগে জনসংখ্যা আবার 1500-2000-এ উঠেছিল। দ্বিতীয় দখল জিশতোভি চুক্তিতে (4 আগস্ট 1791) শেষ হবে এবং দুর্গ অটোমানদের কাছে ফেরত দেওয়া হবে।", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["বোগুরদেলেনের কারা জর্জির কাছে হস্তান্তর — প্রথম সার্ব বিদ্রোহের প্রথম দুর্গ", "5c913eb4"], "d": ["1804 সালে বেলগ্রেডের দে ও ইয়ামাকদের চাপের প্রতিক্রিয়ায় শুরু হওয়া, পরে জাতীয়তাবাদী চরিত্র নেওয়া প্রথম সার্ব বিপ্লবের সময় বোগুরদেলেন দুর্গ 26 জানুয়ারি 1806 তারিখে কারা জর্জির কাছে হস্তান্তরিত হলো। সাভার ওপরের এই দুর্গ বিদ্রোহীদের দখল করা প্রথম বড় অটোমান দুর্গ এবং বেলগ্রেডের পতনের আগাম সংকেত। বিদ্রোহ 1813 সালে দমিত হয়ে বেলগ্রেড পুনরুদ্ধার হলে দুর্গও অটোমান শাসনে ফিরলো; তবে 1830 ফরমানের গ্যারিসন শর্তে বোগুরদেলেন, বেলগ্রেড, সেমেন্দিরে ও ফেথুলইসলামসহ স্বায়ত্তশাসিত সার্বিয়ার ভেতরে অটোমান সৈন্য থাকা চারটি দুর্গের একটি হিসেবে সংজ্ঞায়িত হলো এবং 1867 সালে গ্যারিসন প্রত্যাহার পর্যন্ত এই মর্যাদায় থাকলো।", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["ইজদিন (লামিয়া) গ্রিসের সীমানার ভেতরে থাকলো — আর্তা-ভোলোস রেখা", "930f63b8"], "d": ["স্বাধীন গ্রিক রাষ্ট্রের উত্তর সীমানা 1832 সালে আর্তা উপসাগর থেকে ভোলোস উপসাগর পর্যন্ত রেখায় টানা হলো। অটোমান যুগে (1424-1832) ইউবোয়া সানজাকের অধীন কাজা কেন্দ্র ইজদিন এই রেখার দক্ষিণে পড়ায় গ্রিসে গেল; থেসালির বাকি অংশ (ইয়েনিশেহির, তিরহালা) 1881 সাল পর্যন্ত অটোমানদের থাকলো।", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["রাশিয়ার যুদ্ধ ঘোষণা — তিরানব্বই যুদ্ধের শুরু", "ac548ab8"], "d": ["1876 সালের বুলগেরীয় বিদ্রোহ দমন ইউরোপীয় জনমতে বিশাল ক্ষোভ জাগিয়েছিল, রাশিয়া বাব-ই আলিকে একঘরে করতে এটিকে চূড়ান্ত পর্যন্ত কাজে লাগিয়েছিল। ইস্তানবুল (তেরসানে) সম্মেলনের বুলগেরিয়াকে দুটি স্বায়ত্তশাসিত প্রদেশে ভাগ করার প্রস্তাব এবং এরপর 31 মার্চ 1877 তারিখের লন্ডন প্রটোকল অটোমান রাষ্ট্র প্রত্যাখ্যান করলে রাশিয়া 24 এপ্রিল 1877 তারিখে যুদ্ধ ঘোষণা করলো এবং তার সেনাবাহিনী নিজের পক্ষে টেনে আনা রোমানিয়া প্রিন্সিপালিটির ভূখণ্ডে প্রবেশ করলো (মানচিত্র ওয়ালাচিয়া-বোগদানকে এই মুহূর্ত থেকে এদির্ন যুদ্ধবিরতি পর্যন্ত রুশ অগ্রগতির ডোরাকাটা আচ্ছাদনে দেখায়)। রুমি পঞ্জিকায় 1293 সালে পড়ায় যুদ্ধ তিরানব্বই যুদ্ধ নামে পরিচিত। অভিযান দানিউব ও পূর্ব আনাতোলিয়া দুই ফ্রন্টে চললো: দানিউবে 180.000 লোকের অটোমান সেনাবাহিনী নদীর বাম তীরকে প্রথম, বলকান পর্বতকে দ্বিতীয় প্রতিরক্ষা রেখা গণ্য করেছিল; পূর্বে আহমেদ মুখতার পাশার 55.000 সৈন্য আর্দাহান-দোগুবায়াজিতের মধ্যে অবস্থান নিয়েছিল। এই যুদ্ধ মানচিত্রে অটোমান রুমেলির পতনের সূচনাকারী ঘটনা — বুলগেরিয়া, সার্বিয়া, মন্টিনিগ্রো ও রোমানিয়ার বর্তমান সীমানার সবই এই পনেরো মাসের ফল।", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["রোমানিয়ার স্বাধীনতা ঘোষণা — ওয়ালাচিয়া-বোগদান করদত্বের অবসান", "bdd164b3"], "d": ["93 যুদ্ধ ঘোষণার দুই সপ্তাহ পর রোমানিয়া প্রিন্সিপালিটি স্বাধীনতা ঘোষণা করলো এবং রাশিয়ার পক্ষে যুদ্ধে নামলো; প্লেভেন অবরোধে তার ভূমিকা অটোমান পরাজয়ে নির্ণায়ক হলো। চারশ বছরের বেশি ওয়ালাচিয়া ও বোগদান করদত্ব এভাবে কার্যত শেষ হলো; স্বাধীনতা বার্লিন কংগ্রেসে (1878) আন্তর্জাতিক স্বীকৃতি পেল। মানচিত্র এই তারিখ থেকে রোমানিয়াকে করদ নয়, নিজস্ব রঙে স্বাধীন রাষ্ট্র হিসেবে দেখায়। স্বাধীনতা ঘোষণার ফলে ওয়ালাচিয়া ও বোগদানের সমগ্র অংশ (ইয়াশ, গালাতি, ইবরাইল, ইয়ের্গোগু, কালাফাত, বোতোশানি প্রভৃতি) স্বাধীন রোমানিয়া হলো।", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["রুশ সেনাবাহিনীর দানিউব পারাপার — জিশতোভি ও তারনোভোর পতন", "811367b1"], "d": ["যুদ্ধ শুরুর সঙ্গে রোমানিয়ার ভূখণ্ডে ঢুকে এই প্রিন্সিপালিটিকে নিজ পক্ষে টানা রুশরা, একটি দোবরুজা অন্যটি বুখারেস্টের দিকে, দুই বাহু ধরে অগ্রসর হলো। দানিউব রুসচুক ও নিগবোলুর মধ্য দিয়ে পার করা হলো এবং 27 জুন জিশতোভি, 1 জুলাই প্রাচীন বুলগেরীয় রাজধানী তারনোভো দখল হলো। খালি করার আদেশ থাকলেও এ বিষয়ে যত্ন না নেওয়ায় নিগবোলুও কিছুক্ষণ প্রতিরোধের পর আত্মসমর্পণ করলো। প্রথম প্রতিরক্ষা রেখা এক সপ্তাহের মধ্যে ভেঙে যাওয়া ইস্তানবুলে বড় আতঙ্ক সৃষ্টি করলো; সালতানাতের কেন্দ্র বুরসায় সরানো হবে এমন খবরও ছড়ালো এবং যুদ্ধ পরিচালনা রাজধানীতে গঠিত এক সামরিক পরিষদের হাতে গেল।", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["শিপকা গিরিপথ খালি — বলকান রেখা ভেঙে যাওয়া", "1f45e50a"], "d": ["বলকান পর্বত পেরোনো গিরিপথগুলোর মধ্যে সবচেয়ে কৌশলগত শিপকার অটোমান বাহিনী রুশ আক্রমণ তীব্রভাবে প্রতিহত করলো; তবে পরাজিত হবে বলে বিশ্বাস করে 19 জুলাই গোপনে গিরিপথ খালি করলো। এভাবে দ্বিতীয় প্রতিরক্ষা রেখাও খুলে গেল এবং জেনারেল গুর্কো 22 জুলাই এস্কি জাগরা দখল করলেন। মন্টিনিগ্রো দিক থেকে এসে পৌঁছানো সুলাইমান পাশা গুর্কোকে পরাজিত করে বলকানের দক্ষিণের দখলকৃত স্থানগুলো ফিরিয়ে নিলেও 21 আগস্ট থেকে মাসের পর মাস চলা আক্রমণ সত্ত্বেও শিপকা ফিরিয়ে নিতে পারলেন না। মানচিত্রে এটি বলকান পর্বতমালার উত্তর ও দক্ষিণের মধ্যকার প্রতিরক্ষা সংহতি আর কখনো গড়া না যাওয়া: দানিউব ফ্রন্টের লড়াই এরপর প্লেভেনে গিঁট পাকাবে।", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["লোভচা রুশ সেনাবাহিনীর দখলে", "70e54611"], "d": ["93 যুদ্ধে লোভচা 5 জুন 1877 তারিখে রুশদের দখলে এসেছিল, রিফাত পাশার নেতৃত্বাধীন অটোমান বাহিনী 15 জুন রুশদের হটিয়ে দিয়েছিল; শহর 23 আগস্ট অটোমানদের ত্যাগে আবার রুশ দখলে গেল। মানচিত্র লোভচাকে এই দিন থেকে বার্লিন চুক্তি পর্যন্ত রুশ দখলের অধীনে (ডোরাকাটা) দেখায়; আইনত অটোমান ভূখণ্ড থেকে যায়।", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["কার্সের পতন — পূর্ব ফ্রন্ট ভেঙে পড়া ও আজিজিয়ে দুর্গ", "53fc3bf5"], "d": ["পূর্ব আনাতোলিয়ায় কার্স, দোগুবায়াজিত ও আর্দাহানের দিকে তিন বাহুতে অগ্রসর রুশরা 30 এপ্রিল দোগুবায়াজিত নিয়েছিল, আর্দাহানে ঢুকেছিল, কিন্তু এরজুরুমের দিকে অগ্রসর হওয়ার সময় 15 জুলাই পরাজিত হয়ে সীমান্তের বাইরে ছুড়ে ফেলা হয়েছিল। আহমেদ মুখতার পাশাকে 'গাজি' উপাধি এনে দেওয়া এই সাফল্য আগস্টে জেনারেল লাজারোভের পুনরায় আক্রমণে উল্টে গেল এবং 18 নভেম্বর কার্স পতিত হলো। আরও উপযুক্ত প্রতিরক্ষার জন্য এরজুরুমে সরে যাওয়া অটোমান বাহিনী আজিজিয়ে দুর্গে নেনে হাতুনের জনগণকে উৎসাহ দেওয়ায় বড় প্রতিরোধ দেখালো। কার্স, আর্দাহান ও বাতুম আট মাস পর বার্লিনে যুদ্ধক্ষতিপূরণের একাংশের বিনিময়ে রাশিয়াকে ছেড়ে দেওয়া হবে।", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["প্রথম বলকান যুদ্ধের শুরু — মন্টিনিগ্রোর যুদ্ধ ঘোষণা", "c0c2697e"], "d": ["বলকান রাষ্ট্রগুলো ইত্তিহাদ ও তেরাক্কির 3 জুলাই 1911 তারিখের আইনে গির্জা সমস্যা সমাধানের পর নিজেদের মধ্যকার সবচেয়ে বড় বাধা সরিয়েছিল, রাশিয়ার উসকানিতে 1912 জুড়ে পরস্পরের সঙ্গে মৈত্রী চুক্তি স্বাক্ষর করেছিল (13 মার্চ সার্বিয়া-বুলগেরিয়া, 29 মে বুলগেরিয়া-গ্রিস, আগস্টে মন্টিনিগ্রো-বুলগেরিয়া, 6 অক্টোবর মন্টিনিগ্রো-সার্বিয়া)। বাব-ই আলি এটি টের পেল না; এমনকি রাশিয়ার নিশ্চয়তায় ভরসা করে রুমেলির 120 প্রশিক্ষিত ব্যাটালিয়ন ছুটি দিল। চার রাষ্ট্র 3 অক্টোবর যৌথ নোট দিয়ে মেসিডোনিয়া, আলবেনিয়া ও ক্রিটের জন্য স্বায়ত্তশাসন চাইলো; উত্তর না পেয়ে 8 অক্টোবর 1912 তারিখে মন্টিনিগ্রোর যুদ্ধ ঘোষণায় অভিযান শুরু হলো। 13 অক্টোবর সার্বিয়া ও বুলগেরিয়ার দূতদের পাসপোর্ট হাতে ধরিয়ে দেওয়া হলো, পরদিন এই দুই রাষ্ট্র, এরপর গ্রিস যুদ্ধ ঘোষণা করলো। যুদ্ধের সময় সেনাবাহিনীর ভেতরের রাজনৈতিক মতভেদ পরাজয়ে বড় ভূমিকা রাখলো।", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["রোডোপে কিরজালি দল ভেঙে পড়লো, কিরজালি পতিত", "8cf59b7f"], "d": ["বুলগেরীয় যুদ্ধ ঘোষণার পর রোডোপ থেকে নামা বুলগেরীয় বাহিনী মেহমেদ ইয়াভের পাশার কিরজালি দলকে পরাজিত করে কিরজালিতে প্রবেশ করলো। বিপর্যস্ত দল গুমুলজিনার দিকে সরে গেল; রোডোপের পূর্ব অংশ যুদ্ধের প্রথম সপ্তাহে হাতছাড়া হলো।", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["প্রাচ্য সেনাবাহিনীর বিপর্যয় ও চাতালকা রেখায় পশ্চাদপসরণ — কুমানোভো ও সালোনিকা হারানো", "cf95591a"], "d": ["অটোমান প্রাচ্য সেনাবাহিনী 23 অক্টোবর 1912 তারিখে নিজেদের তিনগুণ বড় বুলগেরীয় বাহিনীর কাছে পরাজিত হয়ে ইস্তানবুলের ত্রিশ কিলোমিটার পশ্চিমের চাতালকা রেখা পর্যন্ত সরে গেল; রাজধানী যুদ্ধের প্রথম মাসেই সরাসরি হুমকির মুখে পড়লো। একই দিনগুলোতে পশ্চিম সেনাবাহিনী 23-24 অক্টোবর কুমানোভোয় সার্বদের কাছে পরাজিত হলো এবং তাহসিন পাশা 35.000 লোকের সেনাবাহিনী নিয়ে সালোনিকায় গ্রিকদের কাছে আত্মসমর্পণ করলেন। এই বিপর্যয়ে 29 অক্টোবর গাজি আহমেদ মুখতার পাশার মন্ত্রিসভা পদত্যাগ করলো; সালোনিকায় নির্বাসন জীবন কাটানো দ্বিতীয় আবদুলহামিদ 1 নভেম্বর ইস্তানবুলে স্থানান্তরিত হলেন। চাতালকা রেখা যুদ্ধের শেষ পর্যন্ত ধরে রাখা হলো — রুমেলির পাঁচশ বছরের অটোমান ভূগোল কয়েক সপ্তাহের মধ্যে এই সংকীর্ণ ফালিতে নেমে এলো।", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["ইয়েনিপাজার সানজাকের কেন্দ্রে প্রিন্স আলেকসান্দার প্রবেশ করলেন", "326d0616"], "d": ["সার্ব বাহিনী যুদ্ধের প্রথম সপ্তাহে ইয়েনিপাজার নিল এবং পশ্চিম থেকে আসা মন্টিনিগ্রো বাহিনীর সঙ্গে মিলিত হলো। সার্বিয়া ও মন্টিনিগ্রোকে একশ বছর আলাদা রাখা ইয়েনিপাজার সানজাক এভাবে দুই মিত্রের মধ্যে সেতুতে পরিণত হলো।", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["কিরকলিসে যুদ্ধের পর কিরকলারেলি হাতছাড়া", "eda4c759"], "d": ["পূর্ব থ্রেসে প্রাচ্য সেনাবাহিনী কিরকলিসে যুদ্ধে পরাজিত হওয়ায় কোলেমেন আবদুল্লাহ পাশার রক্ষা করা শহর বুলগেরীয় বাহিনীর হাতে ছেড়ে দেওয়া হলো। শহর নয় মাস স্থায়ী দখল থেকে কেবল দ্বিতীয় বলকান যুদ্ধে, 21 জুলাই 1913 তারিখে মুক্ত হলো।", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["কসোভো প্রদেশের কেন্দ্র উস্কুপ প্রতিরোধ ছাড়াই ছেড়ে দেওয়া", "455d9b71"], "d": ["কুমানোভো বিপর্যয়ের (23-24 অক্টোবর) পর কসোভো প্রদেশের কেন্দ্র উস্কুপ অরক্ষিত থাকলো। জনগণ শহরের আশেপাশে লড়াই চাইছিল না বলে কনসালদের মাধ্যমে আমন্ত্রিত প্রিন্স আলেকসান্দারের নেতৃত্বাধীন সার্ব বাহিনী 26 অক্টোবর সন্ধ্যায় শহরে প্রতিরোধ ছাড়াই প্রবেশ করলো।", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["ভারদার তীরে কোপরুলু (ভেলেস) হারানো", "73d20b7d"], "d": ["উস্কুপের পতনের দুই দিন পর ভারদার বরাবর দক্ষিণে নামা সার্ব সেনাবাহিনী কোপরুলু নিল। সালোনিকায় খোলা ভারদার উপত্যকার দরজা এভাবে সার্বদের হাতে গেল।", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["ব্রেগালনিৎসা অববাহিকা: জেনারেল স্তেফানোভিচ ইশতিপে প্রবেশ করলেন", "70a84256"], "d": ["জেনারেল স্তেফানোভিচের নেতৃত্বাধীন সার্ব ইউনিট ইশতিপ প্রতিরোধের মুখোমুখি না হয়ে নিল; শহরে প্রথমে অনিয়মিত দল প্রবেশ করলো। কুমানোভোর পর পূর্ব মেসিডোনিয়ার ব্রেগালনিৎসা অববাহিকা সার্ব নিয়ন্ত্রণে গেল।", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["সারান্তাপোরো গিরিপথের পর কারাফেরিয়া গ্রিক আধিপত্যে গেল", "02a68e02"], "d": ["থেসালি থেকে উত্তরে অগ্রসর গ্রিক সেনাবাহিনী সারান্তাপোরো (কিরকগেচিত) গিরিপথ পেরোনোর পর কারাফেরিয়ায় আধিপত্য নিল। শহরের মুসলিম জনসংখ্যার একাংশ এই সময়ে অঞ্চল ত্যাগ করলো।", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["সালোনিকা-মনাস্তির রেলপথের ভোদিনা হারানো", "fc15b917"], "d": ["সালোনিকা-মনাস্তির রেলপথের ভোদিনা গ্রিক সেনাবাহিনীর হাতে গেল। স্লাভ ও তুর্কি জনগোষ্ঠীর জোর করে বিচ্ছিন্ন হওয়ায় শহরের জনসংখ্যা অল্প সময়ে গুরুতরভাবে কমলো।", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["ইয়েনিজে যুদ্ধ — ইয়েনিজে-ই ভারদার গ্রিকদের হাতে গেল", "8f6cb76e"], "d": ["হাসান তাহসিন পাশার 8ম মিশ্র কোর সালোনিকার পশ্চিমের ইয়েনিজেতে গ্রিক সেনাবাহিনীর কাছে পরাজিত হয়ে সালোনিকা অঞ্চলে সরে গেল। যুদ্ধের সময় শহরের বড় অংশ পুড়লো; সালোনিকার পথ গ্রিক সেনাবাহিনীর জন্য খুলে গেল।", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["কসোভোর দক্ষিণ-পশ্চিমে প্রিজরেন আত্মসমর্পণ করলো", "bae6b1b9"], "d": ["কসোভোর দক্ষিণ-পশ্চিমের প্রিজরেন সার্ব বাহিনীর কাছে আত্মসমর্পণ করলো। শহরে ঢোকা ইউনিটগুলোর মুসলিম জনগণের প্রতি আচরণ কসোভোতে যুদ্ধের সবচেয়ে ভারী অধ্যায়গুলোর একটি হিসেবে নথিভুক্ত হলো।", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["কর্নেল মিতভ উস্ত্রুমজায় সামরিক আইন ঘোষণা করলেন", "bcad75cc"], "d": ["বুলগেরীয় কর্নেল মিতভ উস্ত্রুমজায় প্রবেশ করে সামরিক আইন ঘোষণা করলেন; পরদিন চলে যাওয়ার সময় শহর একজন বুলগেরীয় কাইমাকাম ও একজন সার্ব অধিনায়কের হাতে ছেড়ে দিলেন। উস্ত্রুমজা যুদ্ধের সময় মিত্রদের মধ্যে হাতবদল হলো এবং 1913 সালে বুলগেরিয়ার সঙ্গে যুক্ত হলো।", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["হাসান তাহসিন পাশা সালোনিকা গ্রিকদের ছেড়ে দিলেন", "1738933c"], "d": ["ইয়েনিজে পরাজয়ের পর সালোনিকায় সরে আসা হাসান তাহসিন পাশা বুলগেরীয় সেনাবাহিনী উত্তর থেকে এগিয়ে আসার সময় শহর গ্রিকদের ছেড়ে দিলেন; গ্রিক সেনাবাহিনী 8 নভেম্বর দুপুরের দিকে শহরে প্রবেশ করলো। অটোমান রুমেলির সবচেয়ে বড় বন্দর শহর এবং ইত্তিহাদ ও তেরাক্কির জন্মস্থান সালোনিকা এভাবে হাতছাড়া হলো।", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["পশ্চিম থ্রেসের কেন্দ্র গুমুলজিনা বুলগেরীয়দের জন্য খুলে গেল", "96eec25f"], "d": ["কিরজালি থেকে সরে আসা ইয়াভের পাশার দলের ফেরেসের দিকে পিছু হটার ফলে গুমুলজিনা বুলগেরীয় বাহিনীর কাছে আত্মসমর্পণ করলো। পশ্চিম থ্রেসের কেন্দ্র যুদ্ধের শেষে বুলগেরিয়াকে ছেড়ে দেওয়া হবে এমন ভূখণ্ডের শীর্ষে ছিল।", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["এলবাসানে পৌঁছানো সার্বরা একই দিনে দেবরে প্রবেশ করলো", "16720246"], "d": ["মনাস্তির থেকে পশ্চিমে অগ্রসর সার্ব বাহিনী এলবাসানে পৌঁছানোর দিন দেবরেও প্রবেশ করলো এবং আদ্রিয়াটিকের দিকে নামলো। একই দিনে আভলোনায় আলবেনিয়ার স্বাধীনতা ঘোষিত হচ্ছিল।", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["তৈমুর বাগদাদ দ্বিতীয়বার দখল করলেন — শহরের আব্বাসি মহল্লা ধ্বংস", "04b68a24"], "d": ["তৈমুর বাগদাদ আট বছরের ব্যবধানে দুবার নিলেন। 1393 সালের প্রথম দখলে শহরের বেশি ক্ষতি হয়নি; 1401 সালের দ্বিতীয়টি অবশ্য বাগদাদের সাংস্কৃতিক জীবনে দ্বিতীয় ভারী আঘাত গণ্য — জনগণকে তরবারির আঘাতে হত্যা করা হলো, আব্বাসি যুগের মহল্লা ও ভবনের অধিকাংশ ধ্বংস হলো। জালায়িরি শাসক আহমেদ 1405 সালে শহরে ফিরে ধ্বংস হওয়া প্রাচীর ও বাজার মেরামতের চেষ্টা করলেও সময় পেলেন না; বাগদাদ 1410 সালে কারাকোয়ুনলু তুর্কমেনদের হাতে গেল। এই দুই দখল আঙ্কারা যুদ্ধের পথে তৈমুর অটোমান ও মামলুক সীমান্তের কতটা কাছে এসেছিলেন তা দেখানো সবচেয়ে বাস্তব পদক্ষেপগুলোর একটি।", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["জুনেইদ বে আয়দিন-ইলির প্রধান হয়ে ফিরলেন — আয়দিনোগুল্লারি আবার স্বাধীন", "63281658"], "d": ["চেলেবি মেহমেদ 1414-15 সালে ইজমির নিয়ে জুনেইদ বেকে নিগবোলু সানজাক বেইত্বে পাঠিয়ে আয়দিন-ইলিকে অটোমান প্রশাসনে বেঁধেছিলেন। জুনেইদ চেলেবি মেহমেদের মৃত্যুর পর বাইজান্টিয়ামের সিংহাসন-দাবিদার হিসেবে সামনে আনা মুস্তাফা চেলেবির পাশে আবার মঞ্চে এলেন এবং তাঁর উজিরও হলেন। দ্বিতীয় মুরাদ পুরনো বেগলিক ফিরিয়ে দেওয়ার প্রতিশ্রুতিতে তাঁকে এই মিত্রতা থেকে আলাদা করলেন; জুনেইদও ইজমিরে ফিরে আয়াসুলুক দখল করলেন এবং আয়দিনোগলু মুস্তাফা বেকে হত্যা করে বেগলিকের প্রধান হলেন। এভাবে আয়দিন-ইলি ভুয়া মুস্তাফা সংকটের ভেতর থেকে অটোমান শাসন থেকে বেরিয়ে জন্ম নিল।", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["জুনেইদ বে ও পরিবারের মৃত্যুদণ্ড — আয়দিনোগুল্লারি বেগলিকের অবসান", "efa684ba"], "d": ["আয়দিন-ইলিতে আবার কর্তৃত্ব নেওয়া জুনেইদ বের আনাতোলীয় বেদের উসকানি ও ভেনিসের সঙ্গে যোগাযোগ খোঁজার কারণে দ্বিতীয় মুরাদ আনাতোলিয়া বেইলারবেই হামজা বেকে তাঁর বিরুদ্ধে পাঠালেন। পুত্র কুর্দ হাসান আকহিসারের কাছে পরাজিত হয়ে বন্দি হলে সামোস দ্বীপের বিপরীতে ইপসিলিতে সরে যাওয়া জুনেইদ কারামানোগলুর কাছ থেকে আশা করা সাহায্য না এলে এবং অটোমানদের সঙ্গে একত্রে চলা জেনোয়াবাসীরা সমুদ্র থেকে অবরোধ করলে আত্মসমর্পণে বাধ্য হলেন; পুরো বংশসহ নিশ্চিহ্ন করা হলো। আয়দিনোগুল্লারি ভূখণ্ড এভাবে সম্পূর্ণ অটোমান শাসনে এলো।", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["এরজুরুম ও ভান অববাহিকা সাফাভিদের হাতে গেল — আককোয়ুনলুর উত্তর বাহু ধসে পড়লো", "b418875f"], "d": ["শারুরে আলভেন্দ বেকে পরাজিত করে 1501 সালের গ্রীষ্মে তাবরিজে প্রবেশ করা শাহ ইসমাইল পরের বছর উত্তর-পশ্চিম দিকে অগ্রসর হয়ে এরজুরুম থেকে ভান হ্রদ অববাহিকা পর্যন্ত রেখা নিজের আধিপত্যে নিলেন। আককোয়ুনলু রাষ্ট্র উজুন হাসানের মৃত্যুর পর সিংহাসন কলহে ইতিমধ্যেই দুই ভাগে ভাঙা ছিল: আলভেন্দ বে আজারবাইজান ও দিয়ারবাকির, চাচাতো ভাই মুরাদ ইরাক-ই আজম ও ফারস ধরে রেখেছিলেন। এই বিভাজন সাফাভি অগ্রগতি সহজ করলো; অঞ্চল এক বছরের মধ্যে হাতবদল হলো। এরজুরুম এরপর ষোলো বছর সাফাভি হাতে থাকলো এবং অটোমান আধিপত্যে এলো কেবল চালদিরানের পর, 1518-19 সালে। এই বছরে (1502) আশকালে ও পাসিনলার (হাসানকালে) এরজুরুম অঞ্চলসহ আককোয়ুনলু থেকে সাফাভিদের হাতে গেল (দিন অনিশ্চিত)।", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["মুরাদ বের হামাদান পরাজয়: ইরাক-ই আজম ও ফারস সাফাভিদের হাতে গেল", "8de07a31"], "d": ["আককোয়ুনলু সিংহাসনের দ্বিতীয় দাবিদার সুলতান মুরাদ শাহ ইসমাইলের বিরুদ্ধে হামাদানের কাছে হওয়া যুদ্ধে ভারী পরাজয় বরণ করে বাগদাদে পালালেন। এই একটি যুদ্ধেই ইরাক-ই আজম, ফারস ও কিরমান অঞ্চল সাফাভি শাসনে এলো; মানচিত্রে এই অঞ্চলগুলো একই সময়ে হাতবদল হয়। আককোয়ুনলু রাষ্ট্রের বিলুপ্তির সবচেয়ে বড় একক পদক্ষেপ এটি — তাবরিজ হারানো রাজবংশকে রাজধানীহীন করেছিল, হামাদান পরাজয় ভূখণ্ডহীন করলো।", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["শাহ ইসমাইল ইয়াজদে প্রবেশ করলেন: আককোয়ুনলু অবশিষ্টাংশের মধ্য ইরানের শেষ দুর্গ পতিত", "6f9835df"], "d": ["1503 হামাদান পরাজয়ের পর ইরাক-ই আজম ও ফারস সাফাভিদের হাতে গেলেও ইয়াজদ আককোয়ুনলু রাজবংশের বায়িন্দিরলি মুরাদ বের হাতে আলাদা থেকে গিয়েছিল। শহর এক মাসের অবরোধে পতিত হলো এবং মধ্য ইরানের শেষ আককোয়ুনলু দ্বীপ বন্ধ হলো। TDV-এর নথি: \"Şah İsmâil 28 Cemâziyelâhir 910 (6 Aralık 1504) tarihinde bir aylık bir kuşatmanın ardından şehre girdi.\"", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["শাহ ইসমাইলের দিয়ারবাকির অভিযান: আককোয়ুনলুর শেষ কেন্দ্রগুলো পতিত", "b6d8504e"], "d": ["আজারবাইজান ও ইরান মালভূমি দখল করা শাহ ইসমাইল 1507 সালে পশ্চিমে, আককোয়ুনলু রাজবংশের জন্মস্থান দিয়ারবাকির অঞ্চলের দিকে এগোলেন। আমিদ থেকে মারদিন, উরফা থেকে হারপুত পর্যন্ত বিস্তৃত রেখা দুই ধাপে সাফাভি শাসনে এলো এবং আককোয়ুনলুরা কার্যত বিলুপ্ত হলো। এই অভিযান একই সঙ্গে সাফাভি সীমান্তকে প্রথমবার অটোমান ও মামলুক সীমান্তের গায়ে লাগালো; চালদিরানে যাওয়া উত্তেজনার ভৌগোলিক ভিত্তি এভাবে গড়া হলো।", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["বাগদাদের সাফাভিদের হাতে যাওয়া — ইরাক-ই আরাব হাতবদল", "39730186"], "d": ["হামাদান পরাজয়ের পর বাগদাদে আশ্রয় নেওয়া আককোয়ুনলু সুলতান মুরাদের পেছনে শাহ ইসমাইল 1508 সালে ইরাক-ই আরাবে প্রবেশ করলেন এবং বাগদাদ নিলেন। কারবালা ও নাজাফের সমাধিস্থল সাফাভি শাসনে যাওয়া আন্দোলনের মাজহাবি দাবির দিক থেকে তাবরিজ দখলের মতো গুরুত্বপূর্ণ ছিল। মানচিত্রে ইরাক-ই আরাব একই দিনে হাতবদল হয়; এটি বিলুপ্তির শেষ ও সবচেয়ে বিস্তৃত ভৌগোলিক পদক্ষেপ। বাগদাদ 1534 সালে কানুনির ইরাকেইন অভিযান পর্যন্ত সাফাভি হাতে থাকলো।", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["মারভ যুদ্ধ: উজবেকরা ভারী পরাজয় বরণ করলো, মারভ ও হেরাত দখল", "f8e45aaf"], "d": ["পশ্চিমে আককোয়ুনলু উত্তরাধিকার সম্পূর্ণ করা শাহ ইসমাইল পূর্বে খোরাসানে অভিযান চালালেন এবং মারভের সামনে উজবেকদের ভারী পরাজয়ে ফেললেন; শেইবানি খান যুদ্ধক্ষেত্রে নিহত হলেন। মারভ ও হেরাত সাফাভি আধিপত্যে এলো এবং সাফাভি রাষ্ট্র ফোরাত থেকে আমু দরিয়া পর্যন্ত বিস্তৃত সীমানা পেল। এভাবে 1501 সালের গ্রীষ্মে তাবরিজ প্রবেশে শুরু হওয়া প্রক্রিয়া নয় বছরে সম্পূর্ণ হলো: আককোয়ুনলু উত্তরাধিকার পুরোপুরি সাফাভি শাসনে গেল এবং অটোমান রাষ্ট্র পূর্বে নিজের সমান বড় দ্বিতীয় রাষ্ট্রের প্রতিবেশী হলো।", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["জাবিদের অটোমান আধিপত্যে চূড়ান্ত অন্তর্ভুক্তি", "ddd971c7"], "d": ["দিউ অবরোধ 5 নভেম্বর 1538 তারিখে তুলে নেওয়া নৌবহর ফেরার পথে ইয়েমেন উপকূলে থামলো এবং জাবিদ চূড়ান্তভাবে অটোমান শাসনে যুক্ত হলো; হাদিম সুলাইমান পাশা 10 মার্চ 1539 তারিখে শহর ছেড়ে 1 এপ্রিল জেদ্দায় পৌঁছালেন। শহর 1517 সাল থেকে সাবেক মামলুক বেদের হাতে অটোমানদের নামে শাসিত হচ্ছিল; এই তারিখে সরাসরি প্রশাসনে গেল।", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["ইবেরীয় ইউনিয়ন: পর্তুগিজ মুকুট স্পেনের রাজার হাতে গেল", "1cc6dfdc"], "d": ["কার্ডিনাল রাজা এনরিকের উত্তরাধিকারহীন মৃত্যুতে খোলা উত্তরাধিকার কলহ আলকান্তারা যুদ্ধে (25 আগস্ট 1580) স্পেনের পক্ষে শেষ হলো এবং তোমারে মিলিত পর্তুগিজ কোর্তেস 16 এপ্রিল 1581 তারিখে দ্বিতীয় ফিলিপকে পর্তুগালের রাজা হিসেবে স্বীকৃতি দিল। তোমার শর্ত অনুযায়ী পর্তুগাল নিজের প্রতিষ্ঠান, মুদ্রা ও ভাষা রক্ষা করবে, প্রশাসনে কেবল পর্তুগিজরা নিযুক্ত হবে, মাদ্রিদে আলাদা পর্তুগিজ পরিষদ থাকবে — অর্থাৎ একীভবন ছিল ব্যক্তিগত ইউনিয়ন, অন্তর্ভুক্তি নয়।", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["রেস্তাউরাসাও: পর্তুগাল স্বাধীনতা ফিরে পেল", "64ec0738"], "d": ["কাতালোনিয়া বিদ্রোহ স্পেনকে ব্যস্ত রাখা দিনগুলোতে লিসবনে একদল অভিজাত প্রাসাদে অতর্কিত হামলা চালিয়ে স্পেনীয় শাসন উৎখাত করলেন এবং ব্রাগাঁসার ডিউককে চতুর্থ জোয়াও নামে রাজা ঘোষণা করলেন। ষাট বছরের ইবেরীয় ইউনিয়ন এভাবে শেষ হলো; তবে সেউতা স্পেনে থাকা বেছে নিল এবং এটি 1668 সালের লিসবন চুক্তিতে স্বীকৃত হলো। পর্তুগাল হাবসবুর্গ যুদ্ধের সঙ্গে জুড়ে যাওয়া এই জানালা এশিয়ায় তার ক্ষতির কাঠামোও: হরমুজ 1622 সালে, মালাক্কা 1641 সালে, কলম্বো 1656 সালে হাতছাড়া হলো; তাঙ্গিয়ের ও বোম্বে স্বাধীনতার মূল্য হিসেবে ইংল্যান্ডকে দেওয়া হলো। সূত্র: Britannica, History of Portugal — Restoration।", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["তাঞ্জিয়ার ইংল্যান্ডের হাতে হস্তান্তর", "1f7cad6d"], "d": ["পর্তুগালের স্বাধীনতা যুদ্ধে ইংরেজ সমর্থন নিশ্চিত করতে সম্পাদিত বিবাহ চুক্তির (23 জুন 1661) দ্বিতীয় ধারায় তাঞ্জিয়ার ক্যাথরিন অব ব্রাগানজার যৌতুক হিসেবে ইংল্যান্ডকে ছেড়ে দেওয়া হয়। স্যান্ডউইচের আর্লের নৌবহর 29 জানুয়ারি 1662 তারিখে নোঙর ফেলে এবং পরদিন পিটারবরোর আর্লের উপস্থিতিতে আনুষ্ঠানিক হস্তান্তর সম্পন্ন হয়। ইংরেজরা 1684 সালে শহরটি ত্যাগ করবে।", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["নাদির শাহের হত্যা — আফশার আধিপত্যের পতন", "19c218c0"], "d": ["সাফাভি সিংহাসনের অবসান ঘটিয়ে 1736 সালে নিজের নামে সুলতানি ঘোষণা করা, ভারত অভিযানে দিল্লি পর্যন্ত পৌঁছানো এবং অটোমানদের সঙ্গে তিনটি যুদ্ধ করে 1746 সালের কেরদান চুক্তিতে শান্তি স্থাপনকারী নাদির শাহ নিজের দেহরক্ষীদের হাতে তাঁবুতে নিহত হন। এরপর ইরান আর একক হাতে শাসিত হয়নি: খোরাসানে আফশার অবশিষ্টাংশ, দক্ষিণে জান্দ এবং উত্তরে উঠতি কাজার উনপঞ্চাশ বছর ধরে দেশটি ভাগ করে নেয়। এই বিশৃঙ্খলার কারণে অটোমান পূর্ব সীমান্ত দীর্ঘ সময় শান্ত ছিল। নাদির শাহ 20 জুন 1747 তারিখে নিহত হন; টিডিভির মতে ইরেভান খানাত একই বছর (1747) প্রতিষ্ঠিত হয়, দিন অনিশ্চিত।", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["কাজার রাজবংশের ইরানে আধিপত্য প্রতিষ্ঠা", "744b48c5"], "d": ["কাজার গোত্রপ্রধান আগা মুহাম্মদ খান জান্দ শাসন উৎখাত করে এবং খোরাসানে আফশারদের শেষ প্রতিরোধ ভেঙে ইরানকে আবার এক হাতে একত্র করেন ও তেহরানকে রাজধানী করেন। এভাবে উনপঞ্চাশ বছরের বিভক্তির যুগ শেষ হয়; এরপর 1923 সাল পর্যন্ত অটোমানদের পূর্বের প্রতিবেশী ছিল কাজার ইরান। টিডিভি ইসলাম বিশ্বকোষ অনুসারে মাশহাদ 1796 সালে আগা মুহাম্মদ শাহের সামনে আফশার শাসক শাহরুখ কর্তৃক অভ্যর্থিত হয় এবং কাজার আধিপত্যের অধীনে আসে (সূত্রে দিন নেই)।", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["ফের্দিনান্দ বুদিন দখল করলেন — জাপোলিয়াই রাজধানী থেকে বিতাড়িত", "99f77c29"], "d": ["মোহাচের পর হাঙ্গেরীয় সিংহাসনে দুজন রাজা দাঁড়ায়: অভিজাতদের একাংশ ইয়ানোশ জাপোলিয়াইকে, অন্যরা হাবসবুর্গ ফের্দিনান্দকে নির্বাচিত করেছিল। ফের্দিনান্দ 1527 সালে বুদিন দখল করে জাপোলিয়াইকে রাজধানী থেকে বিতাড়িত করেন; জাপোলিয়াই সুলতান সুলায়মানের সাহায্য চান। এ কারণেই 1529 সালের ভিয়েনা অভিযানের প্রথম লক্ষ্য ছিল বুদিন।", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["বারবারোসার এজিয়ান দ্বীপ অভিযান — নাক্সোস ডাচি অটোমান নিয়ন্ত্রণে", "722b2fea"], "d": ["1207 সাল থেকে ভেনিসের আশ্রয়ে লাতিন ডিউকদের দ্বারা শাসিত নাক্সোস ডাচি বারবারোসা হায়রেদ্দিন পাশার দ্বীপ অভিযানের মাধ্যমে অটোমান নিয়ন্ত্রণে আসে। দ্বীপের মর্যাদায় হাত দেওয়া হয়নি; ডাচি অটোমানদের অধীন হিসেবে টিকে থাকে এবং 1540 সালের অটোমান-ভেনিস চুক্তিতে কর্তৃত্বের অধিকার আনুষ্ঠানিকভাবে অটোমানদের হাতে চলে যায়।", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["ক্রুসেডার নৌবহর জারবা দখল করল — তুরগুত পাশার ঘাঁটি হাতছাড়া", "f41b3f2a"], "d": ["স্পেন, পোপতন্ত্র, মাল্টা, জেনোয়া ও ফ্লোরেন্সের জাহাজে গঠিত ক্রুসেডার নৌবহর তুরগুত রেইস 1551 সাল থেকে অভিযান-ঘাঁটি হিসেবে ব্যবহৃত জারবাকে লক্ষ্যবস্তু করে। ঝড় ও মহামারির কারণে দ্বীপের সামনে তারা কেবল 1560 সালের শুরুতে পৌঁছাতে পারে; 12 মার্চ 1560 তারিখে দ্বীপটি দখল করে একটি দুর্গ নির্মাণ করে। খবর পেয়ে পিয়ালে পাশা 28 মার্চ 120টি গ্যালির নৌবহর নিয়ে ইস্তানবুল থেকে রওনা হন। দখল দীর্ঘস্থায়ী হয়নি: অটোমান নৌবহর মে মাসে জারবার সামনে মিত্রদের পরাজিত করে এবং দুর্গ জুলাইয়ের শেষে পুনরুদ্ধার হয়। এই অভিযান প্রেভেজার পর ভূমধ্যসাগরে অটোমান আধিপত্য সুদৃঢ়কারী দ্বিতীয় বৃহৎ নৌ-অভিযানের সূচনা।", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["জারবা দুর্গের পতন — দ্বীপ অটোমান শাসনে", "f1efc0df"], "d": ["পিয়ালে পাশার 14 মে 1560 তারিখের নৌ-বিজয়ের পর ক্রুসেডার বাহিনী দ্বীপে নির্মিত দুর্গে আশ্রয় নেয়; ত্রিপোলির বেইলারবেই তুরগুত পাশার বাহিনী স্থলপথে অবরোধ করে। দুই মাসব্যাপী অবরোধ 30 জুলাই 1560 তারিখে দুর্গের পতনের মাধ্যমে শেষ হয় এবং দ্বীপটি ত্রিপোলি বেইলারবেইয়ের সঙ্গে যুক্ত হয়। নৌ-বিজয় ও দুর্গ জয়ের মধ্যে সাতাত্তর দিনের ব্যবধান; দ্বীপ 14 মে নয়, 30 জুলাই কার্যত হাত বদলেছে।", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["দানজিগে রুশ-প্রুশীয় দ্বৈত শাসনের অবসান — নেপোলিয়নের মুক্ত শহর প্রুশিয়ায় ফিরল", "1ccda4d2"], "d": ["টিলসিটের শান্তির (9 জুলাই 1807) মাধ্যমে প্রুশিয়া থেকে বিচ্ছিন্ন হয়ে ফরাসি আশ্রয়ে মুক্ত শহর করা দানজিগকে নেপোলিয়নের বাহিনী 1813 সালের অবরোধের পর ত্যাগ করে। 2 জানুয়ারি – 4 ফেব্রুয়ারি 1814 পর্যন্ত শহরে রুশ-প্রুশীয় দ্বৈত শাসন চলে; জার আলেকজান্ডার দানজিগ ও ভিস্টুলা মোহনা নেওয়ার পরিকল্পনা ত্যাগ করলে শহর প্রুশীয় শাসনে যায়।", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["ভিয়েনায় ক্রাকাউ স্বাধীন, মুক্ত ও নিরপেক্ষ শহর ঘোষিত", "19eea839"], "d": ["ভিয়েনা কংগ্রেসে রাশিয়া, অস্ট্রিয়া ও প্রুশিয়া ক্রাকাউ শহরকে তার পারিপার্শ্বিক অঞ্চলসহ তিন রাষ্ট্রের সুরক্ষাধীন একটি মুক্ত রাষ্ট্রে পরিণত করে; ভিয়েনা চূড়ান্ত দলিল এই ব্যবস্থাকে স্বীকৃতি দেয়।", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["ক্রাকাউ মুক্ত শহর বিলুপ্ত, অস্ট্রিয়ায় অন্তর্ভুক্ত", "15548a14"], "d": ["1846 সালের ফেব্রুয়ারির ক্রাকাউ অভ্যুত্থানকে অজুহাত করে রাশিয়া, অস্ট্রিয়া ও প্রুশিয়া ভিয়েনার সম্মেলনে মুক্ত শহর বিলুপ্ত করে অস্ট্রীয় ভূখণ্ডে অন্তর্ভুক্ত করার সিদ্ধান্ত নেয়; ইংল্যান্ড ও ফ্রান্সের আপত্তি ফল দেয়নি।", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["বোর্নু রাবিহ ইবনে জুবায়েরের কর্তৃত্বে এল", "8be4ca96"], "d": ["বাগিরমি ও ওয়াদাইকে নাড়িয়ে দেওয়া সুদানি যুদ্ধনায়ক রাবিহ ইবনে জুবায়ের বোর্নু দখল করেন; 1896 সালের মধ্যে গোটা দেশ হস্তগত করে দিকোয়াকে কেন্দ্র করেন।", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["রাবিহ ইবনে জুবায়ের ফরাসিদের কাছে পরাজিত ও নিহত — বোর্নুতে তাঁর কর্তৃত্বের অবসান", "fb5a3ace"], "d": ["ফরাসি ঔপনিবেশিক বাহিনীর কাছে পরাজিত রাবিহ নিহত হন; তাঁর পুত্র কর্তৃত্ব ধরে রাখতে চাইলেও টিকতে পারেননি এবং বোর্নু 1902 সালে ফ্রান্স, ইংল্যান্ড ও জার্মানির মধ্যে ভাগ হয়ে যায়।", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["গুমুলচিনা কেন্দ্রিক পশ্চিম থ্রেস অস্থায়ী সরকার ঘোষিত", "974b2e28"], "d": ["বুখারেস্ট চুক্তি (10 আগস্ট 1913) পশ্চিম থ্রেসকে বুলগেরিয়ার হাতে ছেড়ে দিলে অঞ্চলের তুর্কি জনগণ গুমুলচিনা কেন্দ্রিক একটি অস্থায়ী সরকার ঘোষণা করে; দেদেআগাচ দখলের পর সরকার ‘পশ্চিম থ্রেস স্বাধীন সরকার’ নামে স্বাধীনতা ঘোষণা করে। বৃহৎ শক্তিগুলোর হস্তক্ষেপে অটোমান সরকার একে সমর্থন করেনি; 29 সেপ্টেম্বর 1913 সালের ইস্তানবুল চুক্তি পশ্চিম থ্রেসকে বুলগেরিয়ার হাতে ছেড়ে দেয় এবং সরকারটি 25 অক্টোবর 1913 পর্যন্ত মাত্র সাতান্ন দিন টিকে ছিল।", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["জাতিসংঘের (লিগ অব নেশনস) সুরক্ষায় দানজিগ মুক্ত শহর প্রতিষ্ঠিত", "bd148fe8"], "d": ["ভার্সাই চুক্তির মাধ্যমে জার্মানি থেকে বিচ্ছিন্ন দানজিগ 10 জানুয়ারি 1920 থেকে মিত্র বৃহৎ শক্তিগুলোর অন্তর্বর্তী শাসনে ছিল; 15 নভেম্বর 1920 তারিখে লিগ অব নেশনসের সুরক্ষায় পোল্যান্ডের সঙ্গে শুল্ক ইউনিয়নভুক্ত মুক্ত শহর হিসেবে প্রতিষ্ঠিত হয়।", "c74affc1"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["ওরহান গাজীর মৃত্যু — বেলিক থেকে রাষ্ট্রে উত্তরণের চল্লিশ বছরের সমাপ্তি", "62c59cfd"], "d": ["1324 সালে ওসমান গাজীর মৃত্যুর পর বেলিকের নেতৃত্বে আসা ওরহান গাজী আটত্রিশ বছরের শাসনে অটোমানদের একটি সীমান্ত বেলিক থেকে মারমারার দুই তীরে প্রতিষ্ঠিত রাষ্ট্রে রূপান্তরিত করেন: বুর্সা (1326), ইজনিক (1331) ও ইজমিত (1337) দখল হয়, কারেসি বেলিক সংযুক্ত হয়, প্রথম আকচা মুদ্রা প্রচলিত হয় (1327), প্রথম মাদ্রাসা ইজনিকে স্থাপিত হয় (1331) এবং রুমেলিতে উত্তরণ চিম্পে (1352) ও গেলিবোলু (1354) হয়ে স্থায়ী হয়। রুমেলি বিজয়ে নেতৃত্বদানকারী জ্যেষ্ঠ পুত্র সুলায়মান পাশাকে তিনি 1357 সালে শিকার দুর্ঘটনায় হারান; নিজে 1362 সালের মার্চে বুর্সায় মারা যান এবং তাঁর স্থলে পুত্র প্রথম মুরাদ অধিষ্ঠিত হন।", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["বাহরাইন দ্বীপপুঞ্জ জাবরিদের হাতে যাওয়া", "6a242b16"], "d": ["টিডিভির বাহরাইন নিবন্ধে উল্লেখ আছে, দ্বীপ “ক্রমান্বয়ে উয়ুনি, সালগুরি, তাবি ও জাবরিদের শাসনে ছিল এবং জাবরি আমলে সংখ্যাগরিষ্ঠ শিয়া থেকে সুন্নিতে রূপান্তরিত হয়”; কোনোটির তারিখ দেওয়া নেই। সাধারণ সাহিত্যে জাবরি রাজবংশ পঞ্চদশ শতকের শুরুতে কাতিফের শেষ জারওয়ানি শাসককে উৎখাত করে প্রতিষ্ঠিত হয় এবং চরম উৎকর্ষের সময়ে (আজওয়াদ ইবনে যামিল, মৃ. 1496) পারস্য উপসাগরের সমগ্র আরব উপকূল, লাহসা, কাতিফ ও বাহরাইন দ্বীপপুঞ্জ নিয়ন্ত্রণ করে। আজওয়াদের পর দ্বীপপুঞ্জ মুকরিন ইবনে যামিলের হাতে যায় — 1521 সালে পর্তুগিজদের কাছে পরাজিত হবেন এই শাসকই।", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["পর্তুগালের আরজিলা দখল — মরক্কোর উপকূলে দ্বিতীয় ঘাঁটি", "83444a11"], "d": ["পঞ্চম আফোনসো 30,000 জনের বাহিনী ও 400 জাহাজের নৌবহর নিয়ে নিজে মরক্কোর উপকূলে অবতরণ করেন এবং ওয়াত্তাসি শাসনাধীন আরজিলা 24 আগস্ট 1471 তারিখে দখল করেন। শহরের পতন তাঞ্জিয়ারের প্রতিরোধ ভেঙে দেয়; তাঞ্জিয়ার চার দিন পরে, 28 আগস্ট বিনা যুদ্ধে আত্মসমর্পণ করে। পর্তুগাল এভাবে সেউটা (1415) ও আলকাসের-সেগের (1458) পর মরক্কোর আটলান্টিক উপকূলে তৃতীয় ও চতুর্থ ঘাঁটি স্থাপন করে; রাজা এই অভিযানের পর নিজের উপাধিতে “আফ্রিকার প্রভু” যুক্ত করান।", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["সাফির পর্তুগিজ প্রভাবাধীন হওয়া", "765e703e"], "d": ["আটলান্টিক উপকূলের সবচেয়ে ব্যস্ত শস্য ও মৎস্য বন্দর সাফি 1488 সালে পর্তুগিজ প্রভাবাধীন হয়; শহর কিছুকাল স্থানীয় শাসকদের হাতে পর্তুগিজ আশ্রয়ে শাসিত হয় এবং 1508 সালে সরাসরি দখল হয়। সূত্রগুলো এই দুই পর্যায়কে ভিন্নভাবে গুরুত্ব দেয় বলে সূচনার তারিখ 1488 ও 1508-এর মধ্যে ওঠানামা করে; দুটিই একই প্রক্রিয়ার দুই প্রান্ত। সাফি তিপ্পান্ন বছর পর্তুগিজ হাতে ছিল এবং 1541 সালে আগাদিরের পতনের পর পরিত্যক্ত হয়।", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["সান্তা ক্রুজ দো কাবো দে গুয়ের প্রতিষ্ঠা — আগাদিরে পর্তুগিজ দুর্গ", "cc22c433"], "d": ["সুস উপকূলে, তখন পর্যন্ত পর্তুগালের পৌঁছানো হয়নি এমন স্থানে বেসরকারি উদ্যোগে নির্মিত সান্তা ক্রুজ দো কাবো দে গুয়ে দুর্গ 1505 সালে গড়া হয় এবং 1513 সালে পর্তুগিজ রাজমুকুটের হাতে হস্তান্তরিত হয়। দুর্গটি সুস উপত্যকার চিনি ও স্বর্ণ বাণিজ্য নিয়ন্ত্রণ করে মারাকেশের দক্ষিণ-পশ্চিম নির্গমন পথ বন্ধ করে রেখেছিল; তাই সাদি আন্দোলনের প্রথম বড় লক্ষ্য হয়। 1533 সালের অবরোধ প্রতিহত হয়, 1541 সালেরটি সফল হয় এবং মরক্কোতে পর্তুগালের পতন শুরু করে।", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["আজেমমুর দখল — উম্মুররাবির মোহনার নিয়ন্ত্রণ", "232acd4b"], "d": ["ব্রাগানজার ডিউক জাইমের নেতৃত্বাধীন পর্তুগিজ বাহিনী উম্মুররাবি নদীর মোহনার আজেমমুরে 3 সেপ্টেম্বর 1513 তারিখে প্রতিরোধ ছাড়াই প্রবেশ করে। শহর দখলের ফলে নদীমুখ ও অভ্যন্তরের শস্য পথ উভয়ের নিয়ন্ত্রণ আসে এবং পরের বছর 12 কিমি দক্ষিণ-পশ্চিমে মাজাগান দুর্গ নির্মাণের পথ খোলে। আজেমমুর আটাশ বছর পর্তুগিজ হাতে ছিল।", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["মাজাগান দুর্গ প্রতিষ্ঠা — মরক্কোয় সবচেয়ে দীর্ঘস্থায়ী পর্তুগিজ ঘাঁটি", "786cdb40"], "d": ["আজেমমুর দখলের পরের বছর, 1514 সালের গ্রীষ্মে উপকূলে মাজাগান দুর্গ নির্মিত হয়। 1541 সালের সাধারণ পতনের পর পর্তুগাল মরক্কোর সব ঘাঁটি ছাড়লেও মাজাগান ছাড়েনি; বরং দুর্গটি ইতালীয় ধাঁচের বুরুজে নতুন করে গড়ায় এবং শহর দুইশত পঞ্চান্ন বছর ধরে রাখা হয়। 1562 সালের বড় অবরোধও প্রতিহত হয়। মাজাগান মরক্কোয় পর্তুগালের শেষ ঘাঁটি হিসেবে 1769 সালে খালি করা হবে।", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["মারদিন দুর্গের আত্মসমর্পণ — দিয়ারবাকিরের দক্ষিণে সাফাভি প্রতিরোধের অবসান", "e6226de5"], "d": ["চালদিরানের পর দিয়ারবাকির অঞ্চলের দিকে অগ্রসর বিয়িকলি মেহমেদ পাশা মারদিন অবরোধ করলে সাফাভি বাহিনী 1515 সালের অক্টোবরে দুর্গে আশ্রয় নেয়; শহর অটোমান হাতে গেলেও দুর্গ প্রতিরোধ চালায়। সাফাভি গভর্নর কারা খানের শক্তিবৃদ্ধি নিয়ে পাল্টা আক্রমণ 1516 সালের মে মাসে কোচহিসার (কিজিলতেপে) যুদ্ধে পরিণত হয় — দেদে গারকিন প্রান্তরে সারাদিন চলা লড়াইয়ে কারা খানের শিরশ্ছেদ হয় এবং তাঁর সেনা ছত্রভঙ্গ হয়। দুর্গ টিডিভির ভাষায় “মাত্র নয় মাস পর” আত্মসমর্পণ করে।", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["পর্তুগালের বাহরাইন দখল — জাবরি কর্তৃত্বের অবসান", "315a435a"], "d": ["জাবরি শাসক মুকরিন ইবনে যামিল হরমুজকে কর দিতে অস্বীকার করলে পর্তুগিজ নৌবহর ও পর্তুগালের অধীন হরমুজ রাজ্যের বাহিনী দ্বীপে অবতরণ করে; মুকরিন যুদ্ধে পরাজিত হন এবং বাহরাইন 1521 সালে পর্তুগিজ শাসনে আসে। এরপর আশি বছর দ্বীপ হরমুজের মাধ্যমে, অধিকাংশ সময় সুন্নি ইরানি গভর্নরদের হাতে শাসিত হয়। বাহরাইনের মুক্তা ও কৌশলগত অবস্থান দ্বীপটিকে উপসাগরে অটোমান-পর্তুগিজ প্রতিদ্বন্দ্বিতার প্রত্যক্ষ লক্ষ্যে পরিণত করবে।", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["আগাদিরের পতন — সাদিদের মরক্কো থেকে পর্তুগিজ উচ্ছেদ শুরু", "bb1568f6"], "d": ["সাদি সুলতান মুহাম্মদ আশ-শেখ 16 ফেব্রুয়ারি 1541 তারিখে সান্তা ক্রুজ দুর্গ অবরোধ করেন এবং 12 মার্চ তা দখল করেন; গভর্নর গুতেরে দে মনরয়সহ প্রায় ছয়শত পর্তুগিজ বন্দি হয়।", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["সাফি ও আজেমমুর খালি করা — পর্তুগাল আটলান্টিক উপকূল থেকে সরে যাচ্ছে", "4cb6099a"], "d": ["1541 সালের 12 মার্চ আগাদিরের পতন এবং মরক্কোর সুলতানের সঙ্গে প্রত্যাশিত মিত্রতা না হওয়ায় তৃতীয় জোয়াও আটলান্টিক উপকূলের দুটি বড় ঘাঁটি খালি করার আদেশ দেন; সাফি ও আজেমমুরের সরে যাওয়া 1541 সালের শরতে, সেপ্টেম্বর-অক্টোবরে সম্পন্ন হয়। এভাবে এক বছরে তিনটি ঘাঁটি হাতছাড়া হয় এবং মরক্কো উপকূলে পর্তুগালের পঞ্চাশ বছরের বিস্তার উল্টে যায়; অবশিষ্ট থাকে সেউটা, তাঞ্জিয়ার, আরজিলা, আলকাসের-সেগের ও নতুন সুরক্ষিত মাজাগান।", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["আরজিলা খালি করা — পর্তুগাল উত্তর উপকূলে সংকুচিত", "b5d18373"], "d": ["আর্থিক সংকট ও সাদি চাপের সম্মিলনে তৃতীয় জোয়াও 1471 সাল থেকে ধরে রাখা আরজিলা খালি করেন। মরক্কোয় পর্তুগালের উপস্থিতি এভাবে সেউটা, তাঞ্জিয়ার ও মাজাগানে নেমে আসে। আরজিলা 1577 সালে অল্প সময়ের জন্য আবার দখল হবে, 1589 সালে চূড়ান্তভাবে পরিত্যক্ত হবে।", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["অটোমানদের বাহরাইন অভিযান — উপসাগরে পর্তুগালের বিরুদ্ধে শেষ বড় পদক্ষেপ", "14501df3"], "d": ["1546 সালে বসরা সংযুক্তি এবং লাহসা প্রদেশ প্রতিষ্ঠার মাধ্যমে উপসাগরের আরব উপকূলে অবস্থান নেওয়া অটোমান রাষ্ট্র দ্বীপের মুক্তা বাণিজ্য ও পর্তুগালের হরমুজ পথকে লক্ষ্য করে লাহসার বেইলারবেই মুস্তাফা পাশার নেতৃত্বে বাহরাইনের দিকে অগ্রসর হয়। অভিযানের ফল সূত্রে ভিন্ন: টিডিভি ইসলাম বিশ্বকোষ লেখে অটোমানরা “1559 সালে বাহরাইন দখল করে সেখানে একটি ঘাঁটি” গড়ে, দ্বীপপুঞ্জ “পরে আবার পর্তুগিজদের শাসনে” যায়; পশ্চিমা সাহিত্য বলে অবরোধ ব্যর্থ হয়, হরমুজ থেকে সমুদ্রপথে আসা পর্তুগিজ সাহায্য অটোমান বাহিনীকে হটিয়ে দেয় এবং উভয় পক্ষকে ভেঙে দেওয়া এক মহামারির পর অটোমানরা আত্মসমর্পণের শর্ত চায়। দুই বর্ণনা ফলাফলেই ভিন্ন; অভিন্ন বিষয় হলো, বাহরাইন অটোমানদের হাতে স্থায়ী হয়নি।", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["উলুচ আলি পাশার তিউনিস দখল — হাফসি-স্পেনীয় ব্যবস্থার অবসান", "d4498698"], "d": ["শার্লকেন 1535 সালে তিউনিস দখল করলে নিজে শহর শাসন করেননি, হাফসি সুলতান মাওলায় হাসানকে সিংহাসনে ফিরিয়ে বসান; টিডিভির ভাষায় তিউনিস শহর “1569 সালে অটোমানদের দ্বিতীয় হস্তক্ষেপ পর্যন্ত স্পেনীয়দের আশ্রয়ে এবং তৃতীয় মাওলায় আহমদের শাসনে” ছিল। 27 জুন 1568 তারিখে আলজিয়ার্সের বেইলারবেই নিযুক্ত উলুচ আলি স্থলপথে তিউনিসের দিকে অগ্রসর হন, বেজায় হাফসি সুলতানকে পরাজিত করে শহরে প্রবেশ করেন; মাওলায় আহমদ স্পেনীয় দুর্গ হালকুলওয়াদিতে আশ্রয় নেন। এভাবে উপসাগর দুই ভাগ হয় — শহর অটোমান, বন্দর-দুর্গ স্পেনীয় — এবং এই বিভাজন চার বছর স্থায়ী হয়।", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["দন হুয়ান দে অস্ট্রিয়ার তিউনিস পুনরুদ্ধার — লেপান্তোর স্থলে একমাত্র প্রতিফল", "a6f044ee"], "d": ["লেপান্তোর (1571) পর পবিত্র লিগ ভেঙে গেলেও স্পেন একাই উত্তর আফ্রিকায় অগ্রসর হয়: টিডিভির ভাষায় “10 অক্টোবর 1573 তারিখে স্পেনীয়রা তিউনিসের নিয়ন্ত্রণ নিতে নতুন অভিযানে নামে। তিউনিস দখল করে সেখানে 8000 সৈন্য রেখে যায়।” দন হুয়ান দে অস্ট্রিয়ার নেতৃত্বে এই অভিযানই লেপান্তো বিজয়ের স্থলে একমাত্র প্রতিফল; তবে তা স্থায়ী হয়নি এবং শহর এগারো মাস পরে পুনরুদ্ধার হয়। দখলের ফলে যা উৎখাত হয় তা ছিল প্রতিষ্ঠিত একটি অটোমান প্রশাসন: 2 জিলহজ্জ 980 তারিখে (5 এপ্রিল 1573) তিউনিসের অধিনায়ক ছিলেন কিলিচ আলি পাশা, কায়মাকাম রামাজান পাশা, বেইলারবেই হায়দার পাশা।", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["সাফাভিদের পর্তুগালের কাছ থেকে বাহরাইন গ্রহণ", "c37d982c"], "d": ["শাহ প্রথম আব্বাসের পাঠানো বাহিনী দ্বীপের বিদ্রোহীদের সঙ্গে মিলে পর্তুগিজ গ্যারিসনকে দুর্গ থেকে বের করে দেয়; টিডিভির ভাষায় দ্বীপপুঞ্জ “1602 সালে ইরানের অধীন বাহিনীর দ্বারা” পর্তুগিজদের হাত থেকে নেওয়া হয়। বাহরাইন এভাবে একাশি বছরের পর্তুগিজ শাসন থেকে বেরিয়ে সাফাভি আধিপত্যে আসে এবং একশত পনেরো বছর ইরানের অধীন থাকে। এটি উপসাগরে পর্তুগালের পতনের প্রথম ধাপ; বিশ বছর পর হরমুজও ইংরেজ-ইরানি যৌথ অভিযানে পতিত হবে।", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["ওমানিদের বাহরাইন আক্রমণ — সাফাভি কর্তৃত্বের অবসান", "c9be5820"], "d": ["সাফাভি রাষ্ট্রের শেষ বছরগুলোর বিপর্যয়ের সময় ইয়ারুবি রাজবংশের অধীন ওমানি নৌবহর দ্বীপ আক্রমণ করে এবং সাফাভি কর্তৃত্ব শেষ হয়। এর পরের পঁয়ত্রিশ বছর উপসাগরের সবচেয়ে বিশৃঙ্খল সময়: দ্বীপ ওমান, ইরান ও স্থানীয় আরব শক্তির মধ্যে কয়েকবার হাত বদলায়।", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["বাহরাইনের বুশেহরের আল-ই মেজকুর শাসনে যাওয়া", "610e2f9d"], "d": ["মূলত ওমান থেকে এসে বুশেহরে বসতি গড়া এবং হুওয়ালা হিসেবে গণ্য আল-ই মেজকুর পরিবার 1753 সালে বুশেহরের ঘাঁটি থেকে বাহরাইনকে নিজেদের শাসনে নেয়। পরিবারটি ইরানের উপসাগরীয় উপকূলের আরব সম্প্রদায়গুলোর নেতৃত্ব দিত এবং ইরানের পক্ষে দ্বীপ শাসন করত; শেষ প্রতিনিধি নাসর আল-ই মেজকুর জান্দ প্রশাসন কর্তৃক বাহরাইনের গভর্নর নিযুক্ত হন। এটিই আল-ই খলিফার আগে দ্বীপের শেষ শাসন।", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["মাজাগান খালি করা — মরক্কোয় পর্তুগালের শেষ ঘাঁটির পতন", "f9e9749d"], "d": ["আলাওয়ি সুলতান তৃতীয় মুহাম্মদ ইবনে আবদুল্লাহ 1769 সালের শুরুতে যে অবরোধ শুরু করেন তার মুখে 592 জনের গ্যারিসন টিকতে পারেনি; লিসবন থেকে 1 ফেব্রুয়ারি রওনা হওয়া উদ্ধার নৌবহর 11 মার্চ 1769 তারিখে শেষ সৈন্যদের জাহাজে তোলে এবং সর্বশেষ গভর্নর দিনিস গ্রেগোরিও শহর ত্যাগ করেন। এভাবে 1415 সালে সেউটা দখলের মাধ্যমে শুরু হওয়া মরক্কোয় পর্তুগালের উপস্থিতি সাড়ে তিন শতক পর শেষ হয়। মাজাগান ছিল 1541 সালের সাধারণ পতনের পর ধরে রাখা একমাত্র আটলান্টিক উপকূলীয় ঘাঁটি এবং দুইশত পঞ্চান্ন বছর নিয়ে মরক্কোয় পর্তুগালের সবচেয়ে দীর্ঘ ধরে রাখা স্থান।", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["আল-ই খলিফার বাহরাইন বিজয় — আজও টিকে থাকা রাজবংশের প্রতিষ্ঠা", "8773b011"], "d": ["জান্দ প্রশাসনের বাহরাইন গভর্নর নাসর আল-ই মেজকুর কাতার উপদ্বীপের জুবারা অবরোধ করেন; আহমদ ইবনে মুহাম্মদ ইবনে খলিফার নেতৃত্বাধীন উতুব বাহিনী অবরোধ ভেঙে পাল্টা আক্রমণে গিয়ে একই বছর বাহরাইন দখল করে। টিডিভির বিবরণ সংক্ষিপ্ত: “বাহরাইন 1783 সালে উতুব গোত্রের আল-ই খলিফার কর্তৃত্বে আসে।” আহমদ ইবনে মুহাম্মদ এই বিজয়ের পর “আল-ফাতিহ” উপাধিতে পরিচিত হন এবং তাঁর প্রতিষ্ঠিত রাজবংশ আজও দ্বীপে শাসন করছে।", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["ইংল্যান্ডের সঙ্গে বাহরাইনের চুক্তি — উপসাগরে আশ্রিত ব্যবস্থায় প্রবেশ", "576796b2"], "d": ["টিডিভির বিবরণ অনুযায়ী “21 মে 1861 তারিখে ইংল্যান্ড এবং বাহরাইনের প্রতিনিধি শেখ মুহাম্মদের ভাই আলি অঞ্চলে দাস বাণিজ্য ও জলদস্যুতা নিষিদ্ধকারী একটি চুক্তি স্বাক্ষর করেন”; ইংরেজ দলিলে একই চুক্তি (Perpetual Truce of Friendship and Peace) 31 মে 1861 তারিখ বহন করে। চুক্তিটি বাহরাইনের পররাষ্ট্র সম্পর্ক ইংল্যান্ডের সঙ্গে বেঁধে দেওয়া আশ্রিত ব্যবস্থার প্রথম ধাপ এবং অটোমানদের 1871 সালে লাহসা ও কাতিফে পুনরায় বসতি স্থাপনের পরও দ্বীপ এই ব্যবস্থার বাইরে থাকে।", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["আহি এভরান — আহি সংগঠনের প্রতিষ্ঠাতা পির", "3392e100"], "d": ["আহি এভরান আনাতোলিয়ায় আহি সংগঠনের প্রতিষ্ঠাতাদের একজন এবং দাব্বাগদের (চর্মকার) পির বলে গণ্য। কির্শেহিরে তাঁর জাভিয়ে অটোমান যুগে কারিগর/গিল্ড সংগঠনের আধ্যাত্মিক কেন্দ্র হিসেবে বিংশ শতকের শুরু পর্যন্ত টিকে ছিল; রাষ্ট্র এই অবস্থান 1780, 1782, 1822-23 ও 1842 সালে আনুষ্ঠানিকভাবে নিশ্চিত করেছে।", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["শেখ এদেবালি — আহি সংগঠন ও অটোমান রাজবংশের মধ্যে প্রতিষ্ঠার সংযোগ", "c1186059"], "d": ["বিলেজিকে জাভিয়ে স্থাপন করা এবং আহি সংগঠনেরও একজন শেখ হিসেবে অবস্থানকারী এদেবালি জনশ্রুতি অনুসারে ওসমান গাজীর বিখ্যাত স্বপ্নের ব্যাখ্যা দেন; এরপর ওসমান গাজী এদেবালির কন্যা মালহুন খাতুনকে বিয়ে করেন। এদেবালি একই সঙ্গে প্রথম অটোমান কাজি ও মুফতি বলে গণ্য।", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["বুর্সা বিজয়ের পর ওরহান গাজীর জিরিত খেলার জন্য জমি ওয়াকফ", "da1becbd"], "d": ["টিডিভির জিরিত নিবন্ধ অনুসারে ওরহান গাজী বুর্সা বিজয়ের পর আশপাশের একটি এলাকা ঘোড়দৌড় ও জিরিত খেলার জন্য ওয়াকফ করেন — অটোমানদের মধ্যে জিরিত খেলার প্রাতিষ্ঠানিক রূপ পাওয়া প্রথম লিপিবদ্ধ দৃষ্টান্তগুলোর একটি।", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["কিরকপিনার কুস্তির কথিত সূচনা", "2d93fa65"], "d": ["জনশ্রুতি অনুসারে কিরকপিনার কুস্তি ঐতিহ্য রুমেলি বিজেতা সুলায়মান পাশার সঙ্গে পার হওয়া চল্লিশ গাজীর মধ্যকার কুস্তি প্রতিযোগিতা থেকে শুরু। টিডিভির কুস্তি ও কিরকপিনার নিবন্ধ এই জনশ্রুতি উল্লেখ করে কিন্তু নির্দিষ্ট প্রতিষ্ঠার তারিখ দেয় না।", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["জ্যানিসারি বাহিনীর প্রতিষ্ঠা", "f4206dce"], "d": ["চান্দারলি কারা খলিল ও মোল্লা রুস্তেমের নির্দেশনায়, পেনচিক আইন অনুযায়ী যুদ্ধবন্দিদের মধ্য থেকে নেওয়া অমুসলিম তরুণদের প্রশিক্ষণের মাধ্যমে শুরু হওয়া ব্যবস্থা গেলিবোলুতে প্রতিষ্ঠিত আজেমি ওজাকের মাধ্যমে প্রথম মুরাদের সময় প্রাতিষ্ঠানিক রূপ পায়।", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["এদির্নে এস্কি মসজিদের (উলু মসজিদ) নির্মাণ শুরু", "da7a22ac"], "d": ["জনসাধারণের মধ্যে উলুজামি (জামি-ই আতিক) নামেও পরিচিত এস্কিজামির নির্মাণ আমির সুলায়মান চেলেবি 1402-1403 সালে শুরু করেন।", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["বুর্সা ইয়েশিল মসজিদ কমপ্লেক্সের নির্মাণ শুরু", "280b8a21"], "d": ["ফেত্রেত যুগের পর সিংহাসন পুনরায় একত্রকারী প্রথম মেহমেদ 1414 সালে কমপ্লেক্সের নির্মাণ শুরু করেন এবং একে বুর্সার কেন্দ্রীয় স্থানে, দাদা ও পিতার কমপ্লেক্স থেকে আলাদা করে চেনা যায় এমনভাবে স্থাপন করেন। প্রধান স্থপতি হাজি ইভাজ পাশা।", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["বুর্সা ইয়েশিল মসজিদ কমপ্লেক্স সমাপ্ত", "bc82821f"], "d": ["তাবরিজের কারিগরদেরও অবদান রাখা টাইল ও অলংকরণ কর্মসূচির জন্য পরিচিত ইয়েশিল মসজিদ কমপ্লেক্স 1419 সালের ডিসেম্বরে সমাপ্ত হয়। কমপ্লেক্স মসজিদ, সমাধিসৌধ (ইয়েশিল সমাধি), মাদ্রাসা, ইমারেত ও হাম্মামখানায় গঠিত; আদি অটোমান স্থাপত্যের সবচেয়ে সমৃদ্ধ নিদর্শনগুলোর একটি।", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["দেভশিরমে ব্যবস্থার কার্যত প্রয়োগ শুরু", "fa835172"], "d": ["আগের ইসলামি রাষ্ট্রগুলোতে দেখা যায়নি এমন দেভশিরমে পদ্ধতি প্রথমে পেনচিক আইন অনুযায়ী অমুসলিম যুদ্ধবন্দি তরুণদের কাজে লাগানোর রূপে শুরু হয়। টিডিভি (TDV)-র মতে, ‘চেলেবি মেহমেদের সময়ে প্রয়োগ করা হলেও তাঁর পুত্র দ্বিতীয় মুরাদের আমলে আইনে পরিণত হয়েছে বলে বোঝা যায়।’", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["শেখুল ইসলাম পদের সূচনা — মোল্লা ফেনারির বুরসার মুফতি পদ", "2a8ee2b9"], "d": ["দীর্ঘ বছর বুরসার কাজি থাকা আলিম মোল্লা ফেনারির 1425 সালে বুরসার মুফতি পদে নিয়োগকে টিডিভি (TDV)-র ভাষায় ‘অটোমানদের মধ্যে মুফতিত্ব ও শেখুল ইসলামি পদের সূচনা’ গণ্য করা হয়। তবে টিডিভি উল্লেখ করে যে এটি পঞ্চদশ নয়, ষোড়শ শতকে সমগ্র ইলমিয়া সংগঠনের প্রতিনিধিত্বকারী পূর্ণ প্রাতিষ্ঠানিক শেখুল ইসলাম পদের সঙ্গে অভিন্ন নয়।", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["তিমার ব্যবস্থার প্রাতিষ্ঠানিকীকরণ", "dc267780"], "d": ["নথিভিত্তিক প্রথম তিমার উল্লেখ ওরহান বেগের আমল পর্যন্ত পাওয়া যায়; তবে পদ্ধতিগত আইনিকরণ ঘটে দ্বিতীয় মুরাদের আমলে। এ সময়ে প্রস্তুত তিমার ইজমাল দফতরগুলো দেখায় যে ব্যবস্থার সব মৌলিক নীতি গড়ে উঠেছিল; 1432 সালের কাছাকাছি সময়ের নথিপত্র প্রমাণ করে যে আইনগুলো পূর্ণ কার্যকর ছিল।", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["উচ শেরেফেলি মসজিদ ও কমপ্লেক্স সমাপ্ত", "cde6993e"], "d": ["দ্বিতীয় মুরাদ কর্তৃক মুসলিহুদ্দিন ও শিহাবুদ্দিন নামের কারিগরদের দিয়ে দশ বছরে (1437-1447) নির্মিত উচ শেরেফেলি মসজিদ অটোমান স্থাপত্যে কেন্দ্রীয় নকশার মসজিদের প্রথম নিদর্শন বলে গণ্য এবং ধ্রুপদী যুগের পূর্ববর্তী উত্তরণ স্থাপত্যের অন্যতম মোড় পরিবর্তনকারী কাজ।", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["ফাতিহের আইনে দিওয়ান-ই হুমায়ুনের প্রাতিষ্ঠানিকীকরণ", "e8443e77"], "d": ["দ্বিতীয় মুরাদের আমলে এডির্নে দিওয়ান নিয়মিত বিধিতে বাঁধা পড়ে ‘দিওয়ান-ই হুমায়ুন’ পরিচয় অর্জন করতে শুরু করে। প্রকৃত রূপান্তর আসে সুলতান ফাতিহ মেহমেদের আইনে: সবচেয়ে বড় নতুনত্ব ছিল সুলতানের দিওয়ান-সভাপতিত্ব পুরোপুরি তুলে দিয়ে তা প্রধান উজিরের হাতে অর্পণ।", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["ফাতিহ সুলতান মেহমেদের ওকমেইদানি তীরন্দাজদের জন্য বরাদ্দ", "342a9fd5"], "d": ["ইস্তানবুল বিজয়ের সময় কাসিমপাশার ঢালে শিবির স্থাপনকারী ফাতিহ সুলতান মেহমেদ জায়গাটি একই সঙ্গে তীরন্দাজদের প্রশিক্ষণ-মাঠ হিসেবে ব্যবহার করেছিলেন; শহর দখলের পর এলাকাটি স্থায়ীভাবে তীরন্দাজদের জন্য বরাদ্দ করেন। এই বরাদ্দ ওকমেইদানির শতাব্দীব্যাপী অটোমান তীরন্দাজি ঐতিহ্যের কেন্দ্র হওয়ার সূচনা।", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["ইরানি রেশম বাণিজ্যে বুরসার শীর্ষে ওঠা", "f1324cdf"], "d": ["তাব্রিজ থেকে আসা কাফেলাগুলো গিলান, আস্তারাবাদ ও সারির রেশম বুরসায় বয়ে আনত, আর এখানে জেনোয়া, ভেনিস, ফ্লোরেন্স ও ইহুদি ব্যবসায়ীরা প্রতিযোগিতা করে তা কিনত। 1479 সালে ইরান থেকে আমদানি করা রেশমের মূল্য 150.000 ভেনিসীয় স্বর্ণমুদ্রায় পৌঁছায়; 1502 সালে শহরে 1000-এরও বেশি তাঁত চলছিল।", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["দ্বিতীয় বায়েজিদের কিরকপিনার কুস্তিগিরদের বড় পুরস্কার প্রদান", "d745b882"], "d": ["টিডিভির কুস্তি নিবন্ধ অনুসারে দ্বিতীয় বায়েজিদ 1504 সালে কুস্তিগিরদের 3.000 ও 1.500 কুরুশের পুরস্কার দেন; কুস্তি খেলার প্রতি অটোমান রাজদরবারের পৃষ্ঠপোষকতার লিপিবদ্ধ আদি দৃষ্টান্তগুলোর একটি।", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["বায়েজিদ মসজিদ ও কমপ্লেক্স সমাপ্ত", "eb9ab65b"], "d": ["দ্বিতীয় বায়েজিদের জন্য নির্মিত বায়েজিদ মসজিদ ও কমপ্লেক্সের নির্মাণ একটি আর্কাইভ দলিল অনুসারে 906 হিজরিতে (1500) শুরু হয় এবং 14 জমাদিউল আউয়াল 911-এ (13 অক্টোবর 1505) সমাপ্ত হয়। স্থপতি নিয়ে বিতর্ক আছে: আইভানসারাইয়ির বিবরণের ভিত্তিতে দীর্ঘকাল স্থপতি হায়রেদ্দিনের কাজ ধরা হতো, পরে কেমালেদ্দিনের বলে গণ্য হয়, কারও মতে দুজন একসঙ্গে কাজ করেছেন; একই দলিল অবশ্য কারিগর হিসেবে ইয়াকুব শাহ ইবনে সুলতান শাহকে দেখায়। মসজিদটি ধ্রুপদী-পূর্ব অটোমান স্থাপত্য থেকে ধ্রুপদী যুগে উত্তরণের গুরুত্বপূর্ণ স্মৃতিস্তম্ভগুলোর একটি।", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["তের্সানে-ই আমিরের ইস্তানবুলে (কাসিমপাশা/গোল্ডেন হর্ন) স্থানান্তর", "f36e3675"], "d": ["সুলতান প্রথম সেলিমের আমলে গালাতা প্রাচীরের পশ্চিমের উপসাগরে নির্মাণ শুরু হওয়া নতুন নৌ-কারখানা 1515 সালে 160 বে (গজ) নিয়ে সম্পন্ন হয়; এভাবে গেলিবোলুকেন্দ্রিক নৌ-কারখানার কার্যক্রম ইস্তানবুলে সরে আসে। প্রতিষ্ঠানটি পরে বারবারোস হাইরেদ্দিন পাশার আমলে আনুষ্ঠানিকভাবে ‘তের্সানে-ই আমিরে’ নাম পায়।", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["শেখ হামদুল্লাহর মৃত্যু ও হস্তলিপি ঘরানার উত্তরাধিকার", "f5ed4d09"], "d": ["আমাসিয়ার শেখ হামদুল্লাহ দ্বিতীয় বায়েজিদের লিপিশিক্ষক হিসেবে আকলাম-ই সিত্তে (ছয় লিপিশৈলী) ঘরানাকে পরিপক্বতায় পৌঁছে দিয়ে সমগ্র ইসলামি বিশ্বে প্রভাব বিস্তারকারী এক অটোমান লিপিশৈলীর প্রতিষ্ঠাতা হন। 1520 সালে মারা গেলে তিনি পেছনে বিস্তৃত শিষ্যবৃত্ত রেখে যান।", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["পিরি রেইসের কিতাব-ই বাহরিয়ের প্রথম সংস্করণ সমাপ্ত", "fd6cc1ff"], "d": ["ভূমধ্যসাগরের উপকূল, বন্দর ও নৌচালনা তথ্য সংকলনকারী কিতাব-ই বাহরিয়ের প্রথম (গদ্য) সংস্করণ পিরি রেইস 1521 সালে সমাপ্ত করেন। এই প্রথম সংস্করণ তখনো সুলতানকে উপস্থাপন করা হয়নি, পরবর্তী বছরগুলোতে সম্প্রসারিত হওয়া একটি খসড়া ছিল।", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["পিরি রেইসের কিতাব-ই বাহরিয়ে সম্প্রসারণ করে আইনদাতা সুলতান সুলায়মানকে উপহার", "d4abf0b7"], "d": ["পিরি রেইস কিতাব-ই বাহরিয়েকে আংশিক পদ্যে সম্প্রসারিত করে 1526 সালে আইনদাতা সুলতান সুলায়মানকে উপস্থাপন করেন। এই রূপে গ্রন্থটি অটোমান নৌবিদ্যার সবচেয়ে ব্যাপক নৌচালনা নির্দেশিকা হিসেবে ছড়িয়ে পড়ে।", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["মাত্রাকচি নাসুহের বেয়ান-ই মেনাজিলে ইরাকেইন অভিযানের পথ চিত্রণ", "aa012278"], "d": ["আইনদাতা সুলতান সুলায়মানের 1534 সালে যাত্রা করা প্রথম ইরান (ইরাকেইন) অভিযানে অংশ নেওয়া মাত্রাকচি নাসুহ ইস্তানবুল থেকে তাবরিজ, সেখান থেকে বাগদাদ পর্যন্ত সেনাবাহিনীর পথের প্রতিটি বিরতিস্থল ক্ষুদ্রচিত্র-মানচিত্র কৌশলে এঁকেছিলেন। এই কাজ বেয়ান-ই মেনাজিল-ই সেফের-ই ইরাকেইন নামের গ্রন্থে সংকলিত হয় এবং অটোমানদের মধ্যে মেনজিলনামা ধারার সবচেয়ে মৌলিক নিদর্শন।", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["বাগদাদ বিজয়ের পর ফুজুলির আইনদাতাকে কাসিদা উপহার", "1ef0653f"], "d": ["আইনদাতা সুলতান সুলায়মান 1534 সালে বাগদাদ জয় করার পর ফুজুলি অটোমান সুলতানকে “গেলদি বুর্জ-ই এভলিয়ায়ে পাদিশাহ-ই নামদার” চরণে শুরু হওয়া বিখ্যাত কাসিদাসহ পাঁচটি কাসিদা উপহার দেন; এভাবে সাফাভি আশ্রয় ছেড়ে অটোমান রাষ্ট্রনায়কদের পৃষ্ঠপোষকতা খোঁজেন।", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["ফুজুলির লাইলা ও মজনু মাসনাভি সমাপ্ত", "e3ef4085"], "d": ["ধ্রুপদী তুর্কি সাহিত্যের সবচেয়ে সুন্দর মাসনাভিগুলোর একটি বলে গণ্য লাইলা ও মজনু ফুজুলি 1535 সালে, আইনদাতার বাগদাদ অভিযানে অংশ নেওয়া ইস্তানবুলের কবিদের অনুরোধে রচনা করে সমাপ্ত করেন।", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["স্থপতি সিনানের রাজকীয় প্রধান স্থপতি পদে নিয়োগ", "7a753f0e"], "d": ["টিডিভি ইসলাম বিশ্বকোষের সিনান নিবন্ধ অনুসারে, রাজকীয় প্রধান স্থপতি আজেম আলির 1537 সালে মৃত্যুর পর বোগদান অভিযানে প্রুত নদীর ওপর নির্মিত সেতুর জন্য মনোযোগ আকর্ষণকারী সিনান প্রধান উজির লুৎফি পাশার সুপারিশে এই দায়িত্বে নিযুক্ত হন। এভাবে সিনানের পঞ্চাশ বছরের বেশি স্থায়ী প্রধান স্থপতির যুগ শুরু হয়।", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["শেহজাদে মসজিদ ও কমপ্লেক্সের নির্মাণ শুরু", "1a70ddfd"], "d": ["আইনদাতা সুলতান সুলায়মান 1543 সালে মহামারিতে হারানো পুত্র শেহজাদে মেহমেদের নামে কমপ্লেক্স নির্মাণের আদেশ দেন; নির্মাণ 1543 সালের জুনে শুরু হয়, প্রথমে সমাধিসৌধ শেষ করে পরে মসজিদ নির্মাণে যাওয়া হয়। এটি স্থপতি সিনানের নিজের ভাষায় “শিক্ষানবিশির কাজ”।", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["উসকুদার ইস্কেলে (মিহরিমাহ সুলতান) কমপ্লেক্স সমাপ্ত", "3769007f"], "d": ["উসকুদার ইস্কেলে চত্বরের কমপ্লেক্সের নির্মাণ 1540-এর দশকের প্রথম বছরগুলোতে শুরু হয়ে 1547 সালে সমাপ্ত হয়। মিহরিমাহ সুলতান স্থপতি সিনানকে দিয়ে যে দুটি বড় মসজিদ নির্মাণ করান তার মধ্যে কালানুক্রমে প্রথমটি; দ্বিতীয়টি (এদির্নেকাপি) প্রায় বিশ বছর পর সমাপ্ত হবে।", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["আলেপ্পোয় ভেনিসের কনসুলেট স্থাপন", "3aad8b9e"], "d": ["ষোড়শ শতকে ইউরোপীয়দের বাণিজ্যিক ভারকেন্দ্র দামেস্ক থেকে আলেপ্পোয় সরে যায়। এ পরিবর্তনের বাস্তব নিদর্শন হিসেবে ভেনিস 1548 সালে আলেপ্পোয় কনসুলেট খোলে; এরপর 1557 সালে ফ্রান্স ও 1586 সালে ইংল্যান্ড তা অনুসরণ করে। শহরটি ইউরোপের পশমি কাপড় ও রুপার সঙ্গে ভারতীয় মসলা এবং শতকের শেষে ইরানি রেশম বিনিময়ের প্রধান বাজারে পরিণত হয়।", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["শেহজাদে মসজিদ উপাসনার জন্য খুলে দেওয়া", "2bb3f4b2"], "d": ["প্রায় পাঁচ বছরের নির্মাণের পর শেহজাদে মসজিদ 1548 সালের আগস্টে উপাসনার জন্য খুলে দেওয়া হয়। জোড়া মিনার ও কেন্দ্রীয় গম্বুজের নকশায় এটি স্থপতি সিনানের পরবর্তী বড় কাজগুলোর পূর্বাভাস বলে গণ্য; কমপ্লেক্স মসজিদ, সমাধিসৌধ, মাদ্রাসা, ইমারেত, তাবহানে ও কাফেলা-সরাইয়ে গঠিত।", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["কিরকচেশমে জলপ্রণালী নির্মাণ শুরু", "14124b59"], "d": ["স্থপতি সিনান আইনদাতার আদেশে বেলগ্রেড বনভূমি থেকে ইস্তানবুলে পানি আনার সম্ভাব্যতা পরীক্ষা করে তা সম্ভব বলে জানান; বিশাল জলপ্রকল্পের নির্মাণ 1554 সালে শুরু হয়ে 1563 সালের আগে সমাপ্ত হয়। টিডিভি এটিকে সিনানের “প্রকৌশলের দিক থেকে সবচেয়ে গুরুত্বপূর্ণ, আয়তনের দিক থেকেও সবচেয়ে বড় কাজ” বলে বর্ণনা করে।", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["ইস্তানবুলে প্রথম কফিহাউস খোলা", "85c12f9f"], "d": ["অটোমান নগরজীবনে কফির প্রবেশ শুরু হয় তাখতাকালেতে আলেপ্পোর ব্যবসায়ী হাকেম ও দামেস্কের শামস নামের এক ব্যক্তির খোলা কফিহাউসগুলো দিয়ে। অল্প সময়ে সমাজের সব স্তরের মানুষ একত্র হওয়ার এক নতুন public sphere (গণপরিসর) গড়ে ওঠে; কানুনির শেষ দিকে ইস্তানবুলে পঞ্চাশটি কফিহাউস ছিল।", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["এবুসসুউদ এফেন্দির গেদিক (কারিগরি একচেটিয়া অধিকার) প্রশ্ন আইনগতভাবে পরীক্ষা", "5d4e2930"], "d": ["কারিগরি পেশায় নির্দিষ্ট সংখ্যক ব্যক্তিকে দেওয়া একচেটিয়া ও বিশেষাধিকার ‘গেদিক’-এর প্রশ্ন কানুনির আমলে আবার আলোচনায় আসে; শেখুল ইসলাম এবুসসুউদ এফেন্দি 1555-56 সালে বিষয়টি গভীরভাবে পরীক্ষা করে প্রথাটির বৈধতা সুলতানের কাছে উপস্থাপন করেন।", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["সেইদি আলি রেইসের মিরআতুল মামালিক ইস্তানবুলে সমাপ্ত", "ee8640e1"], "d": ["বাগদাদ থেকে শুরু করে ফেরার যাত্রাজুড়ে লেখা মিরআতুল মামালিক নামের ভ্রমণগ্রন্থ সেইদি আলি রেইস 1557 সালের জানুয়ারিতে ইস্তানবুলে সমাপ্ত করেন। গ্রন্থটি এক অটোমান নাবিকের ভারত মহাসাগর থেকে মধ্য এশিয়া হয়ে স্থলপথে স্বদেশে ফেরার প্রত্যক্ষ সূত্র।", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["রুস্তেম পাশা কমপ্লেক্সের (মসজিদ) নির্মাণ", "02e30725"], "d": ["আইনদাতার জামাতা ও প্রধান উজির রুস্তেম পাশা স্থপতি সিনানকে দিয়ে যে কমপ্লেক্স নির্মাণ করান তা 1555-1561 সালের মধ্যে গড়া হয়। স্থাপনাটি নিচে খিলানযুক্ত দোকানসহ উঁচু প্ল্যাটফর্মের ওপর নির্মিত অনন্য স্থাপত্য এবং সমৃদ্ধ ইজনিক টাইলের জন্য পরিচিত।", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["মোস্তার সেতু সমাপ্ত", "e7f434af"], "d": ["নেরেতভা নদীর ওপর বিখ্যাত মোস্তার সেতু 1566-67 সাল নাগাদ স্থপতি হায়রেদ্দিন নির্মাণ করেন; 1568 সালের একটি সরকারি দলিলে সেতুর উল্লেখ থাকা এর সমাপ্ত হওয়া নিশ্চিত করে। স্থাপনাটি এক খিলানবিশিষ্ট সূচালো খিলানের ধ্রুপদী অটোমান সেতু স্থাপত্যের সবচেয়ে পরিচিত নিদর্শনগুলোর একটি।", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["এদির্নেকাপি (মিহরিমাহ সুলতান) মসজিদ সমাপ্ত", "f2d21a82"], "d": ["আইনদাতার কন্যা মিহরিমাহ সুলতানের জন্য 1563 সালে নিশ্চিত হওয়া নির্মাণ অনুমতির পর শুরু হওয়া মসজিদ নির্মাণ 1566 সালে সমাপ্ত হয়; কমপ্লেক্সের ওয়াকফনামা 1570-71 সালে প্রণীত হয়। স্থাপনাটি স্থপতি সিনানের ইস্তানবুলের প্রাচীরের সবচেয়ে কাছের বড় কাজগুলোর একটি।", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["বাকির আইনদাতা সুলতান সুলায়মানের জন্য শোকগাথা রচনা", "7aa6665f"], "d": ["আইনদাতা সুলতান সুলায়মানের জিগেতভারে মৃত্যুর খবর এলে সে যুগের “সুলতানুশ শুআরা” বাকি অটোমান সাহিত্যের সবচেয়ে বিখ্যাত শোকগাথাগুলোর একটি রচনা করেন।", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["বাকির দ্বিতীয় সেলিমকে সিংহাসন আরোহণের কবিতা উপহার", "6027f034"], "d": ["দ্বিতীয় সেলিমের সিংহাসনে আরোহণের পরপরই বাকি নতুন সুলতানকে একটি “জুলুসিয়ে” (সিংহাসন আরোহণের কবিতা) উপহার দেন — টিডিভি অনুসারে আইনদাতার মৃত্যুতে রচিত শোকগাথার ঠিক পরে।", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["বুয়ুকচেকমেজে সেতু সমাপ্ত", "5f49b3c5"], "d": ["আইনদাতা সুলতান সুলায়মানের আদেশে শুরু হওয়া সেতু সুলতানের জিগেতভার অভিযানকালে মৃত্যুর পর পুত্র দ্বিতীয় সেলিম 1567-68 সালে সম্পন্ন করান। স্থপতি সিনান বুয়ুকচেকমেজে হ্রদ সাগরে মেশার স্থানে নির্মিত সেতুর বন্যায় ক্ষতিগ্রস্ত অংশগুলোও নিজে মেরামত করেন।", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["সেলিমিয়ে মসজিদের (এদির্নে) নির্মাণ শুরু", "07e18c9e"], "d": ["স্থপতি সিনান যাকে “কারিগরির কাজ” বলেছেন সেই সেলিমিয়ের নির্মাণ দ্বিতীয় সেলিমের নামে 1568 সালে শুরু হয়ে ছয় বছর চলে 1574 সালে সমাপ্ত হয় (সমাপ্তি কালপঞ্জিতে ইতিমধ্যে নথিভুক্ত)। আরাস্তার পশ্চিম দোকান ও শিশুবিদ্যালয় অবশ্য দ্বিতীয় সেলিমের মৃত্যুর পর তৃতীয় মুরাদের সময় দাউদ আগা সম্পন্ন করেন।", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["কিনালিজাদে আলি চেলেবির মৃত্যু — অটোমান নীতিদর্শনের ক্লাসিক গ্রন্থ আখলাক-ই আলাইয়ের লেখক", "dd921873"], "d": ["অটোমান নীতিদর্শনের সবচেয়ে পরিচিত ক্লাসিক গ্রন্থ আখলাক-ই আলাইয়ের লেখক কিনালিজাদে আলি চেলেবি আনাতোলিয়ার কাজিআসকার থাকা অবস্থায় 22 জানুয়ারি 1572 তারিখে মারা যান। তাঁর গ্রন্থের সত্তরটিরও বেশি পাণ্ডুলিপি ইস্তানবুলের গ্রন্থাগারগুলোতে রয়েছে।", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["পিয়ালে পাশা কমপ্লেক্স নির্মাণ", "75411278"], "d": ["দ্বিতীয় সেলিমের জামাতাদের একজন, নৌ-প্রধান পিয়ালে পাশা কমপ্লেক্সের জমি 1573 সালে কিনে স্থপতি সিনানকে দিয়ে নির্মাণ করান। কমপ্লেক্স মসজিদ, মাদ্রাসা, তেক্কে, সমাধিসৌধ, কবরস্থান, শিশুবিদ্যালয়, ঝরনা, বাজার ও হাম্মামখানায় গঠিত বিস্তৃত স্থাপনা হিসেবে নকশা করা হয়।", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["দ্রিনা (সোকোল্লু মেহমেদ পাশা) সেতু সমাপ্ত", "1d668c73"], "d": ["প্রধান উজির সোকোল্লু মেহমেদ পাশার পৃষ্ঠপোষকতায় স্থপতি সিনান নির্মিত সেতু শিলালিপির তারিখ অনুসারে 1577-78 সালে সমাপ্ত হয়; কিছু গবেষক নির্মাণ 1571-72 সালে শুরু হয়েছিল বলে মনে করেন। সেতুটি সোকোল্লুর জন্মস্থান ভিশেগ্রাদের প্রতি তাঁর অনুরাগের প্রতীক।", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["আজাপকাপি (সোকোল্লু মেহমেদ পাশা) মসজিদ নির্মাণ", "f7b57feb"], "d": ["উনকাপানি সেতুর শিশহানে প্রান্তের খুঁটির পাশে অবস্থিত মসজিদটি প্রধান উজির সোকোল্লু মেহমেদ পাশা স্থপতি সিনানকে দিয়ে নির্মাণ করান। এটি সোকোল্লুর নামে নির্মিত সিনানের দুটি মসজিদের একটি (অন্যটি কাদিরগার মসজিদ)।", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["তৃতীয় মুরাদের হুনারনামে রচনার ফরমান", "b125710d"], "d": ["তৃতীয় মুরাদ 2 জানুয়ারি 1578 তারিখের ফরমানে সেইয়িদ লোকমানকে ওসমান গাজী থেকে নিজের সময় পর্যন্ত সুলতানদের জীবন নিয়ে হুনারনামে রচনার আদেশ দেন; গ্রন্থের ক্ষুদ্রচিত্র নাক্কাশ ওসমান ও তাঁর দল প্রস্তুত করে।", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["জাল মাহমুদ পাশা মসজিদ সমাপ্ত", "732f75bc"], "d": ["জাল মাহমুদ পাশা ও শাহ সুলতানের 1574 সালের বিয়ের পর শুরু হওয়া কমপ্লেক্স নির্মাণে মসজিদের কাজ 1580 সালে সমাপ্ত হয়; মাদ্রাসাগুলো 1582 এবং ঝরনা 1590 পর্যন্ত চলে। কমপ্লেক্সটি আইয়ুপের ঢালে দুটি প্রতিসম মিনারসহ অনন্য নকশার জন্য দৃষ্টি আকর্ষণ করে।", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["হুনারনামের দ্বিতীয় খণ্ড সমাপ্ত", "70a1e741"], "d": ["হুনারনামের দ্বিতীয় খণ্ড 1588 সালের জানুয়ারিতে সমাপ্ত হয়; 65টি ক্ষুদ্রচিত্র নিয়ে এটি অটোমান ইতিহাসচর্চার তথ্যগত দিক থেকে সবচেয়ে মূল্যবান গ্রন্থগুলোর একটি হয়ে ওঠে। উভয় খণ্ডই নাক্কাশ ওসমানের কর্মশালায় চিত্রিত।", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["দাউদ আগার রাজকীয় প্রধান স্থপতি হওয়া", "8cdc7f53"], "d": ["স্থপতি সিনানের 1588 সালে মৃত্যুর পরের স্বল্প বিরতি থেকে শুরু করে দাউদ আগা 1592 সাল থেকে সরকারি দলিলে রাজকীয় প্রধান স্থপতি হিসেবে উল্লিখিত হতে থাকেন। সেলিমিয়ে কমপ্লেক্সের কিছু সম্পূরক অংশ এবং ইয়েনি মসজিদের প্রথম নির্মাণ হাতে নেওয়া দাউদ আগা সে যুগের অন্যতম গুরুত্বপূর্ণ স্থপতি।", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["ইয়েনি মসজিদের (এমিনোনু) ভিত্তি স্থাপন", "d3cddc01"], "d": ["তৃতীয় মেহমেদের মা সাফিয়ে সুলতানের পৃষ্ঠপোষকতায় মসজিদের ভিত্তি, মাটি খুঁটি দিয়ে মজবুত করে পাথরের খণ্ড দিয়ে স্থাপিত হয়। টিডিভির দুটি আলাদা নিবন্ধ এই ঘটনার জন্য ভিন্ন তারিখ দেয় (ইয়েনিজামি কমপ্লেক্স নিবন্ধে 9 এপ্রিল 1598, দাউদ আগা নিবন্ধে 23 আগস্ট 1597); এখানে ভবনের নিজস্ব বিশেষ নিবন্ধের তারিখ ভিত্তি হিসেবে নেওয়া হয়েছে।", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["দাউদ আগার মহামারিতে মৃত্যু ও ইয়েনি মসজিদের নির্মাণ অসমাপ্ত থাকা", "81f2cd04"], "d": ["ইয়েনি মসজিদ মাটি থেকে মাত্র এক জিরা উঁচু করার পর 1598 সালের সেপ্টেম্বরে মহামারিতে মারা যাওয়া দাউদ আগার স্থলে দালগিচ আহমেদ চাভুশ প্রধান স্থপতি নিযুক্ত হন। টিডিভি জানায়, মৃত্যুর তারিখ একটি তারিখ-কবিতার ওপর ভিত্তি করা বিকল্প বর্ণনায় 1599-1600 হিসেবেও এসেছে, নিশ্চিত তারিখ নির্ধারণ করা যায়নি।", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["আঙ্কারার সফ কাপড়ের ইউরোপে ব্যাপক রপ্তানি", "3f37018d"], "d": ["আঙ্কারায় বোনা সফ ও শালি কাপড় ইস্তানবুল, বুরসা, দামেস্ক, আলেপ্পোর মতো অভ্যন্তরীণ বাজারের পাশাপাশি ভেনিস, পোল্যান্ড, ইংল্যান্ড ও ফ্রান্সে রপ্তানি হতো। টিডিভি (TDV)-র দেওয়া উদাহরণে, 1599 সালে আঠারো জন ব্যবসায়ী 5.700.000 আকচে মূল্যের 162 বোঝা সফ কিনে আলেপ্পো ও ভেনিসে পাঠান।", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["তৃতীয় মেহমেদের মৃত্যুতে ইয়েনি মসজিদের নির্মাণ থেমে যাওয়া", "5acef053"], "d": ["পৃষ্ঠপোষক সাফিয়ে সুলতানের পুত্র তৃতীয় মেহমেদের 1603 সালে মৃত্যুর পর সাফিয়ে সুলতানকে পুরোনো প্রাসাদে পাঠানো হয় এবং ইয়েনি মসজিদের নির্মাণ অসমাপ্ত থাকে; স্থাপনাটি এই অবস্থায় প্রায় ষাট বছর সমাপ্ত না হয়ে অপেক্ষা করে।", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["কাতিব চেলেবির কাশফুজ জুনুনের জন্য আলেপ্পোয় গবেষণা শুরু", "094e6870"], "d": ["কাতিব চেলেবি পরবর্তীকালে গ্রন্থপঞ্জির মহাকীর্তি হতে চলা কাশফুজ জুনুনের উপকরণ সংগ্রহ 1633 সালে আলেপ্পোয় শুরু করেন। বিশ বছর স্থায়ী এই কাজে তিনি যেসব শহরে গেছেন সেগুলোর গ্রন্থাগার ও বইয়ের দোকান একে একে খুঁজে দেখেছেন।", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["ব্যঙ্গকবিতার কারণে নেফির মৃত্যুদণ্ড", "5e459c60"], "d": ["ব্যঙ্গকবিতার জন্য পরিচিত দিওয়ান কবি নেফি সিহাম-ই কাজা নামের ব্যঙ্গসংকলনের কারণে 1635 সালে চতুর্থ মুরাদের আদেশে মৃত্যুদণ্ড পান। প্রধান উজির বায়রাম পাশা তাঁকে সমর্পণ করেন; নেফিকে প্রাসাদের কাঠঘরে শ্বাসরোধ করে হত্যা করে লাশ সাগরে ফেলা হয়।", "e3b52153"]},
"OLAYLAR_EK14:1640-01-01:0":{"b": ["এভলিয়া চেলেবির প্রথম ভ্রমণযাত্রা — সেয়াহাতনামের সূচনা", "ca3ce3f9"], "d": ["এভলিয়া চেলেবি ইস্তানবুলের বাইরে প্রথম ভ্রমণ 1640 সালে বুর্সায় করে দশ খণ্ডের সেয়াহাতনামের ভিত্তি গড়ে দেওয়া চল্লিশ বছরের ভ্রমণজীবন শুরু করেন। লেখক 1684 নাগাদ মারা যাওয়ায় গ্রন্থ সমাপ্ত না হয়ে দশম খণ্ডে হঠাৎ শেষ হয়ে যায়।", "1db7969c"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["ব্যাপক নার্খ (মূল্যতালিকা) দফতর প্রণয়ন", "6c1e231b"], "d": ["নার্খ (মূল্যের সর্বোচ্চ সীমা) প্রথা অটোমানদের মধ্যে অনেক পুরোনো হলেও আজ পর্যন্ত টিকে থাকা সবচেয়ে ব্যাপক নার্খ দফতরটি 1640 সালের; খাদ্য, পোশাক, সেবা, মান ও স্বাস্থ্যবিধি শর্ত অন্তর্ভুক্ত করা এ দফতর টিডিভি (TDV)-র ভাষায় ‘পূর্ণাঙ্গ বাজার নিয়ন্ত্রণ আইনের মতো কাজ করেছে।’", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["কাতিব চেলেবির প্রথমবার জিহাননুমা লেখা শুরু", "554c6734"], "d": ["কাতিব চেলেবি পশ্চিমের ভৌগোলিক আবিষ্কারের মুখে অটোমান ভূগোলজ্ঞানের শূন্যতা পূরণের উদ্দেশ্যে 1648 সালে জিহাননুমার প্রথম রচনা শুরু করেন। কিছু ইউরোপীয় দেশ সম্পর্কে পর্যাপ্ত সূত্র না পাওয়ায় এই প্রথম সংস্করণ অসমাপ্ত থাকে।", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["সামরিক শ্রেণির একচেটিয়া দখলে এসে ইলতিজাম ব্যবস্থার পরিণত রূপ", "2c587934"], "d": ["ইলতিজাম পদ্ধতি (কর আদায় মূল্যের বিনিময়ে ব্যক্তিবিশেষকে ইজারা দেওয়া) পঞ্চদশ শতকের দ্বিতীয়ার্ধ থেকে প্রচলিত ছিল, কিন্তু ষোড়শ শতকের শুরু থেকে দ্রুত ছড়িয়ে পড়ছিল। টিডিভি (TDV)-র মতে, এ খাত পুরোপুরি সামরিক শ্রেণির সদস্যদের একচেটিয়া দখলে যাওয়ার প্রক্রিয়া 1650 সালে সম্পন্ন হয়; ইলতিজাম এভাবে তিমার ব্যবস্থার স্থলাভিষিক্ত প্রধান রাজস্ব পদ্ধতিতে পরিণত হয়।", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["কাতিব চেলেবির জিহাননুমা নতুন করে লেখা শুরু", "e9c68110"], "d": ["প্রথম রচনা অসমাপ্ত রাখা কাতিব চেলেবি 1654 সালের শেষে জিহাননুমা নতুন করে লিখতে শুরু করেন। এই দ্বিতীয় সংস্করণও সমাপ্ত হয়নি; গ্রন্থ ভান পর্যন্ত পৌঁছালে 1657 সালে লেখকের মৃত্যুতে তা অসমাপ্ত থাকে এবং কেবল 1732 সালে ইব্রাহিম মুতেফেররিকা এই অবস্থায় ছাপান।", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["ইয়েনি মসজিদ সমাপ্ত হয়ে উপাসনার জন্য খোলা", "d6d86c82"], "d": ["ষাট বছরের বেশি অসমাপ্ত থাকা ইয়েনি মসজিদের নির্মাণ হাতিজে তুরহান ভালিদে সুলতানের 1661 সালে নিযুক্ত প্রধান স্থপতি মেরেমেতচি মুস্তাফা আগার পরিচালনায় সমাপ্ত হয় এবং 30 অক্টোবর 1665 তারিখে আদায় করা জুমার নামাজের মাধ্যমে উপাসনার জন্য খুলে দেওয়া হয়।", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["চতুর্থ মেহমেদের এদির্নেতে খতনা উৎসবে দিনের পর দিন জিরিত খেলানো", "3638a5b6"], "d": ["চতুর্থ মেহমেদ 1675 সালে এদির্নেতে আয়োজিত শাহজাদাদের খতনা উৎসবে দিনের পর দিন চলা জিরিত প্রতিযোগিতার আয়োজন করেন; অটোমান রাজদরবারের জিরিত খেলায় সমর্থনের সবচেয়ে জাঁকালো দৃষ্টান্ত হিসেবে টিডিভির জিরিত নিবন্ধে বিশেষভাবে উল্লিখিত।", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["হাফিজ ওসমানের নিজস্ব লিপিশৈলী বিকাশ", "93081cb3"], "d": ["শেখ হামদুল্লাহর ধারার হাফিজ ওসমান 1679 সালে আকলাম-ই সিত্তে নিজস্ব, পরে “হাফিজ ওসমান ঘরানা” নামে পরিচিত নতুন শৈলী গড়ে তোলেন। এই শৈলী দুই আলাদা শাখায় আজ পর্যন্ত চলে এসেছে।", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["হাফিজ ওসমানের দ্বিতীয় মুস্তাফার লিপিশিক্ষক নিযুক্ত হওয়া", "d976cda4"], "d": ["সে যুগের সবচেয়ে দক্ষ লিপিকার বলে গণ্য হাফিজ ওসমান 1695 সালে সদ্য সিংহাসনে বসা দ্বিতীয় মুস্তাফার লিপিশিক্ষক নিযুক্ত হন। জীবদ্দশায় তিনি প্রায় পঞ্চাশজন লিপিকার তৈরি করেন এবং 25টি কোরআন শরিফ অনুলিপি করেন।", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["ইত্রির মৃত্যু", "62750526"], "d": ["তুর্কি সংগীতের সর্বশ্রেষ্ঠ সুরকারদের একজন বুহুরিজাদে মুস্তাফা ইত্রি এফেন্দি সমসাময়িক সূত্র অনুসারে 1711 সালে মারা যান। সেগাহ তাকবির ও রাস নাত প্রভৃতি রচনায় তিনি মসজিদ ও তেক্কে সংগীতের মহৎ কীর্তিগুলো রেখে যান।", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["নেদিমের তুলিপ যুগের কবিতার অগ্রদূত হিসেবে আত্মপ্রকাশ", "d3c40dbb"], "d": ["1718-1730 সালের তুলিপ যুগজুড়ে নেদিম প্রকাশের নিখুঁততা, সরলতার সন্ধান ও রসিক ভঙ্গিতে স্বতন্ত্র নতুন কাব্যশৈলী গড়ে তোলেন। নেভশেহিরলি দামাত ইব্রাহিম পাশার পরিমণ্ডলে বিকশিত এই শৈলী দিওয়ান কবিতায় দেশজকরণ ধারার সবচেয়ে বড় প্রতিনিধি বলে গণ্য।", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["লেভনির সুরনামে-ই ভেহবি চিত্রণ", "8c127866"], "d": ["রাজদরবারের নাক্কাশ লেভনি তৃতীয় আহমেদের শাহজাদাদের 1720 সালের খতনা উৎসব বর্ণনাকারী সুরনামে-ই ভেহবিকে 137টি ক্ষুদ্রচিত্রে চিত্রিত করেন। আগের নিদর্শনের বিপরীতে উৎসবকে কেবল আতমেইদানে বন্দি না রেখে শহরের বিভিন্ন কোণে চিত্রিত করে তিনি অটোমান ক্ষুদ্রচিত্রকলায় নতুন ধারণার সূচনা করেন।", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["একচেটিয়া-ভিত্তিক কারিগর ব্যবস্থা হিসেবে গেদিক ব্যবস্থার আনুষ্ঠানিক প্রতিষ্ঠা", "cd0f79a7"], "d": ["টিডিভি (TDV)-র মতে, গেদিক অধিকার ‘একচেটিয়া, বিশেষাধিকার ও এক ধরনের পেটেন্ট’ অর্থ পাওয়ার পদ্ধতিগত রূপান্তর 1727 থেকে লক্ষ করা যায়; কারিগরি পেশায় নির্দিষ্ট সংখ্যক ব্যক্তিকে কাজের অধিকার দেওয়া এ ব্যবস্থা প্রধানত ওয়াকফ সম্পত্তির দোকানগুলোতে ‘গেদিক অধিকার’ নামে স্থিতি লাভ করে।", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["পাত্রোনা খলিল বিদ্রোহে সাদাবাদ ধ্বংস", "8a30f9a0"], "d": ["25 সেপ্টেম্বর 1730 তারিখে ফেটে পড়া পাত্রোনা খলিল বিদ্রোহের সময় সাদাবাদের শত শত প্রাসাদ ও স্থাপনা ধ্বংস হয়; তুলিপ যুগের প্রতীক এই কমপ্লেক্স আর আগের জৌলুস ফিরে পায়নি।", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["পাত্রোনা খলিল বিদ্রোহের সময় নেদিমের মৃত্যু", "06bf909e"], "d": ["পাত্রোনা খলিল বিদ্রোহ ফেটে পড়ার সময় সেকবান আলি পাশা মাদ্রাসার অধ্যাপক ছিলেন নেদিম; বিদ্রোহ-পরবর্তী দিনগুলোতে তিনি মারা যান। মৃত্যুর দিন জানা নেই; তবে তাঁর পরিত্যক্ত সম্পত্তির কাস্সাম হুজ্জাত 15 রবিউল আখির 1143-এ (28 অক্টোবর 1730) প্রণীত হওয়ায় এর আগেই তিনি মারা গেছেন। মৃত্যুর কারণ নিয়ে নানা বর্ণনা আছে: কিছু সূত্র তাঁর ভয়জনিত রোগে (ইল্লেত-ই ওয়েহিমে) কিংবা মদ ও আফিমজনিত কম্পনরোগে মারা যাওয়ার কথা লেখে, মুস্তাকিমজাদে লেখেন বিদ্রোহের সময় ভয়ে ঘরের ছাদে উঠে সেখান থেকে পড়ে মারা গেছেন। তাঁর মৃত্যুতে তুলিপ যুগের সাংস্কৃতিক ঔজ্জ্বল্যও কার্যত শেষ হয়।", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["লেভনির মৃত্যু", "dd48b56e"], "d": ["অটোমান ক্ষুদ্রচিত্রকলার শেষ বড় প্রতিনিধি বলে গণ্য লেভনি 1732 সালে মারা যান। তাঁর কাজের বড় অংশ আজ তোপকাপি প্রাসাদ জাদুঘরে রয়েছে।", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["নুরুওসমানিয়ে মসজিদ ও কমপ্লেক্সের ভিত্তি স্থাপন", "397ec798"], "d": ["নুরুওসমানিয়ে কমপ্লেক্সের ভিত্তি প্রথম মাহমুদ 19 জানুয়ারি 1749 তারিখে স্থাপন করেন। এই স্থাপনা অটোমান স্থাপত্যে ইউরোপীয় বারোক শৈলীর প্রথম বড় প্রয়োগ বলে গণ্য এবং ধ্রুপদী কমপ্লেক্স নকশা থেকে স্পষ্টভাবে আলাদা।", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["নুরুওসমানিয়ে মসজিদ ও কমপ্লেক্সের উদ্বোধন", "15d83731"], "d": ["প্রথম মাহমুদের শুরু করা কিন্তু সমাপ্তি দেখে যেতে না পারা কমপ্লেক্সের উদ্বোধন তাঁর ভাই তৃতীয় ওসমানের সময় 5 ডিসেম্বর 1755 তারিখে হয়। উদ্বোধনকারী তৃতীয় ওসমানের উদ্দেশে মসজিদ “ওসমানের নুর” অর্থে নাম পায়।", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["মুহেন্দিসহানে-ই বাহরি-ই হুমায়ুনের উদ্বোধন", "a2fab1cd"], "d": ["অটোমানদের প্রথম আধুনিক নৌ প্রকৌশল বিদ্যালয় মুহেন্দিসহানে-ই বাহরি-ই হুমায়ুন ফরাসি আর্কাইভ দলিল অনুসারে 29 এপ্রিল 1775 তারিখে প্রথম আবদুলহামিদের সময়, প্রধান উজির দেরভিশ মেহমেদ পাশার শাসনকালে চালু হয়।", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["এসহাম ব্যবস্থার প্রবর্তন", "eabd8ece"], "d": ["কুচুক কায়নারজা চুক্তির আরোপিত 7,5 মিলিয়ন কুরুশের ক্ষতিপূরণের বোঝার মুখে 1775 সালে এসহাম ব্যবস্থা চালু হয়। মালিকানার (মালিকানে) সীমা ছাড়িয়ে যাওয়ার জন্য নকশা করা এ পদ্ধতিতে মুকাতা আয় অংশে ভাগ করা হতো, এবং মালিকানে থেকে ভিন্নভাবে নারী, অমুসলিম ও সাধারণ মানুষও অংশীদার হতে পারত।", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["হাম্মামিজাদে ইসমাইল দেদে এফেন্দির জন্ম", "c033f039"], "d": ["তুর্কি সংগীতের সবচেয়ে সৃজনশীল সুরকারদের একজন হাম্মামিজাদে ইসমাইল দেদে এফেন্দি 9 জানুয়ারি 1778 তারিখে ইস্তানবুলের শেহজাদেবাশি এলাকায় জন্মগ্রহণ করেন। জীবনে তিনি 500-এর বেশি রচনা সুরারোপ করেন; এর মধ্যে প্রায় 294টি আজ পর্যন্ত টিকে আছে।", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["মুহেন্দিসহানে-ই বেররি-ই হুমায়ুনের নির্মাণ শুরু", "4f5d521a"], "d": ["তৃতীয় সেলিমের নিজাম-ই জেদিদ সংস্কারের সবচেয়ে গুরুত্বপূর্ণ প্রতিষ্ঠানগুলোর একটি মুহেন্দিসহানে-ই বেররি-ই হুমায়ুনের নির্মাণ 14 জুলাই 1793 তারিখে শুরু হয়। ভবন 1795 সালের সেপ্টেম্বরে সমাপ্ত হয়ে শিক্ষার জন্য খুলে দেওয়া হয়; প্রতিষ্ঠানটি ইউরোপের সামরিক একাডেমি অনুসরণে গড়া অটোমানদের দ্বিতীয় সামরিক প্রকৌশল বিদ্যালয়।", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["তৃতীয় সেলিমের কিছু কারিগর সংঘের একচেটিয়া অধিকার বিলোপ শুরু", "008f4a7d"], "d": ["টিডিভি (TDV)-র ‘এসনাফ’ (কারিগর) নিবন্ধ অনুযায়ী, প্রতিষ্ঠার সময় থেকে আখি সংগঠনের সঙ্গে জড়িত অটোমান সংঘব্যবস্থায় ‘আখি বাবা’ ও ‘শেখ’-এর মতো কর্মকর্তারা উনবিংশ শতকের শুরু পর্যন্ত সংঘের নেতৃত্ব দিয়েছেন; অষ্টাদশ শতকে সংঘগুলোর একচেটিয়া অধিকারের ফলে দাম নার্খের (মূল্যসীমা) ওপরে উঠে অর্থনৈতিক চাপ সৃষ্টি হলে তৃতীয় সেলিম 1794 থেকে মৌলিক খাদ্য সংঘগুলোর একচেটিয়া অধিকার তুলে দিতে শুরু করেন।", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["দেদে এফেন্দির মুসাহিব-ই শেহরিয়ারি হিসেবে প্রাসাদে গ্রহণ", "0cb99ac3"], "d": ["তৃতীয় সেলিমের সময় একটি বুসেলিক সুরের মাধ্যমে সুলতানের মনোযোগ আকর্ষণ করা দেদে এফেন্দি 1812 সালে দ্বিতীয় মাহমুদ কর্তৃক “মুসাহিব-ই শেহরিয়ারি” (সুলতানের বিশেষ সভাসদ) পদে গৃহীত হন এবং অল্প সময় পরে মুয়াজ্জিনবাশি পদে উন্নীত হন।", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["অটোমান সাম্রাজ্যে প্রথম নিয়মিত আদমশুমারি", "4f004c6c"], "d": ["দ্বিতীয় মাহমুদ সেনাবাহিনীতে নেওয়ার মতো জনসংখ্যা নির্ণয়ের উদ্দেশ্যে প্রথমবার 1830 সালের শেষ দিকে নিয়মিত গণনা করান; শুধু পুরুষ জনসংখ্যা নথিভুক্ত হয় এবং আনাতোলিয়া-রুমেলিতে প্রায় 7,5 মিলিয়ন মানুষ নির্ণীত হয়। এরজুরুম ও ভানের মতো কিছু অঞ্চলে গণনা কেবল 1836 সালে শেষ করা সম্ভব হয়।", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["ফেসহানে-ই আমিরের প্রতিষ্ঠা", "971ab85a"], "d": ["1826 সালে জ্যানিসারি বাহিনী বিলুপ্ত হওয়ার পর গঠিত আসাকির-ই মানসুরে-ই মুহাম্মদিয়ে বাহিনীর ফেজ টুপির চাহিদা মেটাতে 1,5 মিলিয়ন কুরুশ পুঁজি নিয়ে 1833 সালে কাদিরগার জুন্দি ময়দানে ফেজ উৎপাদন শুরু হয়। স্থাপনাগুলো 1839 সালে আইয়ুপের হাতিজে সুলতান প্রাসাদে স্থানান্তরিত হয়; ফেসহানে অটোমান বস্ত্রশিল্পের ভিত্তি গড়ে তোলে।", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["চিকিৎসা বিদ্যালয়ের মেকতেব-ই তিব্বিয়ে-ই আদলিয়ে-ই শাহানে নাম গ্রহণ", "187d60f3"], "d": ["গালাতাসারায়ের এন্দেরুন আগালার বিদ্যালয় ভবনে স্থানান্তরিত চিকিৎসা বিদ্যালয় 14 মে 1839 তারিখে দ্বিতীয় মাহমুদের সফরের মাধ্যমে “মেকতেব-ই তিব্বিয়ে-ই আদলিয়ে-ই শাহানে” নাম পায়; প্রতিষ্ঠান এভাবে সামরিক-প্রশাসনিক বিদ্যালয়ের পরিচয়ে আনুষ্ঠানিক স্বীকৃতি পায়।", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["দেদে এফেন্দির হজ্জের সময় মিনায় মৃত্যু", "c3e613a2"], "d": ["হজ্জ ফরজ আদায়ে গিয়ে মিনায় কলেরায় আক্রান্ত হাম্মামিজাদে ইসমাইল দেদে এফেন্দি 29 নভেম্বর 1846 তারিখে মারা যান। 1824-1839 সালের মধ্যে সাতটি আলাদা মেভলেভি আয়িন সুরারোপ করা এই শিল্পীর মৃত্যুতে ধ্রুপদী অটোমান সংগীতের একটি যুগ শেষ হয়।", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["1850 সালের বাণিজ্য আইনবিধি গ্রহণ", "8ac085fd"], "d": ["তানজিমাত যুগের আইনি সংস্কারের অংশ হিসেবে পশ্চিমা রাষ্ট্রগুলো থেকে অনুবাদ ও গ্রহণের মাধ্যমে নতুন আইন নেওয়া হয়: দণ্ডবিধি 1840 সালে, বাণিজ্য আইন 1850 সালে, ভূমি আইন 1857 সালে কার্যকর হয়। বাণিজ্য আইনবিধি ছিল অটোমান বাণিজ্য আইনের প্রথম আধুনিক সংহিতাকরণ।", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["ক্রিমিয়ান তাতার ও ককেশীয় জনগোষ্ঠীর অটোমান ভূমিতে ব্যাপক অভিবাসন-স্রোতের সূচনা", "8832c06d"], "d": ["1859 সালে শেখ শামিল রুশদের হাতে বন্দি হওয়ার পর ক্রিমিয়ান তাতারদের সঙ্গে ককেশাস থেকে বহু সার্কাসীয় ও নোগাই মুহাজির অটোমান ভূমিতে আসতে শুরু করে। এ অভিবাসন-স্রোত 1877-78 সালের অটোমান-রুশ যুদ্ধের পর পর্যন্ত বিভিন্ন তীব্রতায় চলতে থাকে।", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["মুহাজিরিন কমিশন গঠন", "9717e77e"], "d": ["ককেশাস থেকে বাড়তে থাকা অভিবাসন-স্রোত পরিচালনার জন্য অটোমান সরকার 16 জানুয়ারি 1860 তারিখে মুহাজিরিন কমিশন গঠন করে। কমিশন আনাতোলিয়া, বলকান ও সিরিয়ার বসতি স্থাপন কার্যক্রম সমন্বয় করে এবং 1875 সাল পর্যন্ত কাজ চালায়।", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["ব্যাংক-ই ওসমানির ব্যাংক-ই ওসমানি-ই শাহানে (অটোমান ব্যাংক) রূপে পুনর্গঠন", "c3530456"], "d": ["1856 সালে ক্রিমিয়ান যুদ্ধের পর বৈদেশিক ঋণ পরিশোধ পরিচালনার জন্য লন্ডনকেন্দ্রিক, ব্রিটিশ পুঁজির ব্যাংক-ই ওসমানি প্রতিষ্ঠিত হয়েছিল। 1863 সালে ফরাসি-ব্রিটিশ যৌথ গোষ্ঠীকে ব্যাংক-ই ওসমানি-ই শাহানে (অটোমান ব্যাংক) নামে নতুন ব্যাংক গঠনের অনুমতি দেওয়া হয়; প্রতিষ্ঠানটি পরে ব্যাংকনোট ছাপার ক্ষমতাও পায়।", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["জেমইয়েত-ই তেদরিসিয়ে-ই ইসলামিয়ের প্রতিষ্ঠা", "77ad553a"], "d": ["দরিদ্র মুসলিম শিক্ষানবিশদের শিক্ষার দায়িত্ব নেওয়ার উদ্দেশ্যে 30 মার্চ 1864 তারিখে জেমইয়েত-ই তেদরিসিয়ে-ই ইসলামিয়ে প্রতিষ্ঠিত হয়; এ বেসামরিক সমিতি-উদ্যোগ দাতব্য প্রতিষ্ঠানের ঐতিহ্য আধুনিক বিদ্যালয় প্রকল্পে রূপান্তরের এক অগ্রণী দৃষ্টান্ত। সমিতি নয় বছর পর দারুশশাফাকা খুলবে।", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["1864 সালের ভিলায়েত বিধিমালায় মুখতার ও প্রবীণ পরিষদ ব্যবস্থার বিন্যাস", "1a2e8cf2"], "d": ["1864 সালের ভিলায়েত বিধিমালায় গ্রাম প্রশাসন নতুন করে সাজানো হয়; মুসলিম ও অমুসলিমরা একসঙ্গে বসবাসকারী গ্রামে প্রতিটি সম্প্রদায়ের নিজ মুখতার ও প্রবীণ পরিষদ (ইহতিয়ার মজলিস) নির্বাচনের বিধান গৃহীত হয়। প্রবীণ পরিষদ এভাবে প্রথমবার গ্রাম/মহল্লা প্রশাসনে আনুষ্ঠানিক স্থান পায়।", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["মহান সার্কাসীয় বহিষ্কারের চূড়ান্ত পর্ব", "b2ab1874"], "d": ["1858-1878 সালের মধ্যে, সবচেয়ে তীব্রভাবে 1861-1864 সালে রাশিয়ার ককেশাস দখলের ফলে 1,2-1,5 মিলিয়ন সার্কাসীয়কে জোরপূর্বক অটোমান ভূমিতে অভিবাসনে বাধ্য করা হয়। টিডিভি (TDV)-র মতে বহু গবেষক এ ঘটনাকে ‘আধুনিক ইতিহাসের প্রথম জাতিগত নির্মূল অভিযান’ বলে অভিহিত করেন।", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["1869 সালের মাআরিফ-ই উমুমিয়ে বিধিমালা প্রকাশ", "787f6022"], "d": ["1 সেপ্টেম্বর 1869 তারিখে প্রকাশিত মাআরিফ-ই উমুমিয়ে বিধিমালা প্রদেশ ও কেন্দ্রে সাধারণ শিক্ষা নিয়ন্ত্রণকারী প্রথম ব্যাপক দলিল হয়। বিধিমালা দ্বারা মজলিস-ই কেবির-ই মাআরিফ গঠিত হয়; সিবইয়ান মক্তবগুলোকে নিছক ধর্মীয় শিক্ষার পর্যায় থেকে বের করে লেখাপড়া শেখানোর দিকে পুনর্গঠনের কাজ এ ব্যবস্থায় শুরু হয়।", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["দারুশশাফাকা বিদ্যালয়ের শিক্ষাদান শুরু", "525c457c"], "d": ["জেমইয়েত-ই তেদরিসিয়ে-ই ইসলামিয়ের প্রতিষ্ঠিত দারুশশাফাকা 28 জুন 1873 তারিখে এতিম ও দরিদ্র মুসলিম শিশুদের বিনামূল্যে আবাসিকভাবে শিক্ষাদানের লক্ষ্যে কার্যত পাঠদান শুরু করে; ভর্তির সর্বোচ্চ বয়স দশ নির্ধারিত হয়।", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["1894 সালের ইস্তানবুল ভূমিকম্প", "7ae7f648"], "d": ["10 জুলাই 1894 তারিখে ইজমিত উপসাগরের উপকূলের কাছে ঘটা ভূমিকম্প ইস্তানবুলকে মারাত্মকভাবে আঘাত করে; ইস্তানবুলের প্রাচীর সহ বহু মসজিদ ও ঐতিহাসিক স্থাপনা ক্ষতিগ্রস্ত হয়। টিডিভি (TDV)-র ‘জেলজেলে’ (ভূমিকম্প) নিবন্ধ এ ভূমিকম্পকে 1509, 1719 ও 1766 সালের ভূমিকম্পের সঙ্গে মারমারা অঞ্চলে ব্যাপক প্রাণ ও সম্পদহানি ঘটানো ভূমিকম্পগুলোর মধ্যে গণ্য করে।", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["দারুলআজেজের উদ্বোধন", "a30baf31"], "d": ["দ্বিতীয় আবদুলহামিদের 1890 থেকে দেওয়া নির্দেশে প্রস্তুত দারুলআজেজে 2 ফেব্রুয়ারি 1896 তারিখে প্রধান উজির হালিল রিফাত পাশা উদ্বোধন করেন। অভিভাবকহীন শিশু, বৃদ্ধ ও অভাবীদের আশ্রয়দানকারী এ প্রতিষ্ঠান 200 শয্যার হাসপাতাল, কারখানা এবং মসজিদ-গির্জা-সিনাগগের মতো আলাদা উপাসনালয় নিয়ে তার সময়ের বৃহত্তম সামাজিক সহায়তা কমপ্লেক্স ছিল।", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["দারুলফুনুন-ই শাহানের স্থায়ী প্রতিষ্ঠান হিসেবে পুনঃপ্রতিষ্ঠা", "7d6d8fc4"], "d": ["দারুলফুনুন আগের দুটি ব্যর্থ প্রচেষ্টার (1863 ও 1870) পর 31 আগস্ট 1900 তারিখে দারুলফুনুন-ই শাহানে নামে স্থায়ী প্রতিষ্ঠান হিসেবে পুনঃপ্রতিষ্ঠিত হয়; টিডিভি এই তারিখকে বর্তমান তুর্কি বিশ্ববিদ্যালয় ব্যবস্থার প্রত্যক্ষ ভিত্তি বলে বর্ণনা করে।", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["সারবেদাররা সাবজেভার দখল করল — খোরাসানে ইলখানি-পরবর্তী প্রথম রাষ্ট্র", "af997fec"], "d": ["আবু সাইদের মৃত্যুতে (30 নভেম্বর 1335) ইলখানি কেন্দ্রীয় কর্তৃত্ব ভেঙে পড়লে খোরাসানে কর আদায়কারীদের বিরুদ্ধে জমে থাকা ক্ষোভ বাশতিনে বিস্ফোরিত হয়: আবদুর রাজ্জাক 13 মার্চ 1337 তারিখে বিদ্রোহ করেন, 9 সেপ্টেম্বর 1337 তারিখে (12 সফর 738) সাবজেভার দখল করেন। ‘সারবেদার’ — ‘মাথা ফাঁসিকাষ্ঠে’ — নামটি তাদের নিজেদেরই কথা, যা বোঝায় পরাজিত হলে ফাঁসি মেনে নেওয়ার সাহস তাদের ছিল।", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["মারআশি সৈয়দরা আমুল দখল করল — মাজেন্দারানে সৈয়দ কর্তৃত্ব", "c0e03266"], "d": ["সৈয়দ কিওয়ামুদ্দিন মারআশি, সারবেদারদের খোরাসানে খোলা পথ ধরে 760 (1359) সালে আমুল দখল করেন এবং কাস্পিয়ান সাগরের দক্ষিণ উপকূলে একটি সৈয়দ রাষ্ট্র গড়েন। রাজবংশ সারি, বারফুরুশ ও আশপাশে ছড়িয়ে পড়ে; তৈমুরের অভিযানে নড়বড়ে হয় এবং সাফাভি প্রথম শাহ আব্বাসের আমলে বিলুপ্ত হয়।", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["কারকিয়া রাজবংশ গিলানে প্রতিষ্ঠিত — কাস্পিয়ান উপকূলের শেষ স্বাধীন শাসক", "6e5f9db7"], "d": ["আলি কিয়া পরিবারসহ গিলানে ফিরে 773 (1371-72) সালে লাহিজান-কেন্দ্রিক কারকিয়া কর্তৃত্ব প্রতিষ্ঠা করেন; রাজবংশ কাস্পিয়ানের দক্ষিণ-পশ্চিম উপকূল দুই শতকেরও বেশি সময় নিজ হাতে রাখে এবং সাফাভি প্রথম শাহ আব্বাসের 1592 সালে অঞ্চলটি সংযুক্তি পর্যন্ত টিকে থাকে।", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["দারফুরে দাজু কর্তৃত্ব তুনজুরদের হাতে যাওয়া", "6eb22a2a"], "d": ["টিডিভি ইসলাম বিশ্বকোষের দারফুর নিবন্ধ অনুযায়ী অঞ্চলে প্রথম বসতি স্থাপনকারী ও প্রথম রাষ্ট্র গড়া হলো দাজু গোত্র; ত্রয়োদশ ও চতুর্দশ শতক জুড়ে এখানে কর্তৃত্ব করা দাজুরা বাণিজ্যিক আধিপত্য তুনজুরদের হাতে হারায়, পঞ্চদশ শতকে বিশেষত মধ্যাঞ্চলের পরিস্থিতি পুরোপুরি তুনজুরদের পক্ষে ঘুরে যায়।", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["স্পেন কর্তৃক বাদিস (পেনিওন দে ভেলেস) শৈলদুর্গ পুনর্দখল", "0dc52728"], "d": ["টিডিভি (TDV)-র সাদি রাজবংশ নিবন্ধ উল্লেখ করে যে স্পেনীয়দের বাদিস দখল মাগরিবের নৌ-কার্যক্রমে ভারী আঘাত ছিল (1564)। উত্তর মরক্কো উপকূলের এ শৈলঘাঁটি পশ্চিম ভূমধ্যসাগরে জলদস্যুতা ও অটোমান-স্পেনীয় প্রতিদ্বন্দ্বিতার ভিত্তি ছিল।", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["আল-আরাইশের (লারাশ) স্পেনের হাতে ছেড়ে দেওয়া", "7b8f6e27"], "d": ["সাদি রাজবংশ খণ্ডবিখণ্ড হওয়া গৃহযুদ্ধের বছরগুলোতে আটলান্টিক উপকূলের আল-আরাইশ বন্দর স্পেনের হাতে ছেড়ে দেওয়া হয়। টিডিভি (TDV)-র সাদি রাজবংশ নিবন্ধ এ সময়ে দেশ মারাকেশ (দক্ষিণ) ও ফেজ (উত্তর) আমিরাতে দ্বিধাবিভক্ত হওয়া এবং সিংহাসন-দ্বন্দ্বের পক্ষগুলোর বাইরে সাহায্য খোঁজার কথা উল্লেখ করে। বন্দরটি আশি বছরের কাছাকাছি স্পেনীয় হাতে থাকবে, 1689 সালে মওলায় ইসমাইল পুনর্দখল করবেন।", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["মামুরার (মেহদিয়া) স্পেনীয়দের হাতে যাওয়া", "c8fd494e"], "d": ["সেবু নদীর মোহনার মামুরা (মামুরে / মেহদিয়া) বন্দর 1614 সালে স্পেনীয়দের হাতে যায় এবং সান মিগুয়েল দে উলট্রামার নামে সুরক্ষিত করা হয়। টিডিভি (TDV)-র মওলায় ইসমাইল নিবন্ধ উল্লেখ করে যে বন্দরটি 1092 (1681) সালে আকস্মিক হামলায় স্পেনীয়দের হাত থেকে পুনরুদ্ধার করা হয় — অর্থাৎ স্পেনীয় কর্তৃত্ব সাতষট্টি বছর স্থায়ী হয়েছিল।", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["সাদি রাজবংশের অবসান — মরক্কোয় আলাউই (ফিলালি) যুগের সূচনা", "b1afa579"], "d": ["টিডিভি ইসলাম বিশ্বকোষ সাদি রাজবংশ নিবন্ধে এদের সংজ্ঞায়িত করে ‘মরক্কোয় শাসনকারী এক ইসলামি রাজবংশ (1511-1659)’ বলে। 1549 সালে ওয়াত্তাসি কর্তৃত্বের অবসান ঘটিয়ে সমগ্র মরক্কো একত্র করা, 1578 সালে ওয়াদি আল-মাখাজিনে পর্তুগিজ বাহিনী ধ্বংস করা এবং কোনো সময়ই অটোমানদের অধীন না হওয়া এ রাজবংশ দীর্ঘ সিংহাসন-দ্বন্দ্বের পর 1659 সালে শেষ হয়। তাদের স্থান নেন তাফিলালত থেকে আসা আলাউই (ফিলালি) শরিফরা; মওলায় রশিদ 1666 সালে ফেজ শহরে প্রবেশ করে নতুন রাজবংশ সুদৃঢ় করেন এবং তাঁর ভাই মওলায় ইসমাইল আটলান্টিক উপকূলের ইউরোপীয় ঘাঁটিগুলো পরিষ্কার করেন।", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["স্পেন কর্তৃক আল-হুসাইমা (আলুসেমাস) দ্বীপপুঞ্জ দখল", "954ca998"], "d": ["ভূমধ্যসাগর উপকূলের আল-হুসাইমা দ্বীপপুঞ্জ 1673 সালে স্পেনীয় নৌবহরের দখলে যায়। বাদিস ও সেউটার সঙ্গে এটি স্পেনের উত্তর মরক্কো উপকূলে ধরে রাখা এবং আজ পর্যন্ত হাতে থাকা ঘাঁটিগুলোর একটি। একই বছর মওলায় ইসমাইলের বড় ভাই মওলায় রশিদ মারাকেশে প্রবেশ করে জনগণের বাইয়াত নেন এবং ফিলালি কর্তৃত্ব দক্ষিণে সুসংহত হয় — উপকূলের এ ক্ষতি দেখায় যে অভ্যন্তরীণ ঐক্য তখনও বাহ্যিক সীমান্তে প্রতিফলিত হয়নি।", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["মওলায় ইসমাইল কর্তৃক আল-আরাইশ স্পেনীয়দের থেকে পুনরুদ্ধার", "a54bc6ee"], "d": ["টিডিভি (TDV)-র মওলায় ইসমাইল নিবন্ধ স্পষ্ট: ‘1100 সালে (1689) আরাইশ স্পেনীয়দের থেকে পুনরুদ্ধার করে 200 কামান হস্তগত করলেন, দুই বছর পর আসিলাও ফিরিয়ে নিলেন।’ এটি ফিলালি সুলতানের উপকূল-পরিষ্কার শৃঙ্খলের একটি কড়া — তাঞ্জা 1678 সালে ইংরেজদের থেকে, মামুরা 1681 সালে, আল-আরাইশ 1689 সালে, আসিলা 1691 সালে পুনরুদ্ধার হয়। আশি বছর আগে সাদি গৃহযুদ্ধে ছেড়ে দেওয়া বন্দর এভাবে মরক্কোয় ফিরে আসে।", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["দারফুর সুলতানাতের প্রতিষ্ঠা — কেইরা রাজবংশ ও সুলায়মান সোলোঞ্জ", "0fc1c112"], "d": ["টিডিভি (TDV)-র মতে দারফুর সুলতানাতের প্রতিষ্ঠা সপ্তদশ শতকের শেষ দিকে বুমু আল-কাসিরের অঞ্চল আক্রমণের পর সৃষ্ট বিশৃঙ্খলার পরে ঘটে। ফুররা সুলায়মান সোলোঞ্জের নেতৃত্বাধীন কিরা (কেইরা) বংশের অগ্রনায়কত্বে দাজু ও তুনজুরদের হাত থেকে কর্তৃত্ব নিয়ে সুদৃঢ় শাসন গড়ে তোলে। সুলায়মান সোলোঞ্জ 1695-1715 সালে শাসন করেন। দারফুরের সুলতানরা পরবর্তী শতকগুলোতে বাবে আলির সঙ্গে পত্রবিনিময় করতেন; আবদুলমেজিদ ও আবদুলআজিজ তাঁদের শাসন অনুমোদন করেন।", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["ফ্রান্সে প্রথম প্রজাতন্ত্র ঘোষণা — রাজতন্ত্রের অবসান", "d53d49b0"], "d": ["জাতীয় কনভেনশনের প্রথম অধিবেশনে রাজতন্ত্র বিলুপ্ত হয় এবং পরদিন প্রথম প্রজাতন্ত্র ঘোষিত হয়; নতুন পঞ্জিকার প্রথম বছর এ দিন থেকে গণনা শুরু হয়। অটোমানদের দিক থেকে সামনের পক্ষ বদলায়নি, কিন্তু পক্ষের চরিত্র বদলে যায়: তৃতীয় সেলিমের নিজাম-ই জেদিদ বছরগুলোতে ফ্রান্স আর কোনো রাজবংশ নয়, একটি শাসনব্যবস্থা ছিল, এবং 1798 সালে মিসরে অবতরণকারী ছিল সেই ব্যবস্থারই সেনাবাহিনী।", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["মহান কাবিলিয়ার পতন — লালা ফাতমা এন’সুমেরের বন্দিত্ব", "0f61ff08"], "d": ["টিডিভি (TDV)-র ‘আলজেরিয়া’ নিবন্ধ উল্লেখ করে যে পার্বত্য কাবিলিয়া (বিলাদুল কাবাইল) অঞ্চল 1853, 1854 ও 1857 সালের অভিযানের শেষে দখল হওয়ায় ফ্রান্সের আলজেরিয়া দখল অভিযান মূলত সম্পন্ন হয়। 1857 সালের অভিযান তিজি উজু ও আকবু সারি ভেঙে দেয়; প্রতিরোধের প্রতীক লালা ফাতমা এন’সুমের বন্দি হন। আমির আবদুলকাদিরের 1847 সালের আত্মসমর্পণের পর টিকে থাকা শেষ বড় প্রতিরোধকেন্দ্র এভাবে নিভে যায়।", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["আইন সালিহ (তিদিকেল্ট) ফরাসিদের দখলে", "1e28d1d0"], "d": ["সাহারার মাঝখানে তিদিকেল্ট মরূদ্যান-গুচ্ছের কেন্দ্র আইন সালিহ 29 ডিসেম্বর 1899 তারিখে ফরাসি বাহিনীর দখলে যায়। এটি আলজেরীয় উপকূল থেকে দক্ষিণে নামা ফরাসি বিস্তারের মরুভূমিতে পৌঁছানো প্রথম বড় পদক্ষেপ; দুই বছরের মধ্যে তুওয়াত ও গুরারাও একই পথ ধরবে।", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["তুওয়াত · গুরারা · তিদিকেল্ট মরূদ্যানের ফ্রান্সের সঙ্গে সংযুক্তি", "d412838b"], "d": ["আলজেরিয়ার দক্ষিণ-পশ্চিমের তুওয়াত, গুরারা ও তিদিকেল্ট মরূদ্যান-বলয় 21 ফেব্রুয়ারি 1901 তারিখে আনুষ্ঠানিকভাবে ফ্রান্সের সঙ্গে যুক্ত হয়। মরক্কোর সুলতান নামমাত্র দাবি করা এ কাফেলাপথের সংযোগস্থল — আদরার, তিমিমুন, রেগ্গান ও বেনি আব্বাস সহ — এভাবে আলজেরিয়ার অংশ হয়; মরক্কো ও ফরাসি আলজেরিয়ার মধ্যে সীমান্ত বিরোধের সূচনা এটিই।", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["বেশ্শারে (কোলোঁ-বেশার) ফরাসি ঘাঁটি স্থাপন", "4d44d252"], "d": ["মরক্কো সীমান্তের বেশ্শার মরূদ্যান 11 নভেম্বর 1903 তারিখে ফরাসি বাহিনীর দখলে যায় এবং কোলোঁ-বেশার নামে অগ্রবর্তী ঘাঁটিতে পরিণত হয়। তুওয়াত বলয় সংযুক্তির দুই বছর পরের এ পদক্ষেপ আলজেরিয়া থেকে মরক্কোর দিকে ফ্রান্সের অগ্রগতির শেষ কড়াগুলোর একটি; 1912 সালে মরক্কোকে আশ্রিত রাষ্ট্র করার পথ খুলে দেয়।", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["মস্কো প্রিন্সিপালিটির প্রতিষ্ঠা — প্রথম দানিল", "49549309"], "d": ["আলেক্সান্দর নেভস্কির কনিষ্ঠ পুত্র দানিল মস্কোকে স্বাধীন প্রিন্সিপালিটি হিসেবে শাসন করতে শুরু করেন। সেই সময় মস্কো ভ্লাদিমির-সুজদাল ভূমির একটি ছোট ও গুরুত্বহীন কেন্দ্র ছিল; রুশ ইতিহাসচর্চা এই তারিখকে পরবর্তী উত্থানের সূচনাবিন্দু ধরে।", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["কারেসি ও হামিদোগুল্লারি বেইলিকের প্রতিষ্ঠা", "3905da93"], "d": ["টিডিভি (TDV)-র কারেসিওগুল্লারি নিবন্ধ অনুযায়ী কারেসি বেগ, পিতা কালেম বেগের মৃত্যুতে ভেঙে পড়া সেলজুক সীমান্ত সংগঠনে স্বাধীনতা ঘোষণা করে 696 (1296-97) থেকে বালিকেসিরকে কেন্দ্র করেন এবং অল্প সময়ে এরদেক, বিগা, এদরেমিত, বের্গামা সহ মাইসিয়ার সবটুকু বাইজেন্টাইনদের থেকে নেন। একই বছর (1297) হামিদ বেগ উলুবোরলুকে সরকারকেন্দ্র করে হামিদোগুল্লারি বেইলিক প্রতিষ্ঠা করেন; ইস্পার্তা, বুরদুর, এইরদির ও ইয়ালভাচ ভেঙে পড়া সেলজুক সীমান্তাঞ্চল থেকে বেইলিকের প্রথম সীমানায় যুক্ত হয়। দুই বেইলিকই পশ্চিম আনাতোলিয়ায় একই পতনের — সেলজুক কেন্দ্রীয় কর্তৃত্ব ভেঙে পড়ার — ফল।", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["মস্কোর প্রিন্স দানিল কলোমনা ও সেরপুখভ মস্কোর সঙ্গে যুক্ত করলেন", "6d82dccd"], "d": ["দানিল রিয়াজান প্রিন্সিপালিটির কাছ থেকে কলোমনা (বন্দী রিয়াজান রাজকুমার মুক্তির জন্য দুর্গটি ছেড়ে দেন) ও সেরপুখভ নেন; মস্কো ওকা নদীতে পৌঁছায় এবং এটি মস্কো প্রিন্সিপালিটির প্রথম ভূমি সম্প্রসারণ ছিল।", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["মোজাইস্ক স্মোলেনস্ক প্রিন্সিপালিটির কাছ থেকে নিয়ে মস্কোর সঙ্গে যুক্ত হলো", "462055a0"], "d": ["মস্কো প্রিন্সিপালিটি মস্কো নদীর উচ্চ অববাহিকার মোজাইস্ক স্মোলেনস্কের কাছ থেকে নিয়ে পশ্চিম সীমান্ত লিথুয়ানিয়ার কাছাকাছি নিয়ে যায়।", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["পোলোৎস্ক প্রিন্সিপালিটি লিথুয়ানিয়ার গ্র্যান্ড ডাচিতে গেল", "04a26a6f"], "d": ["পোলোৎস্ক, ভিতেবস্ক ও আশপাশের অঞ্চল 1307 সাল পর্যন্ত রুশ প্রিন্সিপালিটি রাজবংশের মধ্যে ছিল; গেদিমিনাসের পূর্বে লিথুয়ানিয়ার পূর্বদিকে বিস্তার এই হস্তান্তরের মাধ্যমে স্পষ্ট হয় (অ্যাটলাসের বিবরণী তারিখ 1307; ভিতেবস্কের প্রকৃত হস্তান্তর ≈1320 বিতর্কিত)।", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["আয়দিনোগুল্লারি বেইলিকের প্রতিষ্ঠা — ইজমির, আয়াসুলুক, তিরে দখল", "69a021ae"], "d": ["টিডিভি (TDV)-র আয়দিনোগুল্লারি নিবন্ধ অনুযায়ী মুবারিজুদ্দিন গাজি মেহমেদ বেগ, গেরমিয়ানোগুল্লারি সীমান্ত বেগ সাসা বেগের কাছ থেকে এ অঞ্চল নিয়ে 1308 সালে আয়দিন-ইলিতে কর্তৃত্ব স্থাপন করেন; ইজমিরের মুসলিম অংশ আয়াসুলুক (সেলচুক), তিরে ও বোদেমিয়ার সঙ্গে জয় করেন। আয়াসুলুককে নৌঘাঁটি করেন এবং দখলকৃত ভূমি পাঁচ পুত্রের মধ্যে ভাগ করে দেন — বেইলিক পরবর্তী দশকগুলোতে, বিশেষত পুত্র উমুর বেগের আমলে, এজিয়ান নৌ-কর্মকাণ্ডে নির্ধারক শক্তি হবে।", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["আনাতোলীয় সেলজুক রাষ্ট্রের কার্যত অবসান — ইলখানির সরাসরি শাসন", "00f85ecb"], "d": ["টিডিভি (TDV)-র দ্বিতীয় মাসউদ নিবন্ধ অনুযায়ী দীর্ঘ অসুস্থতার পর 708 (1308) সালে কায়সেরিতে মারা যাওয়া দ্বিতীয় গিয়াসুদ্দিন মাসউদ সর্বসম্মত মতে আনাতোলীয় সেলজুক রাষ্ট্রের শেষ শাসক — তাঁর মৃত্যুর পর সিংহাসনে বসানো প্রার্থীরা না অভ্যন্তরীণ কর্তৃপক্ষের, না ইলখানির স্বীকৃতি পেতে পেরেছিল। মাসউদের সুলতানাত জুড়েই অঞ্চলটি কার্যত ইলখানি কর্মকর্তাদের শাসনে ছিল; তাঁর মৃত্যুতে এ সরাসরি শাসন কনিয়া, নিগদে ও আকসারায়ের মতো কেন্দ্রে আনুষ্ঠানিক আবরণও হারায়।", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["জান্দারোগুল্লারি বেইলিকের কাস্তামনু-চানকিরি-বার্তিন-সাফরানবোলুতে বিস্তার", "64e39ad0"], "d": ["টিডিভি (TDV)-র জান্দারোগুল্লারি নিবন্ধ অনুযায়ী বেইলিকটি চতুর্দশ শতকের শুরুতে কাস্তামনু-সিনোপ অঞ্চলে শামসুদ্দিন ইয়ামান জান্দার প্রতিষ্ঠা করেন, যাঁকে ইলখানি শাসক গেইখাতু এফলানি ও আশপাশ ইকতা হিসেবে দিয়েছিলেন; উৎসের অপ্রতুলতার কারণে প্রতিষ্ঠার সঠিক তারিখ জানা নেই। জান্দারের উত্তরসূরি সুলায়মান বেগ চোবানোগুল্লারি বেইলিকের স্থলাভিষিক্ত শাসক হিসেবে উল্লিখিত — অর্থাৎ কাস্তামনু ও চানকিরি অঞ্চল চোবানোগুল্লারি থেকে, বার্তিন-সাফরানবোলু-এফলানি রেখা ইলখানির সরাসরি শাসন থেকে জান্দারোগুল্লারির হাতে গেছে।", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["সেন্ট জন (হসপিটালার) নাইটদের রোডস ও দোদেকানিজ বিজয়", "67885b4b"], "d": ["টিডিভি (TDV)-র রোডস নিবন্ধ উল্লেখ করে যে দ্বীপটি 1309 সালে সেন্ট জন নাইটদের (হসপিটালার/ইসবিতারিয়ে) হাতে যায়; আদর্শ হসপিটালার ইতিহাস (দ্রষ্টব্য: J. Riley-Smith, The Knights Hospitaller) বিশদ করে যে অবরোধ 1306 সালের গ্রীষ্মে শুরু হয়, বাইজেন্টাইন সহায়তায় দীর্ঘ প্রতিরোধ করা রোডস শহর গ্র্যান্ড মাস্টার ফুলক দ্য ভিলারের বাহিনীর হাতে কেবল 15 আগস্ট 1310 তারিখে পতিত হয়। দ্বীপ এ তারিখ থেকে 1522 সালে অটোমান বিজয় পর্যন্ত নাইটদের কেন্দ্র থাকবে; আশপাশের দোদেকানিজ দ্বীপপুঞ্জও একই প্রক্রিয়ায় বাইজেন্টাইনদের থেকে হসপিটালার কর্তৃত্বে গেছে।", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["লিভোনীয় নাইটরা লিথুয়ানিয়ার কাছ থেকে দ্যুনাবুর্গ দুর্গ ফিরিয়ে নিল", "92119516"], "d": ["লিথুয়ানীয়রা 1281 সালের কাছাকাছি সময়ে ইয়ের্সিকা দখল করে সেটি অর্ডারের দ্যুনাবুর্গ দুর্গের সঙ্গে বদল করেছিল। দুর্গটি 1313 সালে আবার লিভোনীয় নাইটদের হাতে আসে এবং অর্ডারের কমান্ডারি কেন্দ্র হিসেবে থেকে যায়।", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["ইস্তানকোয়ের (কস) সেন্ট জন নাইটদের দখল", "445666f7"], "d": ["টিডিভি (TDV)-র ইস্তানকোয় নিবন্ধ অনুযায়ী সেন্ট জন নাইটরা রোডসে বসতি করার পর ইস্তানকোয়ও দখল করে (1315) নতুন দুর্গ নির্মাণ করে। দ্বীপ এভাবে 1523 সাল পর্যন্ত চলা নাইট কর্তৃত্বে আসে; 1310 সালে রোডস শহরের পতনের পর কস কোন শাসনে ছিল তা টিডিভি-তে বিস্তারিত নেই।", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["মেট্রোপলিটন আসন মস্কোয় স্থানান্তরিত হলো", "d20099f8"], "d": ["রুশ অর্থোডক্স চার্চের প্রধান মেট্রোপলিটন পিওতর তাঁর ধর্মীয় কেন্দ্র মস্কোয় সরিয়ে নেন। এটি মস্কোর কেবল রাজনৈতিক নয়, ধর্মীয় কেন্দ্র হিসেবেও উত্থানের সূচনা ছিল এবং প্রিন্সিপালিটির বৈধতা জোরদার করে।", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["লিভোনীয় অর্ডার রিগা শহরের অধিরাজ হলো", "21453047"], "d": ["লিথুয়ানিয়ার গ্র্যান্ড ডিউক ভিতেনিস ও গেদিমিনাসের সমর্থনে অর্ডারের বিরুদ্ধে লড়া রিগার আর্চবিশপ-এলাকা ও শহর 1330 সালে পরাজিত হয়; লিভোনীয় অর্ডার শহরের অধিরাজ হয়। 1452 সালের সালাসপিলস চুক্তির মাধ্যমে রিগা অর্ডার ও আর্চবিশপের যৌথ অধিরাজত্বের অধীনে যায়।", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["এরেতনা বেইলিকের প্রতিষ্ঠা — ইলখানি-পরবর্তী মধ্য আনাতোলিয়া", "a67bacd9"], "d": ["টিডিভি (TDV)-র এরেতনোগুল্লারি নিবন্ধ অনুযায়ী উইঘুর বংশোদ্ভূত ইলখানি কর্মকর্তা আলাউদ্দিন এরেতনা, ইলখানি শাসক আবু সাইদ বাহাদুর খানের 1335 সালে মৃত্যুর পর আনাতোলিয়ার ইলখানি নায়েবি পদকে কার্যত স্বাধীন শাসনে রূপান্তর করেন; প্রথমে মামলুক সুলতানের নায়েব পরিচয়ে দেখা দিয়ে 1340 সালে খুতবা থেকে মামলুকের নাম বাদ দেন এবং 1341 সালের কাছাকাছি পূর্ণ স্বাধীনতা ঘোষণা করেন। কেন্দ্র প্রথমে সিভাস, পরে কায়সেরি হওয়া এ বেইলিক মৃত্যু (1352) পর্যন্ত আমাসিয়া, তোকাত, চোরুম, নিগদে, আকসারায় ও এরজিনকান জুড়ে বিস্তৃত মধ্য আনাতোলীয় কর্তৃত্ব গড়ে তোলে এবং 1381 সালে কাজি বুরহানুদ্দিনের হাতে শেষ হয়।", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["হ্যাবসবুর্গদের কার্নিওলা ও কারিন্থিয়া (Ljubljana) দখল", "039918d3"], "d": ["কারিন্থিয়ার ডিউক ও টিরলের কাউন্ট ষষ্ঠ হাইনরিখ 1335 সালের 2 এপ্রিল টিরল দুর্গে উত্তরাধিকারী না রেখে মারা যান; 1330 সালের 23 নভেম্বর বাভারিয়ার লুডভিগের সঙ্গে গোপনে হওয়া চুক্তি অনুসারে হ্যাবসবুর্গ ভাই দ্বিতীয় আলব্রেখট ও চতুর্থ অটো সম্রাটের সনদের মাধ্যমে কারিন্থিয়া ডাচি এবং তার অধীন কার্নিওলা (বর্তমান লুব্লিয়ানা যে অঞ্চলের অন্তর্ভুক্ত) লাভ করেন; টিরল অবশ্য হাইনরিখের কন্যার মাধ্যমে পৃথক থেকে যায়। এটি ছিল আল্পস অঞ্চলে হ্যাবসবুর্গদের সম্প্রসারণের প্রথম বড় পদক্ষেপগুলোর একটি এবং কার্নিওলা 1918 সাল পর্যন্ত (মাঝে মাঝে ছেদসহ) হ্যাবসবুর্গ/অস্ট্রীয় হাতে থাকবে।", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["জালায়িরি রাষ্ট্রের প্রতিষ্ঠা — ইলখানি-পরবর্তী আজারবাইজান", "a13ada90"], "d": ["টিডিভি (TDV)-র জালায়িরিলার নিবন্ধ অনুযায়ী ইলখানি আমির নোয়ানের নাতি হাসান-ই বুযুর্গ, ইলখানি শাসক আবু সাইদ বাহাদুর খানের মৃত্যুতে শুরু হওয়া সিংহাসন-দ্বন্দ্বের সুযোগ নিয়ে 1340 সালে তাব্রিজকেন্দ্রিক স্বাধীন রাষ্ট্র গড়েন। জালায়িরিরা এভাবে আজারবাইজান ও আশপাশে ইলখানি-পরবর্তী শূন্যতা পূরণকারী প্রথম বড় রাজবংশ হয়; উত্তরসূরি উয়াইসের আমলে (1356-1374) তাদের ভূমি মসুল ও দিয়ারবাকির পর্যন্ত বিস্তৃত হবে।", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["নিঝনি নভগোরদ-সুজদাল গ্র্যান্ড প্রিন্সিপালিটি প্রতিষ্ঠিত — খান কনস্তান্তিন ভাসিলিয়েভিচকে সনদ দিলেন", "c69f5198"], "d": ["গোল্ডেন হোর্ডের খান উজবেক (সূত্রে উজবেক/জানিবেক) সুজদালের রাজকুমার কনস্তান্তিন ভাসিলিয়েভিচকে নিঝনি নভগোরদ-গোরদেৎস প্রিন্সিপালিটি দেন; প্রিন্সিপালিটিটি মস্কোর প্রতিদ্বন্দ্বী হয় এবং 1392 সালে প্রথম ভাসিলির হাতে মস্কোর সঙ্গে যুক্ত হয়।", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["ডেনমার্ক উত্তর এস্তোনিয়া (রেভাল ও নারভা) লিভোনীয় অর্ডারের কাছে বিক্রি করল", "6861ba55"], "d": ["ডেনমার্ক রাজ্য উত্তর এস্তোনিয়ার ভূমি রেভাল ও নারভাসহ লিভোনীয় অর্ডারের কাছে বিক্রি করে। অঞ্চলটি লিভোনীয় যুদ্ধ পর্যন্ত অর্ডারের হাতে ছিল।", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["বোলোতোভো চুক্তি — নভগোরদ প্সকভের স্বাধীনতা স্বীকার করল", "08eca44d"], "d": ["নভগোরদ প্সকভকে 'ছোট ভাই' হিসেবে স্বীকৃতি দেয়; প্সকভ নিজস্ব ভেচে ও পসাদনিক নিয়ে স্বাধীন নগর-প্রজাতন্ত্র হিসেবে 1510 সালে মস্কোর সঙ্গে যুক্ত হওয়া পর্যন্ত টিকে ছিল।", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["প্রথম ভাসিলি নিঝনি নভগোরদ-সুজদাল প্রিন্সিপালিটি মস্কোর সঙ্গে যুক্ত করলেন", "5ecf441b"], "d": ["খান তোখতামিশের কাছ থেকে পাওয়া সনদে প্রথম ভাসিলি নিঝনি নভগোরদ, গোরদেৎস ও সুজদাল মস্কোর সঙ্গে যুক্ত করেন; ভলগা ও ওকা অববাহিকায় মস্কোর বিস্তার শুরু হয়।", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["ভিতাউতাস স্মোলেনস্ক নিলেন — স্মোলেনস্ক প্রিন্সিপালিটি লিথুয়ানিয়ার সঙ্গে যুক্ত হলো", "1a68300c"], "d": ["ভিতাউতাস স্মোলেনস্ক দখল করেন; শহরটি 1514 সালে মস্কোর হাতে যাওয়া পর্যন্ত লিথুয়ানিয়ার গ্র্যান্ড ডাচিতে ছিল।", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["বাগদাদের কারাকোইউনলুর হাতে যাওয়া — জালায়িরি সুলতান আহমদের পরাজয়", "a42ebe92"], "d": ["টিডিভি (TDV)-র কারাকোইউনলুলার নিবন্ধ অনুযায়ী কারা ইউসুফ 28 রবিউস সানি 813 (30 আগস্ট 1410) তারিখে তাব্রিজের কাছে জালায়িরি সুলতান আহমদকে ভারী পরাজয়ে ফেলেন; সুলতান আহমদের মৃত্যুর পর 814 (1411) সালে তাঁর পুত্র পির বুদাককে তাব্রিজে সুলতান ঘোষণা করেন এবং একই বছর বড় ছেলে শাহ মেহমেদ বাগদাদ জয় করেন। এভাবে প্রায় এক শতক জালায়িরি রাজধানী থাকা বাগদাদ, আশপাশের বসরা-মসুল-কিরকুক রেখাসহ, কারাকোইউনলু কর্তৃত্বে আসে।", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["এরজিনকান ও কেমাহ আকোইউনলুর হাতে গেল — কারাইউলুক ওসমান বেগ", "122460d4"], "d": ["কারা ইউসুফের মৃত্যুর পর এরজিনকানবাসীর ইচ্ছায় মুতাহহারতেনের নাতি ইয়ার আলি শহরের শাসক হয়েছিলেন। তাঁর সময়ে আকোইউনলু বেগ কারাইউলুক ওসমান এরজিনকান দখল করে আকোইউনলু ভূমির সঙ্গে যুক্ত করেন। এরপর থেকে এরজিনকান কখনো আকোইউনলু ও কারাকোইউনলুর মধ্যে, কখনো আকোইউনলু শাহজাদাদের মধ্যে হাতবদল হওয়া স্থান হয়ে ওঠে।", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["কাজান খানাতের প্রতিষ্ঠা — উলুগ মুহাম্মদ খানের গোল্ডেন হোর্ড থেকে বিচ্ছেদ", "335a7408"], "d": ["টিডিভি (TDV)-র কাজান খানাত নিবন্ধ অনুযায়ী গোল্ডেন হোর্ডের রাজধানী সারায়ে সিংহাসন হারানো উলুগ মুহাম্মদ খান পরিবার ও প্রায় 3000 সৈন্য নিয়ে প্রথমে বেলেভে সরে যান, 1437-1438 সালে রুশ নেজ দ্বিতীয় ভাসিলির সঙ্গে লড়েন এবং এরপর কাজান শহরে বসতি করেন; স্থানীয় জনগণের সমর্থনে এখানে নতুন খানাতের ভিত্তি স্থাপন করেন। টিডিভি উল্লেখ করে যে প্রতিষ্ঠা-প্রক্রিয়া 1437-1445 সালের মধ্যে সম্পন্ন হয় এবং খানাত 1445 থেকে পূর্ণ স্বাধীন মর্যাদা লাভ করে — মানচিত্র এ প্রক্রিয়ার সূচনা, উলুগ মুহাম্মদের কাজানে বসতি স্থাপনের 1438 সালকে ভিত্তি ধরেছে।", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["ক্রিমিয়ান খানাতের প্রতিষ্ঠা — হাজি গিরায়ের গোল্ডেন হোর্ড থেকে স্বাধীন হওয়া", "5728223e"], "d": ["টিডিভি (TDV)-র ক্রিম নিবন্ধ অনুযায়ী ক্রিমিয়ান খানাত চতুর্দশ শতকের দ্বিতীয়ার্ধে গোল্ডেন হোর্ডের সিংহাসন-দ্বন্দ্বে খণ্ডবিখণ্ড হওয়ার ফল হিসেবে আবির্ভূত হয়; খানাতের প্রকৃত প্রতিষ্ঠাতা হাজি গিরায়ের মুদ্রিত সবচেয়ে পুরোনো মুদ্রায় 845 (1441-42) তারিখ রয়েছে এবং এটিকে খানাতের আনুষ্ঠানিক প্রতিষ্ঠার তারিখ ধরা হয়। একই বছর হাজি গিরায় মস্কোর সঙ্গে বন্ধুত্ব গড়ে ক্রিমিয়ায় নিজের অবস্থান সুদৃঢ় করেন এবং শিরিন গোত্রসহ স্থানীয় বেগ পরিবারগুলো তাঁর পক্ষে যোগ দেয়।", "dbd052d0"]}
});
